INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('e9169/kopilot/gh-cli', 'gh-cli', 'e9169', 'kopilot', 'community', 'gh-cli e9169 kopilot community gh-cli 是一个 AI 驱动的 Kubernetes 集群管理 agent，支持自然语言查询和管理 gh-cli は AI駆動のKubernetesクラスタ管理エージェントで、自然言語によるクエリと管理をサポート gh-cli는 AI 기반의 Kubernetes 클러스터 관리 에이전트로 자연어 쿼리 및 관리를 지원 Gh-CLI es un agente de gestión de clústeres de Kubernetes con IA que permite monitorizar, consultar y gestionar varios clústeres de forma natural Gh-CLI est un agent de gestion de cluster Kubernetes avec IA qui permet de surveiller, d''interroger et de gérer plusieurs clusters de manière naturelle Gh-CLI ist ein Kubernetes-Cluster-Management-Agent mit KI, der es ermöglicht, mehrere Cluster zu überwachen, abzufragen und zu verwalten O gh-cli é um agente de gerenciamento de cluster Kubernetes baseado em IA, que permite monitorar, consultar e gerenciar múltiplos clusters por meio de linguagem natural Агент gh-cli представляет собой продукт искусственного интеллекта для управления кластером Kubernetes, позволяющий отслеживать, запрашивать и управлять несколькими кластерами посредством естественного языка وكلاء gh-cli هو وسيط ذكاء اصطناعي لمجموعة كلاستر Kubernetes، يتيح مراقبة واستعلام وإدارة مجموعات كلاستر متعددة من خلال لغة طبيعية 🤖 AI-powered Kubernetes cluster management agent built with GitHub Copilot SDK. Monitor, query, and manage multiple clusters through natural language. Features smart cost optimization, parallel health checks, and safe kubectl execution. Kubernetes 集群管理 AI 驱动 自然语言查询 成本优化 并行健康检查 安全的 kubectl 🤖 AI-powered Kubernetes cluster management agent built with GitHub Copilot SDK. Monitor, query, and manage multiple clusters through natural language. Features smart cost optimization, parallel health checks, and safe kubectl execution.');
