INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/happyflow-generator', 'happyflow-generator', 'aiskillstore', 'marketplace', 'community', 'happyflow-generator aiskillstore marketplace community HappyFlow 生成器技能是用于自动化 API 测试的工具，支持从 OpenAPI 规范和 GraphQL 模式生成 Python 测试脚本 HappyFlow ジェネレータースキルは、OpenAPI仕様とGraphQLスキーマからPythonテストスクリプトを自動生成することでAPIテストの自動化を支援するツールです HappyFlow 생성기 스킬은 OpenAPI 사양 및 GraphQL 스키마에서 Python 테스트 스크립트를 자동으로 생성하여 API 테스트 자동화를 지원하는 도구입니다 El generador HappyFlow automatiza las pruebas de API generando y ejecutando scripts de prueba de Python desde especificaciones OpenAPI y esquemas GraphQL. Le générateur HappyFlow automatise les tests d''API en générant et en exécutant des scripts de test Python à partir de spécifications OpenAPI et de schémas GraphQL. Der HappyFlow-Generator automatisiert API-Tests, indem er Python-Testskripte aus OpenAPI-Spezifikationen und GraphQL-Schemata generiert und ausführt. O Gerador HappyFlow é uma ferramenta de automação de testes de API que gera e executa scripts de teste Python a partir de especificações OpenAPI e esquemas GraphQL, garantindo a ordem correta de dependência. Генератор HappyFlow - это инструмент для автоматизации тестирования API, который генерирует и выполняет скрипты тестирования Python из спецификаций OpenAPI и схем GraphQL, обеспечивая правильный порядок зависимостей. مُولد HappyFlow هو أداة أتمتة اختبار واجهة برمجة التطبيقات التي تولد وتنفذ نصوص اختبار بايثون من مواصفات OpenAPI ومخططات GraphQL، مما يضمن الترتيب الصحيح للتفاعلات. Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. API 测试 自动化测试 Python 测试脚本 OpenAPI 规范 GraphQL 模式 代码执行 Web 请求 文件操作 Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/gtd', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'gtd', 0, 0, 80, '2026-02-20T04:13:19.578Z', '2026-02-20T04:57:39.495Z', '61c7adb4a70f3e66197fdb3b747d860e475628ccba6c23519a94e5cd5a79c8c6', '{"id":"majiayu000/claude-skill-registry/gtd","name":"gtd","description":{"zh":"GTD 跑步器技能可以自动执行任务，提高开发效率。它可以读取GTD.md文件，提取任务项，并自动执行","ja":"GTDランナー スキルは自動タスク実行を実現し、開発効率を向上させます。GTD.mdファイルを読み込み、タスクアイテムを抽出し、自動実行します","ko":"GTD 러너 스킬은 자동 태스크 실행을 구현하여 개발 효율성을 향상시킵니다. GTD.md 파일을 읽고 태스크 항목을 추출하여 자동 실행합니다","es":"GTD Runner es una habilidad que ejecuta tareas de forma autónoma a partir de elementos de GTD.md. Permite automatizar flujos de trabajo y aumentar la productividad","fr":"GTD Runner est une compétence qui exécute des tâches de manière autonome à partir d''éléments de GTD.md. Elle permet d''automatiser les flux de travail et d''augmenter la productivité","de":"GTD Runner ist eine Fähigkeit, die Aufgaben automatisch aus GTD.md-Elementen ausführt. Sie ermöglicht die Automatisierung von Arbeitsabläufen und die Steigerung der Produktivität","pt":"O GTD Runner é uma habilidade de código que executa tarefas de forma autônoma a partir de itens do GTD.md, classificando e planejando ações.","ru":"GTD Runner - это навык кода, который выполняет задачи автоматически из элементов GTD.md, классифицируя и планируя действия.","ar":"GTD Runner هي مهارة الكود التي تنفذ المهام بشكل ذاتي من عناصر GTD.md، وتصنف و تخطط الإجراءات.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"GTD 跑步器技能：自动执行任务","ja":"GTDランナー スキル：自動タスク実行","ko":"GTD 러너 스킬: 자동 태스크 실행","es":"GTD Runner: Ejecución Autónoma de Tareas","fr":"GTD Runner: Exécution Autonome de Tâches","de":"GTD Runner: Autonomer Task-Ausführung","pt":"GTD Runner: Execução Autônoma de Tarefas","ru":"GTD Runner: Автономное выполнение задач","ar":"GTD Runner: تنفيذ مهام ذاتي","en":"gtd"},"description":{"zh":"GTD 跑步器技能可以自动执行任务，提高开发效率。它可以读取GTD.md文件，提取任务项，并自动执行","ja":"GTDランナー スキルは自動タスク実行を実現し、開発効率を向上させます。GTD.mdファイルを読み込み、タスクアイテムを抽出し、自動実行します","ko":"GTD 러너 스킬은 자동 태스크 실행을 구현하여 개발 효율성을 향상시킵니다. GTD.md 파일을 읽고 태스크 항목을 추출하여 자동 실행합니다","es":"GTD Runner es una habilidad que ejecuta tareas de forma autónoma a partir de elementos de GTD.md. Permite automatizar flujos de trabajo y aumentar la product...","fr":"GTD Runner est une compétence qui exécute des tâches de manière autonome à partir d''éléments de GTD.md. Elle permet d''automatiser les flux de travail et d''au...","de":"GTD Runner ist eine Fähigkeit, die Aufgaben automatisch aus GTD.md-Elementen ausführt. Sie ermöglicht die Automatisierung von Arbeitsabläufen und die Steiger...","pt":"O GTD Runner é uma habilidade de código que executa tarefas de forma autônoma a partir de itens do GTD.md, classificando e planejando ações.","ru":"GTD Runner - это навык кода, который выполняет задачи автоматически из элементов GTD.md, классифицируя и планируя действия.","ar":"GTD Runner هي مهارة الكود التي تنفذ المهام بشكل ذاتي من عناصر GTD.md، وتصنف و تخطط الإجراءات.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["自动执行任务","读取GTD.md文件","提取任务项","自动计划和执行","支持多语言"],"ja":["自動タスク実行","GTD.mdファイルの読み込み","タスクアイテムの抽出","自動計画と実行","多言語対応"],"ko":["자동 태스크 실행","GTD.md 파일 읽기","태스크 항목 추출","자동 계획 및 실행","다중 언어 지원"],"es":["Ejecución autónoma de tareas","Automatización de flujos de trabajo","Lectura de elementos de GTD.md","Clasificación y planificación de acciones","Ejecución secuencial de tareas"],"fr":["Exécution autonome de tâches","Automatisation de flux de travail","Lecture d''éléments de GTD.md","Classification et planification d''actions","Exécution séquentielle de tâches"],"de":["Automatische Ausführung von Aufgaben","Automatisierung von Arbeitsabläufen","Lesevorgang von GTD.md-Elementen","Klassifizierung und Planung von Aktionen","Sequenzielle Ausführung von Aufgaben"],"pt":["Execução autônoma de tarefas","Classificação de itens do GTD.md","Planejamento de ações","Execução sequencial de itens aprovados","Saída de resultados em ~/CybosVault/private/content/work/"],"ru":["Автономное выполнение задач","Классификация элементов GTD.md","Планирование действий","Последовательное выполнение одобренных элементов","Выход результатов в ~/CybosVault/private/content/work/"],"ar":["تنفيذ مهام ذاتي","تصنيف عناصر GTD.md","تخطيط الإجراءات","تنفيذ عناصر موافق بشكل متتالي","إخراج النتائج في ~/CybosVault/private/content/work/"]},"keywords":{"zh":["GTD 跑步器技能","自动执行任务","开发效率","GTD.md","自动计划","自动执行","任务管理","开发工具"],"ja":["GTDランナー スキル","自動タスク実行","開発効率","GTD.md","自動計画","自動実行","タスク管理","開発ツール"],"ko":["GTD 러너 스킬","자동 태스크 실행","개발 효율성","GTD.md","자동 계획","자동 실행","태스크 관리","개발 도구"],"es":["GTD Runner","automatización de tareas","flujos de trabajo","productividad","GTD.md","ejecución autónoma"],"fr":["GTD Runner","automatisation de tâches","flux de travail","productivité","GTD.md","exécution autonome"],"de":["GTD Runner","Automatisierung von Aufgaben","Arbeitsabläufe","Produktivität","GTD.md","automatische Ausführung"],"pt":["GTD Runner","execução autônoma de tarefas","GTD.md","classificação de itens","planejamento de ações","desenvolvimento de software","automação de tarefas"],"ru":["GTD Runner","автономное выполнение задач","GTD.md","классификация элементов","планирование действий","разработка программного обеспечения","автоматизация задач"],"ar":["GTD Runner","تنفيذ مهام ذاتي","GTD.md","تصنيف عناصر","تخطيط الإجراءات","تطوير البرمجيات","أتمتة المهام"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"gtd","description":"Autonomous task execution from GTD.md items. Use when processing GTD tasks, call prep, outreach, or podcast preparation.","bodyPreview":"# GTD Runner Skill\n\nAutonomous task execution from GTD.md items.\n\n## Trigger\n\n- Command: `/cyber-gtd`\n- Default: plan-first (show before execute)\n\n## Workflow\n\n1. Read `@GTD.md` → extract items from `# Next`\n2. For each item:\n   - Classify → match pattern to workflow\n   - Lookup entities via database: `bun scripts/db/query.ts find-entity \"<name>\"`\n   - Plan actions\n3. Show plan → ask to execute\n4. Execute approved items sequentially (one at a time)\n5. Output: `~/CybosVault/private/content/work/M","body":"# GTD Runner Skill\n\nAutonomous task execution from GTD.md items.\n\n## Trigger\n\n- Command: `/cyber-gtd`\n- Default: plan-first (show before execute)\n\n## Workflow\n\n1. Read `@GTD.md` → extract items from `# Next`\n2. For each item:\n   - Classify → match pattern to workflow\n   - Lookup entities via database: `bun scripts/db/query.ts find-entity \"<name>\"`\n   - Plan actions\n3. Show plan → ask to execute\n4. Execute approved items sequentially (one at a time)\n5. Output: `~/CybosVault/private/content/work/MMDD-<slug>.md`\n\n## Classification → Routing\n\n| Pattern | Confidence | Workflow |\n|---------|------------|----------|\n| \"ask for call\", \"message\", \"email\", \"reach out\" | High | → workflows/outreach.md |\n| \"call with\", \"meeting\", \"X <> Y\", \"sync\" | High | → workflows/call-prep.md |\n| \"podcast\" | High | → workflows/podcast.md |\n| company name, \"research\", \"DD\", \"look into\" | Medium | → workflows/research.md |\n| **no match** | Low | Best judgment → log to learnings.md |\n\n## Entity Lookup\n\nQuery database for entity context:\n\n1. Parse item for names (people, companies)\n2. Run: `bun scripts/db/query.ts find-entity \"<name>\" --json`\n3. If found, get full context: `bun scripts/db/query.ts entity <slug> --json`\n4. Entity context includes:\n   - Recent interactions (calls, emails, telegram)\n   - Deal associations\n   - Pending items\n5. If not found + confident it''s an entity:\n   - High confidence (company with domain) → auto-create stub\n   - Medium confidence → ask: \"Create entity file for X?\"\n\n## Output Format\n\nAll outputs to `~/CybosVault/private/content/work/MMDD-<slug>.md`:\n\n```markdown\n# Task: [Task Description]\n\n**Status:** Pending Approval | Completed | Incomplete\n**Created:** YYYY-MM-DD HH:MM\n**GTD Item:** [Original text from GTD.md]\n**Workflow:** [Which workflow handled this]\n\n---\n\n## Context\n\n**Entity:** [Name]\n- Type: [person/org]\n- Deal: [link if exists]\n- Previous calls: [N calls found]\n\n**Key Info:**\n[Relevant context from calls, deals, entity files]\n\n---\n\n## Draft\n\n[Message/agenda/questions/etc]\n\n---\n\n## Pending Actions\n\n- [ ] Send via Gmail to email@example.com\n- [ ] Alternative: Telegram @handle\n\n---\n\n## Execution Log\n\n- HH:MM - [action taken]\n```\n\n## Staged Execution\n\nAgent completes what it can autonomously:\n- Research and context gathering\n- Draft creation\n- Preparation work\n\nThen queues actions requiring approval:\n- Sending messages (Gmail, Telegram)\n- Scheduling meetings\n- Any external action\n\n## Suggestions\n\nWhen processing tasks, if you notice 3+ similar patterns that don''t have\na dedicated workflow, suggest: \"I''ve seen ''[pattern]'' multiple times.\nWant me to create a workflow for it?\"\n\n## Self-Improvement\n\nLog all task executions to `@learnings.md` for pattern analysis.\n"},"lastSynced":"2026-02-20T04:57:39.495Z","agentAnalysis":{"suitability":{"en":"Perfect for Task Automation Agents needing GTD workflow integration and autonomous task execution from markdown items.","zh":"非常适合需要GTD工作流集成和从markdown项自动执行任务的任务自动化代理。","ja":"GTDワークフロー統合とマークダウンアイテムからの自動タスク実行を必要とするタスク自動化エージェントに最適です。","ko":"GTD 워크플로 통합 및 마크다운 항목에서 자동 작업 실행이 필요한 작업 자동화 에이전트에 적합합니다.","es":"Perfecto para Agentes de Automatización de Tareas que necesitan integración de flujo de trabajo GTD y ejecución autónoma de tareas a partir de elementos markdown.","fr":"Parfait pour les agents d''automatisation de tâches nécessitant une intégration de flux de travail GTD et une exécution autonome de tâches à partir d''éléments markdown.","de":"Perfekt für Task-Automatisierungsagenten, die eine GTD-Workflow-Integration und eine autonome Aufgabenausführung aus Markdown-Elementen benötigen.","pt":"Perfeito para Agentes de Automação de Tarefas que necessitam de integração de fluxo de trabalho GTD e execução autônoma de tarefas a partir de itens em markdown.","ru":"Идеально подходит для агентов автоматизации задач, которым необходима интеграция с рабочим процессом GTD и автономное выполнение задач из элементов markdown.","ar":"مثالي لعمليات إتمام المهام التي تحتاج إلى دمج تدفق عمل GTD والتشغيل التلقائي للمهام من عناصر Markdown."},"recommendation":{"en":"Empowers agents to classify and execute tasks from GTD.md items using pattern matching and entity lookup via database queries, enabling seamless workflow automation with bun scripts and TypeScript.","zh":"使代理能够使用模式匹配和实体查找通过数据库查询来对GTD.md项进行任务分类和执行，从而实现与bun脚本和TypeScript的无缝工作流自动化。","ja":"エージェントがパターンマッチングとエンティティ検索を使用してGTD.mdアイテムをタスクに分類して実行できるようにし、bunスクリプトとTypeScriptを使用したシームレスなワークフロー自動化を可能にします。","ko":"에이전트가 패턴 매칭 및 엔티티 조회를 사용하여 GTD.md 항목을 작업으로 분류 및 실행할 수 있도록 하여, bun 스크립트 및 TypeScript를 사용한 무결점 워크플로 자동화를 가능하게 합니다.","es":"Habilita a los agentes a clasificar y ejecutar tareas desde elementos GTD.md utilizando coincidencia de patrones y búsqueda de entidades a través de consultas de base de datos, lo que permite una automatización de flujo de trabajo sin problemas con scripts bun y TypeScript.","fr":"Permet aux agents de classifier et d''exécuter des tâches à partir d''éléments GTD.md en utilisant la correspondance de modèles et la recherche d''entités via des requêtes de base de données, permettant ainsi une automation de flux de travail sans heurts avec des scripts bun et TypeScript.","de":"Ermächtigt Agenten, Aufgaben aus GTD.md-Elementen zu klassifizieren und auszuführen, indem Musterabgleich und Entitätssuche über Datenbankabfragen verwendet werden, was eine nahtlose Automatisierung des Arbeitsablaufs mit bun-Skripten und TypeScript ermöglicht.","pt":"Permite que os agentes classifiquem e executem tarefas a partir de itens GTD.md usando correspondência de padrões e pesquisa de entidades via consultas de banco de dados, permitindo uma automação de fluxo de trabalho sem problemas com scripts bun e TypeScript.","ru":"Позволяет агентам классифицировать и выполнять задачи из элементов GTD.md, используя сопоставление с образцом и поиск сущностей через запросы к базе данных, обеспечивая бесшовную автоматизацию рабочего процесса с помощью скриптов bun и TypeScript.","ar":"يسمح للوكلاء بتصنيف وتنفيذ المهام من عناصر GTD.md باستخدام مطابقة الأنماط والبحث عن الكيانات عبر استفسارات قاعدة البيانات، وتمكين автомة تدفق العمل بسلاسة مع سكريبتات bun وTypeScript."},"useCases":{"en":["Automating task planning from # Next items in GTD.md","Executing sequential tasks with entity lookup","Generating action plans based on workflow patterns"],"zh":["从GTD.md中的# Next项自动执行任务规划","使用实体查找执行顺序任务","根据工作流模式生成行动计划"],"ja":["GTD.mdの# Nextアイテムからタスク計画を自動化する","エンティティ検索を使用して順序タスクを実行する","ワークフローパターンに基づいてアクションプランを生成する"],"ko":["GTD.md의 # Next 항목에서 작업 계획 자동화를 수행하는 것","엔티티 조회를 사용하여 순차적 작업을 실행하는 것","워크플로 패턴에 따라 행동 계획을 생성하는 것"],"es":["Automatización de la planificación de tareas desde elementos # Siguiente en GTD.md","Ejecución de tareas secuenciales con búsqueda de entidades","Generación de planes de acción en función de patrones de flujo de trabajo"],"fr":["Automatisation de la planification de tâches à partir d''éléments # Suivant dans GTD.md","Exécution de tâches séquentielles avec recherche d''entités","Génération de plans d''action en fonction de modèles de flux de travail"],"de":["Automatisierung der Aufgabenplanung aus # Nächste-Elementen in GTD.md","Ausführung von sequenziellen Aufgaben mit Entitätssuche","Erstellung von Aktionsplänen basierend auf Arbeitsablaufmustern"],"pt":["Automatizar planejamento de tarefas a partir de itens # Next em GTD.md","Executar tarefas sequenciais com pesquisa de entidades","Gerar planos de ação com base em padrões de fluxo de trabalho"],"ru":["Автоматизировать планирование задач из элементов # Next в GTD.md","Выполнять последовательные задачи с поиском сущностей","Генерировать планы действий на основе шаблонов рабочего процесса"],"ar":["تحسين تخطيط المهام من عناصر # Next في GTD.md","تنفيذ مهام متسلسلة بالبحث عن الكيانات","توليد خطط العمل بناءً على أنماط تدفق العمل"]},"limitations":{"en":["Requires access to GTD.md file","Depends on bun scripts and database connectivity","Limited to sequential task execution"],"zh":["需要访问GTD.md文件","依赖于bun脚本和数据库连接","仅限于顺序任务执行"],"ja":["GTD.mdファイルへのアクセスが必要","bunスクリプトとデータベース接続に依存している","順序タスク実行のみに限定されている"],"ko":["GTD.md 파일에 대한 액세스가 필요합니다.","bun 스크립트 및 데이터베이스 연결에 의존합니다.","순차적 작업 실행에만 제한됩니다."],"es":["Requiere acceso al archivo GTD.md","Depende de scripts bun y conectividad de base de datos","Limitado a la ejecución de tareas secuenciales"],"fr":["Nécessite un accès au fichier GTD.md","Dépend de scripts bun et de la connectivité de base de données","Limité à l''exécution de tâches séquentielles"],"de":["Benötigt Zugriff auf die GTD.md-Datei","Hängt von bun-Skripten und Datenbankverbindung ab","Begrenzt auf die sequenzielle Ausführung von Aufgaben"],"pt":["Requer acesso ao arquivo GTD.md","Depende de scripts bun e conectividade de banco de dados","Limitado à execução de tarefas sequenciais"],"ru":["Требует доступа к файлу GTD.md","Зависит от скриптов bun и подключения к базе данных","Ограничен выполнением последовательных задач"],"ar":["يتطلب الوصول إلى ملف GTD.md","يعتمد على سكريبتات bun وتركيبة قاعدة البيانات","محدود بتنفيذ المهام المتسلسلة"]},"version":3},"contentHash":"61c7adb4a70f3e66197fdb3b747d860e475628ccba6c23519a94e5cd5a79c8c6","qualityScore":80}');
