INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('glennguilloux/Agent0/create-skill', 'create-skill', 'glennguilloux', 'Agent0', 'community', 'create-skill glennguilloux Agent0 community Agent Zero 创建技能向导帮助您创建新的技能，按照 SKILL.md 标准，包括名称、触发模式、内容结构和支持文件 エージェントゼロのスキル作成ウィザードは、SKILL.md 標準に従った新しいスキルを作成するのに役立ちます 에이전트 제로의 스킬 생성 마법사는 SKILL.md 표준에 따라 새로운 스킬을 생성하는 데 도움을 줍니다 Create-skill es una habilidad que ayuda a crear nuevas habilidades de Agent Zero que siguen el estándar SKILL.md. Guía para crear habilidades personalizadas. Create-skill est une compétence qui aide à créer de nouvelles compétences Agent Zero qui suivent la norme SKILL.md. Guide pour créer des compétences personnalisées. Create-skill ist eine Fähigkeit, die hilft, neue Fähigkeiten für Agent Zero zu erstellen, die dem SKILL.md-Standard entsprechen. Anleitung zur Erstellung benutzerdefinierter Fähigkeiten. O Create Skill Wizard ajuda a criar novas habilidades de Agente Zero que seguem o padrão SKILL.md. Aprenda a criar suas próprias habilidades personalizadas. Create Skill Wizard помогает создавать новые навыки Agent Zero, соответствующие стандарту SKILL.md. Узнайте, как создавать индивидуальные навыки. يساعد Create Skill Wizard على إنشاء مهارات جديدة للوكيل صفر التي تتبع معيار SKILL.md. تعلم كيفية إنشاء مهارات مخصصة. Agent-zero Agent Zero 创建技能 SKILL.md 开发者工具 技能创建向导 快速创建新技能 Agent-zero');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiskillstore/marketplace/shadcn-ui', 'community', 'aiskillstore', 'marketplace', 'aiskillstore/marketplace', 'shadcn-ui', 0, 0, 80, '2026-02-20T04:13:19.579Z', '2026-02-20T05:02:51.971Z', '2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304', '{"id":"aiskillstore/marketplace/shadcn-ui","name":"shadcn-ui","description":{"zh":"shadcn-ui, Radix UI, Base UI Tailwind CSS","ja":"shadcn-ui, Radix UI, Base UI Tailwind CSS","ko":"shadcn-ui, Radix UI, Base UI Tailwind CSS","es":"shadcn-ui es una colección de componentes de interfaz de usuario seguros y personalizables para desarrolladores","fr":"shadcn-ui est une collection de composants d''interface utilisateur sécurisés et personnalisables pour les développeurs","de":"shadcn-ui ist eine Sammlung von sichereren und anpassbaren Benutzeroberflächen-Komponenten für Entwickler","pt":"shadcn-ui é uma coleção de componentes de interface de usuário personalizados e acessíveis, projetados para serem fáceis de integrar e customizar","ru":"shadcn-ui - это коллекция настраиваемых и доступных компонентов интерфейса пользователя, предназначенных для простой интеграции и настройки","ar":"شادcn-يو آي هي مجموعة من مكونات واجهة المستخدم المخصصة والقابلة للوصول، مصممة لتكون سهلة التكامل والتعديل","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"seo":{"title":{"zh":"shadcn-ui ","ja":"shadcn-ui","ko":"shadcn-ui","es":"shadcn-ui: Componentes de interfaz de usuario personaliza...","fr":"shadcn-ui : Composants d''interface utilisateur personnali...","de":"shadcn-ui: Anpassbare Benutzeroberflächen-Komponenten","pt":"shadcn-ui: Componentes de Interface de Usuário","ru":"shadcn-ui: Компоненты интерфейса пользователя","ar":"شادcn-يو آي: مكونات واجهة المستخدم","en":"shadcn-ui"},"description":{"zh":"shadcn-ui, Radix UI, Base UI Tailwind CSS","ja":"shadcn-ui, Radix UI, Base UI Tailwind CSS","ko":"shadcn-ui, Radix UI, Base UI Tailwind CSS","es":"shadcn-ui es una colección de componentes de interfaz de usuario seguros y personalizables para desarrolladores","fr":"shadcn-ui est une collection de composants d''interface utilisateur sécurisés et personnalisables pour les développeurs","de":"shadcn-ui ist eine Sammlung von sichereren und anpassbaren Benutzeroberflächen-Komponenten für Entwickler","pt":"shadcn-ui é uma coleção de componentes de interface de usuário personalizados e acessíveis, projetados para serem fáceis de integrar e customizar","ru":"shadcn-ui - это коллекция настраиваемых и доступных компонентов интерфейса пользователя, предназначенных для простой интеграции и настройки","ar":"شادcn-يو آي هي مجموعة من مكونات واجهة المستخدم المخصصة والقابلة للوصول، مصممة لتكون سهلة التكامل والتعديل","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"definition":{"en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"features":{"zh":["Radix UI","Base UI","Tailwind CSS","UI","shadcn/ui","UI"],"ja":["Radix UI","Base UI","Tailwind CSS","UI","shadcn/ui","UI"],"ko":["Radix UI","Base UI","Tailwind CSS","UI","shadcn/ui","UI"],"es":["Componentes de interfaz de usuario personalizables","Seguridad auditada","Instalación de un solo clic","Verificación de calidad","Compatibilidad con Radix UI y Base UI","Compatibilidad con Tailwind CSS"],"fr":["Composants d''interface utilisateur personnalisables","Sécurité auditée","Installation en un seul clic","Vérification de la qualité","Compatibilité avec Radix UI et Base UI","Compatibilité avec Tailwind CSS"],"de":["Anpassbare Benutzeroberflächen-Komponenten","Sicherheitsüberprüfung","Ein-Klick-Installation","Qualitätsprüfung","Kompatibilität mit Radix UI und Base UI","Kompatibilität mit Tailwind CSS"],"pt":["Componentes personalizados e acessíveis","Fácil integração e customização","Coleção de componentes reutilizáveis","Projetados com Radix UI e Tailwind CSS","Qualidade verificada e segurança auditada"],"ru":["Настраиваемые и доступные компоненты","Простая интеграция и настройка","Коллекция повторно используемых компонентов","Разработаны с использованием Radix UI и Tailwind CSS","Проверенная качество и аудит безопасности"],"ar":["مكونات مخصصة وقابلة للوصول","تكامل وتصميم سهل","مجموعة من المكونات القابلة لإعادة الاستخدام","مصممة باستخدام Radix UI و Tailwind CSS","جودة مدققة ومراجعة أمنية"]},"keywords":{"zh":["shadcn-ui","Radix UI","Base UI","Tailwind CSS","UI","shadcn/ui","UI","frontend"],"ja":["shadcn-ui","Radix UI","Base UI","Tailwind CSS","UI","shadcn/ui","UI","frontend"],"ko":["shadcn-ui","Radix UI","Base UI","Tailwind CSS","UI","shadcn/ui","UI","frontend"],"es":["shadcn-ui","componentes de interfaz de usuario","seguridad","personalizable","Radix UI","Base UI","Tailwind CSS","desarrollo web","frontend"],"fr":["shadcn-ui","composants d''interface utilisateur","sécurité","personnalisable","Radix UI","Base UI","Tailwind CSS","développement web","frontend"],"de":["shadcn-ui","Benutzeroberflächen-Komponenten","Sicherheit","anpassbar","Radix UI","Base UI","Tailwind CSS","Webentwicklung","frontend"],"pt":["shadcn-ui","componentes de interface de usuário","personalizados","acessíveis","Radix UI","Tailwind CSS","desenvolvimento web","frontend"],"ru":["shadcn-ui","компоненты интерфейса пользователя","настраиваемые","доступные","Radix UI","Tailwind CSS","веб-разработка","фронтенд"],"ar":["شادcn-يو آي","مكونات واجهة المستخدم","مخصصة","قابلة للوصول","Radix UI","Tailwind CSS","تطوير ويب","الواجهة الأمامية"]}},"owner":"aiskillstore","repo":"marketplace","repoPath":"aiskillstore/marketplace","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.579Z","topics":[],"category":"community","skillMd":{"name":"shadcn-ui","description":"Expert guidance for integrating and building applications with shadcn/ui components, including component discovery, installation, customization, and best practices.","bodyPreview":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full owner","body":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full ownership**: Components live in your codebase, not node_modules\n- **Complete customization**: Modify styling, behavior, and structure freely, including choosing between Radix UI or Base UI primitives\n- **No version lock-in**: Update components selectively at your own pace\n- **Zero runtime overhead**: No library bundle, just the code you need\n\n## Component Discovery and Installation\n\n### 1. Browse Available Components\n\nUse the shadcn MCP tools to explore the component catalog and Registry Directory:\n- **List all components**: Use `list_components` to see the complete catalog\n- **Get component metadata**: Use `get_component_metadata` to understand props, dependencies, and usage\n- **View component demos**: Use `get_component_demo` to see implementation examples\n\n### 2. Component Installation\n\nThere are two approaches to adding components:\n\n**A. Direct Installation (Recommended)**\n```bash\nnpx shadcn@latest add [component-name]\n```\n\nThis command:\n- Downloads the component source code (adapting to your config: Radix vs Base UI)\n- Installs required dependencies\n- Places files in `components/ui/`\n- Updates your `components.json` config\n\n**B. Manual Integration**\n1. Use `get_component` to retrieve the source code\n2. Create the file in `components/ui/[component-name].tsx`\n3. Install peer dependencies manually\n4. Adjust imports if needed\n\n### 3. Registry and Custom Registries\n\nIf working with a custom registry (defined in `components.json`) or exploring the Registry Directory:\n- Use `get_project_registries` to list available registries\n- Use `list_items_in_registries` to see registry-specific components\n- Use `view_items_in_registries` for detailed component information\n- Use `search_items_in_registries` to find specific components\n\n## Project Setup\n\n### Initial Configuration\n\nFor **new projects**, use the `create` command to customize everything (style, fonts, component library):\n\n```bash\nnpx shadcn@latest create\n```\n\nFor **existing projects**, initialize configuration:\n\n```bash\nnpx shadcn@latest init\n```\n\nThis creates `components.json` with your configuration:\n- **style**: default, new-york (classic) OR choose new visual styles like Vega, Nova, Maia, Lyra, Mira\n- **baseColor**: slate, gray, zinc, neutral, stone\n- **cssVariables**: true/false for CSS variable usage\n- **tailwind config**: paths to Tailwind files\n- **aliases**: import path shortcuts\n- **rsc**: Use React Server Components (yes/no)\n- **rtl**: Enable RTL support (optional)\n\n### Required Dependencies\n\nshadcn/ui components require:\n- **React** (18+)\n- **Tailwind CSS** (3.0+)\n- **Primitives**: Radix UI OR Base UI (depending on your choice)\n- **class-variance-authority** (for variant styling)\n- **clsx** and **tailwind-merge** (for class composition)\n\n## Component Architecture\n\n### File Structure\n```\nsrc/\n├── components/\n│   ├── ui/              # shadcn components\n│   │   ├── button.tsx\n│   │   ├── card.tsx\n│   │   └── dialog.tsx\n│   └── [custom]/        # your composed components\n│       └── user-card.tsx\n├── lib/\n│   └── utils.ts         # cn() utility\n└── app/\n    └── page.tsx\n```\n\n### The `cn()` Utility\n\nAll shadcn components use the `cn()` helper for class merging:\n\n```typescript\nimport { clsx, type ClassValue } from \"clsx\"\nimport { twMerge } from \"tailwind-merge\"\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs))\n}\n```\n\nThis allows you to:\n- Override default styles without conflicts\n- Conditionally apply classes\n- Merge Tailwind classes intelligently\n\n## Customization Best Practices\n\n### 1. Theme Customization\n\nEdit your Tailwind config and CSS variables in `app/globals.css`:\n\n```css\n@layer base {\n  :root {\n    --background: 0 0% 100%;\n    --foreground: 222.2 84% 4.9%;\n    --primary: 221.2 83.2% 53.3%;\n    /* ... more variables */\n  }\n  \n  .dark {\n    --background: 222.2 84% 4.9%;\n    --foreground: 210 40% 98%;\n    /* ... dark mode overrides */\n  }\n}\n```\n\n### 2. Component Variants\n\nUse `class-variance-authority` (cva) for variant logic:\n\n```typescript\nimport { cva } from \"class-variance-authority\"\n\nconst buttonVariants = cva(\n  \"inline-flex items-center justify-center rounded-md\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground\",\n        outline: \"border border-input\",\n      },\n      size: {\n        default: \"h-10 px-4 py-2\",\n        sm: \"h-9 rounded-md px-3\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  }\n)\n```\n\n### 3. Extending Components\n\nCreate wrapper components in `components/` (not `components/ui/`):\n\n```typescript\n// components/custom-button.tsx\nimport { Button } from \"@/components/ui/button\"\nimport { Loader2 } from \"lucide-react\"\n\nexport function LoadingButton({ \n  loading, \n  children, \n  ...props \n}: ButtonProps & { loading?: boolean }) {\n  return (\n    <Button disabled={loading} {...props}>\n      {loading && <Loader2 className=\"mr-2 h-4 w-4 animate-spin\" />}\n      {children}\n    </Button>\n  )\n}\n```\n\n## Blocks and Complex Components\n\nshadcn/ui provides complete UI blocks (authentication forms, dashboards, etc.):\n\n1. **List available blocks**: Use `list_blocks` with optional category filter\n2. **Get block source**: Use `get_block` with the block name\n3. **Install blocks**: Many blocks include multiple component files\n\nBlocks are organized by category:\n- **calendar**: Calendar interfaces\n- **dashboard**: Dashboard layouts\n- **login**: Authentication flows\n- **sidebar**: Navigation sidebars\n- **products**: E-commerce components\n\n## Accessibility\n\nAll shadcn/ui components are built on Radix UI primitives, ensuring:\n- **Keyboard navigation**: Full keyboard support out of the box\n- **Screen reader support**: Proper ARIA attributes\n- **Focus management**: Logical focus flow\n- **Disabled states**: Proper disabled and aria-disabled handling\n\nWhen customizing, maintain accessibility:\n- Keep ARIA attributes\n- Preserve keyboard handlers\n- Test with screen readers\n- Maintain focus indicators\n\n## Common Patterns\n\n### Form Building\n```typescript\nimport { Button } from \"@/components/ui/button\"\nimport { Input } from \"@/components/ui/input\"\nimport { Label } from \"@/components/ui/label\"\n\n// Use with react-hook-form for validation\nimport { useForm } from \"react-hook-form\"\n```\n\n### Dialog/Modal Patterns\n```typescript\nimport {\n  Dialog,\n  DialogContent,\n  DialogDescription,\n  DialogHeader,\n  DialogTitle,\n  DialogTrigger,\n} from \"@/components/ui/dialog\"\n```\n\n### Data Display\n```typescript\nimport {\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"@/components/ui/table\"\n```\n\n## Troubleshooting\n\n### Import Errors\n- Check `components.json` for correct alias configuration\n- Verify `tsconfig.json` includes the `@` path alias:\n  ```json\n  {\n    \"compilerOptions\": {\n      \"paths\": {\n        \"@/*\": [\"./src/*\"]\n      }\n    }\n  }\n  ```\n\n### Style Conflicts\n- Ensure Tailwind CSS is properly configured\n- Check that `globals.css` is imported in your root layout\n- Verify CSS variable names match between components and theme\n\n### Missing Dependencies\n- Run component installation via CLI to auto-install deps\n- Manually check `package.json` for required Radix UI packages\n- Use `get_component_metadata` to see dependency lists\n\n### Version Compatibility\n- shadcn/ui v4 requires React 18+ and Next.js 13+ (if using Next.js)\n- Some components require specific Radix UI versions\n- Check documentation for breaking changes between versions\n\n## Validation and Quality\n\nBefore committing components:\n1. **Type check**: Run `tsc --noEmit` to verify TypeScript\n2. **Lint**: Run your linter to catch style issues\n3. **Test accessibility**: Use tools like axe DevTools\n4. **Visual QA**: Test in light and dark modes\n5. **Responsive check**: Verify behavior at different breakpoints\n\n## Resources\n\nRefer to the following resource files for detailed guidance:\n- `resources/setup-guide.md` - Step-by-step project initialization\n- `resources/component-catalog.md` - Complete component reference\n- `resources/customization-guide.md` - Theming and variant patterns\n- `resources/migration-guide.md` - Upgrading from other UI libraries\n\n## Examples\n\nSee the `examples/` directory for:\n- Complete component implementations\n- Form patterns with validation\n- Dashboard layouts\n- Authentication flows\n- Data table implementations\n"},"lastSynced":"2026-02-20T05:02:51.971Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing customizable and accessible UI components with Radix UI, Base UI, and Tailwind CSS integration.","zh":"非常适合需要可定制和可访问的UI组件的前端代理，具有Radix UI、Base UI和Tailwind CSS集成。","ja":"フロントエンドエージェントがカスタマイズ可能でアクセス可能なUIコンポーネントを必要とする場合に最適です。Radix UI、Base UI、Tailwind CSSを統合しています。","ko":"프론트엔드 에이전트가 사용자 지정 가능하고 접근 가능한 UI 컴포넌트가 필요한 경우에 적합합니다. Radix UI, Base UI 및 Tailwind CSS를 통합합니다.","es":"Perfecto para agentes Frontend que necesitan componentes de UI personalizables y accesibles con integración de Radix UI, Base UI y Tailwind CSS.","fr":"Parfait pour les agents Frontend ayant besoin de composants UI personnalisables et accessibles avec une intégration de Radix UI, Base UI et Tailwind CSS.","de":"Perfekt für Frontend-Agents, die benutzerdefinierbare und zugängliche UI-Komponenten mit Radix UI-, Base UI- und Tailwind-CSS-Integration benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de componentes de UI personalizáveis e acessíveis com integração do Radix UI, Base UI e Tailwind CSS.","ru":"Идеально подходит для агентов Frontend, которым необходимы настраиваемые и доступные компоненты UI с интеграцией Radix UI, Base UI и Tailwind CSS.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى مكونات واجهة المستخدم القابلة للتعديل والمتوافقة مع تكنولوجيا Radix UI و Base UI و Tailwind CSS."},"recommendation":{"en":"Empowers agents to integrate and customize shadcn/ui components following best practices, utilizing full ownership of the codebase with one-click installation and quality verification, leveraging Radix UI or Base UI and Tailwind CSS for seamless frontend development.","zh":"赋予代理集成和定制shadcn/ui组件的能力，遵循最佳实践，利用代码库的完全所有权，实现一键安装和质量验证，利用Radix UI或Base UI和Tailwind CSS进行无缝的前端开发。","ja":"エージェントがshadcn/uiコンポーネントを統合し、カスタマイズできるようにします。ベストプラクティスに従い、コードベースの完全な所有権を利用して、一クリックインストールと品質検証を行い、Radix UIまたはBase UIとTailwind CSSを使用してシームレスなフロントエンド開発を行います。","ko":"에이전트가 shadcn/ui 컴포넌트를 통합하고 사용자 지정할 수 있도록 하여 بهترین 방법을 따르며 코드베이스의 완전한 소유권을 활용하여 한 번의 클릭으로 설치하고 품질을 검증하며 Radix UI 또는 Base UI와 Tailwind CSS를 사용하여无缝な 프론트엔드 개발을 진행합니다.","es":"Habilita a los agentes a integrar y personalizar componentes de shadcn/ui siguiendo las mejores prácticas, utilizando la propiedad total del código con instalación de un solo clic y verificación de calidad, aprovechando Radix UI o Base UI y Tailwind CSS para un desarrollo frontend sin problemas.","fr":"Permet aux agents d''intégrer et de personnaliser les composants shadcn/ui en suivant les meilleures pratiques, en utilisant la pleine propriété du codebase avec une installation en un seul clic et une vérification de la qualité, en exploitant Radix UI ou Base UI et Tailwind CSS pour un développement frontend sans heurts.","de":"Ermächtigt die Agenten, shadcn/ui-Komponenten zu integrieren und anzupassen, indem sie die besten Praktiken befolgen, die volle Kontrolle über den Codebestand mit einer Ein-Klick-Installation und Qualitätsverifizierung ausüben und Radix UI oder Base UI und Tailwind CSS für eine reibungslose Frontend-Entwicklung nutzen.","pt":"Habilita os agentes a integrar e personalizar os componentes shadcn/ui seguindo as melhores práticas, utilizando a propriedade total do código com instalação em um clique e verificação de qualidade, aproveitando o Radix UI ou Base UI e Tailwind CSS para desenvolvimento de frontend sem problemas.","ru":"Наделяет агентов возможностью интегрировать и настраивать компоненты shadcn/ui в соответствии с лучшими практиками, используя полную собственность кодовой базы с установкой в один клик и проверкой качества, используя Radix UI или Base UI и Tailwind CSS для бесперебойного разработки frontend.","ar":"تمكين الوكلاء من دمج مكونات shadcn/ui وتعديلها اتباعًا لأفضل الممارسات، واستخدام الملكية الكاملة لقاعدة الشفرة مع تثبيت واحد النقر والتحقق من الجودة، والاستفادة من Radix UI أو Base UI و Tailwind CSS من أجل تطوير واجهة المستخدم الأمامية دون مشاكل."},"useCases":{"en":["Integrating accessible UI components into web applications","Customizing shadcn/ui components for tailored user experiences","Streamlining frontend development with one-click installation and quality verified components"],"zh":["将可访问的UI组件集成到Web应用程序中","为用户量身定制shadcn/ui组件以实现个性化用户体验","通过一键安装和质量验证的组件来简化前端开发"],"ja":["Webアプリケーションにアクセス可能なUIコンポーネントを統合する","ユーザーに合わせたshadcn/uiコンポーネントをカスタマイズしてユーザーエクスペリエンスを向上させる","一クリックインストールと品質検証されたコンポーネントを使用してフロントエンド開発を効率化する"],"ko":["접근 가능한 UI 컴포넌트를 웹 애플리케이션에 통합하는 것","사용자에게 맞춘 shadcn/ui 컴포넌트를 사용자 지정하여 사용자 경험을 개선하는 것","한 번의 클릭으로 설치하고 품질을 검증한 컴포넌트를 사용하여 프론트엔드 개발을 간소화하는 것"],"es":["Integrar componentes de UI accesibles en aplicaciones web","Personalizar componentes de shadcn/ui para experiencias de usuario personalizadas","Optimizar el desarrollo frontend con instalación de un solo clic y componentes verificados de calidad"],"fr":["Intégrer des composants UI accessibles dans des applications Web","Personnaliser les composants shadcn/ui pour des expériences utilisateur sur mesure","Optimiser le développement frontend avec une installation en un seul clic et des composants vérifiés de qualité"],"de":["Integrieren von zugänglichen UI-Komponenten in Webanwendungen","Anpassen von shadcn/ui-Komponenten für maßgeschneiderte Benutzeroberflächen","Optimieren der Frontend-Entwicklung mit Ein-Klick-Installation und qualitätsgeprüften Komponenten"],"pt":["Integrar componentes de UI acessíveis em aplicações web","Personalizar componentes shadcn/ui para experiências de usuário personalizadas","Otimizar o desenvolvimento de frontend com instalação em um clique e componentes verificados pela qualidade"],"ru":["Интегрировать доступные компоненты UI в веб-приложения","Настроить компоненты shadcn/ui для индивидуальных пользовательских опытов","Оптимизировать разработку frontend с установкой в один клик и компонентами, проверенными на качество"],"ar":["دمج مكونات واجهة المستخدم المتوافقة في التطبيقات الويب","تخصيص مكونات shadcn/ui لتجارب المستخدم المخصصة","تحسين تطوير واجهة المستخدم الأمامية مع تثبيت واحد النقر ومكونات محققة بالجودة"]},"limitations":{"en":["Not a traditional component library, requires copying components into the project","Specifically designed for use with Radix UI, Base UI, and Tailwind CSS"],"zh":["不是传统的组件库，需要将组件复制到项目中","专门为与Radix UI、Base UI和Tailwind CSS一起使用而设计"],"ja":["従来のコンポーネントライブラリではなく、コンポーネントをプロジェクトにコピーする必要がある","Radix UI、Base UI、Tailwind CSSと一緒に使用するように特別に設計されている"],"ko":["전통적인 컴포넌트 라이브러리가 아니며 컴포넌트를 프로젝트에 복사해야 함","Radix UI, Base UI 및 Tailwind CSS와 함께 사용하도록 특별히 설계됨"],"es":["No es una biblioteca de componentes tradicional, requiere copiar componentes en el proyecto","Diseñado específicamente para uso con Radix UI, Base UI y Tailwind CSS"],"fr":["Ce n''est pas une bibliothèque de composants traditionnelle, nécessite de copier les composants dans le projet","Conçu spécifiquement pour une utilisation avec Radix UI, Base UI et Tailwind CSS"],"de":["Keine traditionelle Komponentenbibliothek, erfordert das Kopieren von Komponenten in das Projekt","Speziell für die Verwendung mit Radix UI, Base UI und Tailwind CSS entwickelt"],"pt":["Não é uma biblioteca de componentes tradicional, requer copiar componentes para o projeto","Projetado especificamente para uso com Radix UI, Base UI e Tailwind CSS"],"ru":["Не является традиционной библиотекой компонентов, требует копирования компонентов в проект","Спецально разработан для использования с Radix UI, Base UI и Tailwind CSS"],"ar":["ليست مكتبة مكونات تقليدية، تتطلب نسخ المكونات إلى المشروع","صُممت خصيصًا للاستخدام مع Radix UI و Base UI و Tailwind CSS"]},"version":3},"contentHash":"2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304","qualityScore":80}');
