INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/shadcn-ui', 'shadcn-ui', 'aiskillstore', 'marketplace', 'community', 'shadcn-ui aiskillstore marketplace community shadcn-ui, Radix UI, Base UI Tailwind CSS shadcn-ui, Radix UI, Base UI Tailwind CSS shadcn-ui, Radix UI, Base UI Tailwind CSS shadcn-ui es una colección de componentes de interfaz de usuario seguros y personalizables para desarrolladores shadcn-ui est une collection de composants d''interface utilisateur sécurisés et personnalisables pour les développeurs shadcn-ui ist eine Sammlung von sichereren und anpassbaren Benutzeroberflächen-Komponenten für Entwickler shadcn-ui é uma coleção de componentes de interface de usuário personalizados e acessíveis, projetados para serem fáceis de integrar e customizar shadcn-ui - это коллекция настраиваемых и доступных компонентов интерфейса пользователя, предназначенных для простой интеграции и настройки شادcn-يو آي هي مجموعة من مكونات واجهة المستخدم المخصصة والقابلة للوصول، مصممة لتكون سهلة التكامل والتعديل Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. shadcn-ui Radix UI Base UI Tailwind CSS UI shadcn/ui UI frontend Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/gh-agent-session', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'gh-agent-session', 0, 0, 80, '2026-02-20T04:13:19.580Z', '2026-02-20T05:04:14.536Z', 'a25dec86f649c29a991837ecbe5ab91f5fe02323fc987ebb8aaaebbdf15484d8', '{"id":"majiayu000/claude-skill-registry/gh-agent-session","name":"gh-agent-session","description":{"zh":"GitHub Copilot 代理会话扩展允许开发者通过命令行创建代理会话，实现自动代码更改","ja":"GitHub Copilot エージェントセッション拡張は、コマンドラインからエージェントセッションを作成し、自動コード変更を実現","ko":"GitHub Copilot 에이전트 세션 확장은 명령줄을 통해 에이전트 세션을 생성하여 자동 코드 변경을 구현","es":"La extensión de CLI de GitHub permite crear sesiones de agente de GitHub Copilot a través de la línea de comandos. Estas sesiones son problemas de GitHub especializados que activan cambios de código automatizados","fr":"L''extension de CLI de GitHub permet de créer des sessions d''agent GitHub Copilot via la ligne de commande. Ces sessions sont des problèmes GitHub spécialisés qui déclenchent des modifications de code automatisées","de":"Die GitHub-CLI-Erweiterung ermöglicht die Erstellung von GitHub Copilot-Agent-Sitzungen über die Kommandozeile. Diese Sitzungen sind spezielle GitHub-Probleme, die automatisierte Codeänderungen auslösen","pt":"A extensão de sessão de agente GitHub CLI permite criar sessões de agente para alterações de código automatizadas com base em instruções de linguagem natural.","ru":"Расширение сессии агента GitHub CLI позволяет создавать сессии агента для автоматических изменений кода на основе инструкций естественного языка.","ar":"ملحق جلسة وكلاء جيت هاب CLI يسمح بإنشاء جلسات وكلاء لتعديلات الكود الآلية بناءً على تعليمات اللغة الطبيعية.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"GitHub Copilot 代理会话扩展","ja"