INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/repo-website-api-review', 'repo-website-api-review', 'majiayu000', 'claude-skill-registry', 'community', 'repo-website-api-review majiayu000 claude-skill-registry community 该技能提供了一种系统化的方法来审查 API 文档，确保其准确性和一致性 このスキルは、API ドキュメントを体系的にレビューする方法を提供し、正確性と一貫性を確保する 이 기술은 API 문서를 체계적으로 검토하여 정확성과 일관성을 보장하는 방법을 제공합니다 Este skill proporciona un enfoque sistemático para revisar la documentación de API y garantizar la precisión y la consistencia Ce skill propose une approche systématique pour réviser la documentation de l''API et assurer la précision et la cohérence Dieses Skill bietet einen systematischen Ansatz, um die API-Dokumentation zu überprüfen und Genauigkeit sowie Konsistenz zu gewährleisten Revisão de documentação de API para garantir precisão e consistência Проверка документации API для обеспечения точности и согласованности مراجعة وثائق واجهة برمجة التطبيقات لضمان الدقة والاتساق The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app API 文档审查 系统化审查 源代码比较 函数签名 类型验证 JSDoc 属性检查 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
