INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('artofrawr/claude-control/supabase-python', 'supabase-python', 'artofrawr', 'claude-control', 'community', 'supabase-python artofrawr claude-control community Supabase Python 技术提供了快速开发的解决方案，使用 FastAPI 模式、Supabase Auth 和 SQLAlchemy/SQLModel Supabase Python スキルは、FastAPI パターン、Supabase Auth、SQLAlchemy/SQLModel を使用した迅速な開発ソリューションを提供します Supabase Python 개발은 FastAPI 패턴, Supabase Auth, SQLAlchemy/SQLModel을 사용한 빠른 개발 솔루션을 제공합니다 Supabase Python es una configuración opinada para proyectos de desarrollo con autenticación y almacenamiento Supabase Python est une configuration opinée pour les projets de développement avec authentification et stockage Supabase Python ist eine Meinungs-Config für Entwicklungsprojekte mit Authentifizierung und Speicherung O Supabase Python é uma habilidade que fornece configuração e inicialização de projeto para Claude Code, com padrões FastAPI e acesso a banco de dados seguro Supabase Python — это навык, который обеспечивает конфигурацию и инициализацию проекта для Claude Code, с шаблонами FastAPI и безопасным доступом к базе данных سوباسي بيثون هو مهارة توفر إعداد وتشغيل لمشروع Claude Code، مع أنماط FastAPI ووصول آمن إلى قاعدة البيانات Opinionated config and project initialization for Claude Code. Spec and test-driven, AI-native. Supabase Python FastAPI Supabase Auth SQLAlchemy SQLModel 快速开发 类型安全数据库访问 Opinionated config and project initialization for Claude Code. Spec and test-driven, AI-native.');
