INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/prompt-engineer', 'prompt-engineer', 'majiayu000', 'claude-skill-registry', 'community', 'prompt-engineer majiayu000 claude-skill-registry community Prompt Engineer 技术技能是指编写高效提示的能力，涉及工作流程和最佳实践 プロンプトエンジニア技術スキルは、効率的なプロンプトを作成するためのスキルです 프롬프트 엔지니어 기술 스킬은 효율적인 프롬프트를 작성하는 능력입니다 El ingeniero de prompts es una habilidad técnica que implica la creación y optimización de prompts para sistemas de inteligencia artificial. Aprende a dominar esta habilidad con nuestra guía técnica. L''ingénieur de prompts est une compétence technique qui consiste à créer et à optimiser des prompts pour les systèmes d''intelligence artificielle. Apprenez à maîtriser cette compétence avec notre guide technique. Der Prompt-Ingenieur ist eine technische Fähigkeit, die die Erstellung und Optimierung von Prompts für künstliche Intelligenz-Systeme beinhaltet. Lernen Sie, diese Fähigkeit mit unserer technischen Anleitung zu beherrschen. O skill de engenheiro de prompt é uma ferramenta poderosa para otimizar fluxos de trabalho e desenvolver soluções inovadoras Навык инженера промпта - это мощный инструмент для оптимизации рабочих процессов и разработки инновационных решений مهارة مهندس البرمجة هي أداة قوية لتحسين تدفقات العمل وتطوير حلول مبتكرة The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Prompt Engineer 技术技能 编写高效提示 工作流程 最佳实践 检查清单 验证结果 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
