INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ngxtm/devkit/prompt-engineer', 'prompt-engineer', 'ngxtm', 'devkit', 'community', 'prompt-engineer ngxtm devkit community Prompt Engineer 技能是 AI 编码助手的统一多代理系统，提供 414+ 技能、38 个代理和 57 个命令 Prompt Engineer スキルは、AI コーディングアシスタントの統一多エージェントシステムで、414 種類以上のスキル、38 のエージェント、57 のコマンドを提供します Prompt Engineer 스킬은 AI 코딩 어시스트의 통합 다중 에이전트 시스템으로, 414개 이상의 스킬, 38개의 에이전트, 57개의 커맨드를 제공합니다 El sistema de habilidades de ingeniero de prompts es una plataforma unificada para asistentes de codificación AI con 414+ habilidades y 38 agentes. Ofrece detección de tecnología inteligente y sincronización automática Le système de compétences d''ingénieur de prompts est une plateforme unifiée pour les assistants de codage AI avec 414+ compétences et 38 agents. Il propose une détection de technologie intelligente et une synchronisation automatique Das Skill-System des Prompt-Ingenieurs ist eine einheitliche Plattform für AI-Codierungs-Assistenten mit 414+ Fähigkeiten und 38 Agenten. Es bietet intelligente Technologie-Erkennung und automatische Synchronisation O sistema de habilidades de IA para engenheiros de prompt é uma solução unificada para melhorar a produtividade do código. Oferece 414+ habilidades e 38 agentes para automatizar tarefas Система навыков ИИ для инженеров промпта - это унифицированное решение для повышения производительности кода. Она предлагает 414+ навыков и 38 агентов для автоматизации задач نظام مهارات الذكاء الاصطناعي لمهندسي البرومت هو حل موحد لتحسين إنتاجية الرمز. يقدم 414+ مهارة و 38 وكلاء لآلية المهام Unified multi-agent skill system for AI coding assistants (Claude Code, Cursor, Copilot, Gemini) with 414+ skills, 38 agents, and 57 commands. Features smart tech detection, per-project installation, and auto-sync from upstream sources. AI 编码助手 Prompt Engineer 技能 统一多代理系统 智能技术检测 项目安装 自动同步 编码效率 Unified multi-agent skill system for AI coding assistants (Claude Code, Cursor, Copilot, Gemini) with 414+ skills, 38 agents, and 57 commands. Features smart tech detection, per-project installation, and auto-sync from upstream sources.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/ralph', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'ralph', 0, 0, 80, '2026-02-20T04:13:19.581Z', '2026-02-20T05:13:35.421Z', 'a6a8733abaee5b370957ebd6745a56db88712697fc1262f388d2438b6bbcc021', '{"id":"majiayu000/claude-skill-registry/ralph","name":"ralph","description":{"zh":"Ralph PRD Converter是一种工具，用于将PRD文档转换为prd.json格式，实现自动执行和高效开发。它支持将markdown文件或文本转换为prd.json格式","ja":"Ralph PRD Converterは、PRDドキュメントをprd.json形式に変換するツールであり、自動実行と効率的な開発を実現します。マークダウンファイルまたはテキストをprd.json形式に変換することをサポート","ko":"Ralph PRD Converter는 PRD 문서를 prd.json 형식으로 변환하여 자동 실행 및 효율적인 개발을 실현하는 도구입니다. 마크다운 파일 또는 텍스트를 prd.json 형식으로 변환하는 것을 지원","es":"Ralph es una herramienta que convierte PRD a JSON para ejecución autónoma. Permite la creación de archivos PRD en formato JSON para una integración más sencilla.","fr":"Ralph est un outil qui convertit les PRD en JSON pour exécution autonome. Il permet de créer des fichiers PRD au format JSON pour une intégration plus simple.","de":"Ralph ist ein Tool, das PRD in JSON für autonome Ausführung konvertiert. Es ermöglicht die Erstellung von PRD-Dateien im JSON-Format für eine einfachere Integration.","pt":"O Ralph PRD Converter é uma ferramenta que converte PRDs em formato JSON para execução autônoma, permitindo a automação de processos de desenvolvimento.","ru":"Ralph PRD Конвертер — это инструмент, который преобразует PRD в формат JSON для автономного выполнения, позволяя автоматизировать процессы разработки.","ar":"مُحول رالف PRD هو أداة لتحويل ملفات PRD إلى تنسيق JSON للتشغيل الذاتي، مما يسمح بآليّة عمليات التطوير.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Ralph PRD Converter - 自动执行PRD转换工具","ja":"Ralph PRD Converter - 自動実行PRD変換ツール"