INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/ralph', 'ralph', 'majiayu000', 'claude-skill-registry', 'community', 'ralph majiayu000 claude-skill-registry community Ralph PRD Converter是一种工具，用于将PRD文档转换为prd.json格式，实现自动执行和高效开发。它支持将markdown文件或文本转换为prd.json格式 Ralph PRD Converterは、PRDドキュメントをprd.json形式に変換するツールであり、自動実行と効率的な開発を実現します。マークダウンファイルまたはテキストをprd.json形式に変換することをサポート Ralph PRD Converter는 PRD 문서를 prd.json 형식으로 변환하여 자동 실행 및 효율적인 개발을 실현하는 도구입니다. 마크다운 파일 또는 텍스트를 prd.json 형식으로 변환하는 것을 지원 Ralph es una herramienta que convierte PRD a JSON para ejecución autónoma. Permite la creación de archivos PRD en formato JSON para una integración más sencilla. Ralph est un outil qui convertit les PRD en JSON pour exécution autonome. Il permet de créer des fichiers PRD au format JSON pour une intégration plus simple. Ralph ist ein Tool, das PRD in JSON für autonome Ausführung konvertiert. Es ermöglicht die Erstellung von PRD-Dateien im JSON-Format für eine einfachere Integration. O Ralph PRD Converter é uma ferramenta que converte PRDs em formato JSON para execução autônoma, permitindo a automação de processos de desenvolvimento. Ralph PRD Конвертер — это инструмент, который преобразует PRD в формат JSON для автономного выполнения, позволяя автоматизировать процессы разработки. مُحول رالف PRD هو أداة لتحويل ملفات PRD إلى تنسيق JSON للتشغيل الذاتي، مما يسمح بآليّة عمليات التطوير. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Ralph PRD Converter PRD转换工具 自动执行 高效开发 PRD格式 markdown转换 开发工具 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alinaqi/claude-bootstrap/supabase-python', 'community', 'alinaqi', 'claude-bootstrap', 'alinaqi/claude-bootstrap', 'supabase-python', 0, 0, 80, '2026-02-20T04:13:19.577Z', '2026-03-02T09:49:35.836Z', 'f53306e9d121a3b07b302c0a9d982ede342a3b16d33e6c742d5fedb37cf61d45', '{"id":"alinaqi/claude-bootstrap/supabase-python","name":"supabase-python","description":{"zh":"Supabase Python AI工具提供了将FastAPI与Supabase和SQLAlchemy/SQLModel集成的解决方案，实现快速、可靠的应用程序开发","ja":"Supabase Python AIエージェントは、FastAPIとSupabaseおよびSQLAlchemy/SQLModelの統合ソリューションを提供し、高速で信頼性の高いアプリケーションの開発を実現","ko":"Supabase Python AI 에이전트는 FastAPI와 Supabase 및 SQLAlchemy/SQLModel의 통합 솔루션을 제공하여 빠르고 안정적인 애플리케이션 개발을 가능하게 합니다","es":"Supabase Python es una combinación de FastAPI y Supabase para desarrollar aplicaciones escalables con SQLAlchemy/SQLModel","fr":"Supabase Python est une combinaison de FastAPI et Supabase pour développer des applications évolutives avec SQLAlchemy/SQLModel","de":"Supabase Python ist eine Kombination aus FastAPI und Supabase für die Entwicklung von skalierbaren Anwendungen mit SQLAlchemy/SQLModel","pt":"Desenvolva aplicações rápidas e escaláveis com Supabase, FastAPI e SQLAlchemy/SQLModel","ru":"Разрабатывайте быстрые и масштабируемые приложения с Supabase, FastAPI и SQLAlchemy/SQLModel","ar":"قم بتطوير تطبيقات سريعة وقابلة للتوسعة مع Supabase و FastAPI و SQLAlchemy/SQLModel","en":"FastAPI with Supabase and SQLAlchemy/SQLModel"},"seo":{"title":{"zh":"Supabase Python AI工具：FastAPI与Supabase和SQLAlchemy/SQLModel集成","ja":"Supabase Python AIエージェント：FastAPIとSupabaseおよびSQLAlchemy/SQ...","ko":"Supabase Python AI 에이전트: FastAPI와 Supabase 및 SQLAlchemy/S...","es":"Herramientas AI: Supabase Python con FastAPI","fr":"Outils IA: Supabase Python avec FastAPI","de":"KI-Tools: Supabase Python mit FastAPI","pt":"Ferramentas de IA: Supabase Python com FastAPI","ru":"ИИ Агенты: Supabase Python с FastAPI","ar":"أدوات الذكاء الاصطناعي: Supabase Python مع FastAPI","en":"supabase-python"},"description":{"zh":"Supabase Python AI工具提供了将FastAPI与Supabase和SQLAlchemy/SQLModel集成的解决方案，实现快速、可靠的应用程序开发","ja":"Supabase Python AIエージェントは、FastAPIとSupabaseおよびSQLAlchemy/SQLModelの統合ソリューションを提供し、高速で信頼性の高いアプリケーションの開発を実現","ko":"Supabase Python AI 에이전트는 FastAPI와 Supabase 및 SQLAlchemy/SQLModel의 통합 솔루션을 제공하여 빠르고 안정적인 애플리케이션 개발을 가능하게 합니다","es":"Supabase Python es una combinación de FastAPI y Supabase para desarrollar aplicaciones escalables con SQLAlchemy/SQLModel","fr":"Supabase Python est une combinaison de FastAPI et Supabase pour développer des applications évolutives avec SQLAlchemy/SQLModel","de":"Supabase Python ist eine Kombination aus FastAPI und Supabase für die Entwicklung von skalierbaren Anwendungen mit SQLAlchemy/SQLModel","pt":"Desenvolva aplicações rápidas e escaláveis com Supabase, FastAPI e SQLAlchemy/SQLModel","ru":"Разрабатывайте быстрые и масштабируемые приложения с Supabase, FastAPI и SQLAlchemy/SQLModel","ar":"قم بتطوير تطبيقات سريعة وقابلة للتوسعة مع Supabase و FastAPI و SQLAlchemy/SQLModel","en":"FastAPI with Supabase and SQLAlchemy/SQLModel"},"definition":{"en":"FastAPI with Supabase and SQLAlchemy/SQLModel"},"features":{"zh":["FastAPI与Supabase集成","SQLAlchemy/SQLModel支持","快速、可靠的应用程序开发","简单、易用的API","高性能的数据处理"],"ja":["FastAPIとSupabaseの統合","SQLAlchemy/SQLModelのサポート","高速で信頼性の高いアプリケーションの開発","シンプルで使いやすいAPI","高性能のデータ処理"],"ko":["FastAPI와 Supabase의 통합","SQLAlchemy/SQLModel 지원","빠르고 안정적인 애플리케이션 개발","간단하고易用的 API","고성능의 데이터 처리"],"es":["Desarrollo de aplicaciones escalables con FastAPI","Integración con Supabase para bases de datos","Utilización de SQLAlchemy/SQLModel para modelos de datos","Creación de APIs RESTful con FastAPI","Soporte para desarrollo de aplicaciones web y móviles"],"fr":["Développement d''applications évolutives avec FastAPI","Intégration avec Supabase pour les bases de données","Utilisation de SQLAlchemy/SQLModel pour les modèles de données","Création d''API RESTful avec FastAPI","Prise en charge du développement d''applications web et mobiles"],"de":["Entwicklung von skalierbaren Anwendungen mit FastAPI","Integration mit Supabase für Datenbanken","Verwendung von SQLAlchemy/SQLModel für Datenmodelle","Erstellung von RESTful-APIs mit FastAPI","Unterstützung für die Entwicklung von Web- und Mobilanwendungen"],"pt":["Integração com Supabase","Desenvolvimento com FastAPI","Suporte a SQLAlchemy/SQLModel","Aplicações rápidas e escaláveis","Desenvolvimento de APIs"],"ru":["Интеграция с Supabase","Разработка с FastAPI","Поддержка SQLAlchemy/SQLModel","Быстрые и масштабируемые приложения","Разработка API"],"ar":["دمج مع Supabase","التطوير مع FastAPI","دعم SQLAlchemy/SQLModel","تطبيقات سريعة وقابلة للتوسعة","تطوير واجهات برمجة التطبيقات"]},"keywords":{"zh":["Supabase Python AI工具","FastAPI与Supabase集成","SQLAlchemy/SQLModel教程","如何使用Supabase Python AI工具","Supabase Python AI工具安装","Supabase Python AI工具替代品","FastAPI vs Django","Supabase vs Firebase"],"ja":["Supabase Python AIエージェント","FastAPIとSupabaseの統合","SQLAlchemy/SQLModelチュートリアル","Supabase Python AIエージェントの使用方法","Supabase Python AIエージェントのインストール","Supabase Python AIエージェントの代替品","FastAPI vs Django","Supabase vs Firebase"],"ko":["Supabase Python AI 에이전트","FastAPI와 Supabase의 통합","SQLAlchemy/SQLModel 튜토리얼","Supabase Python AI 에이전트 사용법","Supabase Python AI 에이전트 설치","Supabase Python AI 에이전트 대안","FastAPI vs Django","Supabase vs Firebase"],"es":["cómo utilizar Supabase con FastAPI","Supabase Python tutorial","FastAPI vs Flask","Supabase alternative","instalación de Supabase","guía de configuración de FastAPI","desarrollo de aplicaciones escalables","herramientas AI para desarrolladores"],"fr":["comment utiliser Supabase avec FastAPI","tutoriel Supabase Python","FastAPI vs Flask","alternative à Supabase","installation de Supabase","guide de configuration de FastAPI","développement d''applications évolutives","outils IA pour les développeurs"],"de":["wie man Supabase mit FastAPI verwendet","Supabase Python-Tutorial","FastAPI vs Flask","Supabase-Alternative","Installation von Supabase","FastAPI-Konfigurationshandbuch","Entwicklung von skalierbaren Anwendungen","KI-Tools für Entwickler"],"pt":["como usar supabase","o que é supabase","supabase vs firebase","instalar supabase","guia de configuração do supabase","desenvolvimento de aplicações com supabase","supabase python","fastapi","sqlalchemy","sqlmodel"],"ru":["как использовать supabase","что такое supabase","supabase vs firebase","установить supabase","руководство по настройке supabase","разработка приложений с supabase","supabase python","fastapi","sqlalchemy","sqlmodel"],"ar":["كيفية استخدام supabase","ما هو supabase","supabase مقابل firebase","تثبيت supabase","دليل إعداد supabase","تطوير التطبيقات مع supabase","supabase python","fastapi","sqlalchemy","sqlmodel"]}},"owner":"alinaqi","repo":"claude-bootstrap","repoPath":"alinaqi/claude-bootstrap","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.577Z","topics":[],"category":"community","skillMd":{"name":"supabase-python","description":"FastAPI with Supabase and SQLAlchemy/SQLModel","bodyPreview":"# Supabase + Python Skill\n\n*Load with: base.md + supabase.md + python.md*\n\nFastAPI patterns with Supabase Auth and SQLAlchemy/SQLModel for database access.\n\n**Sources:** [Supabase Python Client](https://supabase.com/docs/reference/python/introduction) | [SQLModel](https://sqlmodel.tiangolo.com/)\n\n---\n\n## Core Principle\n\n**SQLAlchemy/SQLModel for queries, Supabase for auth/storage.**\n\nUse SQLAlchemy or SQLModel for type-safe database access. Use supabase-py for auth, storage, and realtime. FastAP","body":"# Supabase + Python Skill\n\n*Load with: base.md + supabase.md + python.md*\n\nFastAPI patterns with Supabase Auth and SQLAlchemy/SQLModel for database access.\n\n**Sources:** [Supabase Python Client](https://supabase.com/docs/reference/python/introduction) | [SQLModel](https://sqlmodel.tiangolo.com/)\n\n---\n\n## Core Principle\n\n**SQLAlchemy/SQLModel for queries, Supabase for auth/storage.**\n\nUse SQLAlchemy or SQLModel for type-safe database access. Use supabase-py for auth, storage, and realtime. FastAPI for the API layer.\n\n---\n\n## Project Structure\n\n```\nproject/\n├── src/\n│   ├── api/\n│   │   ├── __init__.py\n│   │   ├── routes/\n│   │   │   ├── __init__.py\n│   │   │   ├── auth.py\n│   │   │   ├── posts.py\n│   │   │   └── users.py\n│   │   └── deps.py              # Dependencies (auth, db)\n│   ├── core/\n│   │   ├── __init__.py\n│   │   ├── config.py            # Settings\n│   │   └── security.py          # Auth helpers\n│   ├── db/\n│   │   ├── __init__.py\n│   │   ├── session.py           # Database session\n│   │   └── models.py            # SQLModel models\n│   ├── services/\n│   │   ├── __init__.py\n│   │   └── supabase.py          # Supabase client\n│   └── main.py                  # FastAPI app\n├── supabase/\n│   ├── migrations/\n│   └── config.toml\n├── alembic/                     # Alembic migrations (alternative)\n├── alembic.ini\n├── pyproject.toml\n└── .env\n```\n\n---\n\n## Setup\n\n### Install Dependencies\n```bash\npip install fastapi uvicorn supabase python-dotenv sqlmodel asyncpg alembic\n```\n\n### pyproject.toml\n```toml\n[project]\nname = \"my-app\"\nversion = \"0.1.0\"\ndependencies = [\n    \"fastapi>=0.109.0\",\n    \"uvicorn[standard]>=0.27.0\",\n    \"supabase>=2.0.0\",\n    \"python-dotenv>=1.0.0\",\n    \"sqlmodel>=0.0.14\",\n    \"asyncpg>=0.29.0\",\n    \"alembic>=1.13.0\",\n    \"pydantic-settings>=2.0.0\",\n]\n\n[project.optional-dependencies]\ndev = [\n    \"pytest>=7.0.0\",\n    \"pytest-asyncio>=0.23.0\",\n    \"httpx>=0.26.0\",\n]\n```\n\n### Environment Variables\n```bash\n# .env\nSUPABASE_URL=http://localhost:54321\nSUPABASE_ANON_KEY=<from supabase start>\nSUPABASE_SERVICE_ROLE_KEY=<from supabase start>\nDATABASE_URL=postgresql+asyncpg://postgres:postgres@localhost:54322/postgres\n```\n\n---\n\n## Configuration\n\n### src/core/config.py\n```python\nfrom pydantic_settings import BaseSettings\nfrom functools import lru_cache\n\n\nclass Settings(BaseSettings):\n    # Supabase\n    supabase_url: str\n    supabase_anon_key: str\n    supabase_service_role_key: str\n\n    # Database\n    database_url: str\n\n    # App\n    debug: bool = False\n\n    class Config:\n        env_file = \".env\"\n        env_file_encoding = \"utf-8\"\n\n\n@lru_cache\ndef get_settings() -> Settings:\n    return Settings()\n```\n\n---\n\n## Database Setup\n\n### src/db/session.py\n```python\nfrom sqlalchemy.ext.asyncio import create_async_engine, AsyncSession\nfrom sqlalchemy.orm import sessionmaker\nfrom src.core.config import get_settings\n\nsettings = get_settings()\n\nengine = create_async_engine(\n    settings.database_url,\n    echo=settings.debug,\n    pool_pre_ping=True,\n)\n\nAsyncSessionLocal = sessionmaker(\n    engine,\n    class_=AsyncSession,\n    expire_on_commit=False,\n)\n\n\nasync def get_db() -> AsyncSession:\n    async with AsyncSessionLocal() as session:\n        try:\n            yield session\n        finally:\n            await session.close()\n```\n\n### src/db/models.py\n```python\nfrom datetime import datetime\nfrom typing import Optional\nfrom uuid import UUID, uuid4\nfrom sqlmodel import SQLModel, Field\n\n\nclass ProfileBase(SQLModel):\n    email: str\n    name: Optional[str] = None\n    avatar_url: Optional[str] = None\n\n\nclass Profile(ProfileBase, table=True):\n    __tablename__ = \"profiles\"\n\n    id: UUID = Field(primary_key=True)  # References auth.users\n    created_at: datetime = Field(default_factory=datetime.utcnow)\n    updated_at: datetime = Field(default_factory=datetime.utcnow)\n\n\nclass ProfileCreate(ProfileBase):\n    id: UUID\n\n\nclass ProfileRead(ProfileBase):\n    id: UUID\n    created_at: datetime\n\n\nclass PostBase(SQLModel):\n    title: str\n    content: Optional[str] = None\n    published: bool = False\n\n\nclass Post(PostBase, table=True):\n    __tablename__ = \"posts\"\n\n    id: UUID = Field(default_factory=uuid4, primary_key=True)\n    author_id: UUID = Field(foreign_key=\"profiles.id\")\n    created_at: datetime = Field(default_factory=datetime.utcnow)\n\n\nclass PostCreate(PostBase):\n    pass\n\n\nclass PostRead(PostBase):\n    id: UUID\n    author_id: UUID\n    created_at: datetime\n```\n\n---\n\n## Supabase Client\n\n### src/services/supabase.py\n```python\nfrom supabase import create_client, Client\nfrom src.core.config import get_settings\n\nsettings = get_settings()\n\n\ndef get_supabase_client() -> Client:\n    \"\"\"Get Supabase client with anon key (respects RLS).\"\"\"\n    return create_client(\n        settings.supabase_url,\n        settings.supabase_anon_key\n    )\n\n\ndef get_supabase_admin() -> Client:\n    \"\"\"Get Supabase client with service role (bypasses RLS).\"\"\"\n    return create_client(\n        settings.supabase_url,\n        settings.supabase_service_role_key\n    )\n```\n\n---\n\n## Auth Dependencies\n\n### src/api/deps.py\n```python\nfrom typing import Annotated\nfrom fastapi import Depends, HTTPException, status\nfrom fastapi.security import HTTPBearer, HTTPAuthorizationCredentials\nfrom sqlalchemy.ext.asyncio import AsyncSession\nfrom supabase import Client\n\nfrom src.db.session import get_db\nfrom src.services.supabase import get_supabase_client\n\nsecurity = HTTPBearer()\n\n\nasync def get_current_user(\n    credentials: Annotated[HTTPAuthorizationCredentials, Depends(security)],\n) -> dict:\n    \"\"\"Validate JWT and return user.\"\"\"\n    supabase = get_supabase_client()\n\n    try:\n        # Verify token with Supabase\n        user = supabase.auth.get_user(credentials.credentials)\n        if not user or not user.user:\n            raise HTTPException(\n                status_code=status.HTTP_401_UNAUTHORIZED,\n                detail=\"Invalid token\",\n            )\n        return user.user\n    except Exception as e:\n        raise HTTPException(\n            status_code=status.HTTP_401_UNAUTHORIZED,\n            detail=\"Invalid token\",\n        )\n\n\n# Type alias for dependency injection\nCurrentUser = Annotated[dict, Depends(get_current_user)]\nDbSession = Annotated[AsyncSession, Depends(get_db)]\n```\n\n---\n\n## API Routes\n\n### src/api/routes/auth.py\n```python\nfrom fastapi import APIRouter, HTTPException, status\nfrom pydantic import BaseModel, EmailStr\n\nfrom src.services.supabase import get_supabase_client\n\nrouter = APIRouter(prefix=\"/auth\", tags=[\"auth\"])\n\n\nclass SignUpRequest(BaseModel):\n    email: EmailStr\n    password: str\n\n\nclass SignInRequest(BaseModel):\n    email: EmailStr\n    password: str\n\n\nclass AuthResponse(BaseModel):\n    access_token: str\n    refresh_token: str\n    user_id: str\n\n\n@router.post(\"/signup\", response_model=AuthResponse)\nasync def sign_up(request: SignUpRequest):\n    supabase = get_supabase_client()\n\n    try:\n        response = supabase.auth.sign_up({\n            \"email\": request.email,\n            \"password\": request.password,\n        })\n\n        if response.user is None:\n            raise HTTPException(\n                status_code=status.HTTP_400_BAD_REQUEST,\n                detail=\"Signup failed\",\n            )\n\n        return AuthResponse(\n            access_token=response.session.access_token,\n            refresh_token=response.session.refresh_token,\n            user_id=str(response.user.id),\n        )\n    except Exception as e:\n        raise HTTPException(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            detail=str(e),\n        )\n\n\n@router.post(\"/signin\", response_model=AuthResponse)\nasync def sign_in(request: SignInRequest):\n    supabase = get_supabase_client()\n\n    try:\n        response = supabase.auth.sign_in_with_password({\n            \"email\": request.email,\n            \"password\": request.password,\n        })\n\n        return AuthResponse(\n            access_token=response.session.access_token,\n            refresh_token=response.session.refresh_token,\n            user_id=str(response.user.id),\n        )\n    except Exception as e:\n        raise HTTPException(\n            status_code=status.HTTP_401_UNAUTHORIZED,\n            detail=\"Invalid credentials\",\n        )\n\n\n@router.post(\"/signout\")\nasync def sign_out():\n    supabase = get_supabase_client()\n    supabase.auth.sign_out()\n    return {\"message\": \"Signed out\"}\n```\n\n### src/api/routes/posts.py\n```python\nfrom uuid import UUID\nfrom fastapi import APIRouter, HTTPException, status\nfrom sqlmodel import select\n\nfrom src.api.deps import CurrentUser, DbSession\nfrom src.db.models import Post, PostCreate, PostRead\n\nrouter = APIRouter(prefix=\"/posts\", tags=[\"posts\"])\n\n\n@router.get(\"/\", response_model=list[PostRead])\nasync def list_posts(\n    db: DbSession,\n    published_only: bool = True,\n):\n    query = select(Post)\n    if published_only:\n        query = query.where(Post.published == True)\n    query = query.order_by(Post.created_at.desc())\n\n    result = await db.execute(query)\n    return result.scalars().all()\n\n\n@router.get(\"/me\", response_model=list[PostRead])\nasync def list_my_posts(\n    db: DbSession,\n    user: CurrentUser,\n):\n    query = select(Post).where(Post.author_id == UUID(user.id))\n    result = await db.execute(query)\n    return result.scalars().all()\n\n\n@router.post(\"/\", response_model=PostRead, status_code=status.HTTP_201_CREATED)\nasync def create_post(\n    db: DbSession,\n    user: CurrentUser,\n    post_in: PostCreate,\n):\n    post = Post(\n        **post_in.model_dump(),\n        author_id=UUID(user.id),\n    )\n    db.add(post)\n    await db.commit()\n    await db.refresh(post)\n    return post\n\n\n@router.get(\"/{post_id}\", response_model=PostRead)\nasync def get_post(\n    db: DbSession,\n    post_id: UUID,\n):\n    result = await db.execute(select(Post).where(Post.id == post_id))\n    post = result.scalar_one_or_none()\n\n    if not post:\n        raise HTTPException(\n            status_code=status.HTTP_404_NOT_FOUND,\n            detail=\"Post not found\",\n        )\n\n    return post\n\n\n@router.delete(\"/{post_id}\", status_code=status.HTTP_204_NO_CONTENT)\nasync def delete_post(\n    db: DbSession,\n    user: CurrentUser,\n    post_id: UUID,\n):\n    result = await db.execute(\n        select(Post).where(Post.id == post_id, Post.author_id == UUID(user.id))\n    )\n    post = result.scalar_one_or_none()\n\n    if not post:\n        raise HTTPException(\n            status_code=status.HTTP_404_NOT_FOUND,\n            detail=\"Post not found\",\n        )\n\n    await db.delete(post)\n    await db.commit()\n```\n\n---\n\n## Main Application\n\n### src/main.py\n```python\nfrom fastapi import FastAPI\nfrom fastapi.middleware.cors import CORSMiddleware\n\nfrom src.api.routes import auth, posts\n\napp = FastAPI(title=\"My API\")\n\n# CORS\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"*\"],  # Configure for production\n    allow_credentials=True,\n    allow_methods=[\"*\"],\n    allow_headers=[\"*\"],\n)\n\n# Routes\napp.include_router(auth.router, prefix=\"/api\")\napp.include_router(posts.router, prefix=\"/api\")\n\n\n@app.get(\"/health\")\nasync def health_check():\n    return {\"status\": \"healthy\"}\n```\n\n---\n\n## Alembic Migrations\n\n### Initialize Alembic\n```bash\nalembic init alembic\n```\n\n### alembic/env.py (key changes)\n```python\nfrom src.db.models import SQLModel\nfrom src.core.config import get_settings\n\nsettings = get_settings()\n\n# Use async engine\nconfig.set_main_option(\"sqlalchemy.url\", settings.database_url)\n\ntarget_metadata = SQLModel.metadata\n\n\ndef run_migrations_online():\n    # For async\n    import asyncio\n    from sqlalchemy.ext.asyncio import create_async_engine\n\n    connectable = create_async_engine(settings.database_url)\n\n    async def do_run_migrations():\n        async with connectable.connect() as connection:\n            await connection.run_sync(do_run_migrations_sync)\n\n    def do_run_migrations_sync(connection):\n        context.configure(\n            connection=connection,\n            target_metadata=target_metadata,\n        )\n        with context.begin_transaction():\n            context.run_migrations()\n\n    asyncio.run(do_run_migrations())\n```\n\n### Migration Commands\n```bash\n# Create migration\nalembic revision --autogenerate -m \"create posts table\"\n\n# Apply migrations\nalembic upgrade head\n\n# Rollback\nalembic downgrade -1\n```\n\n---\n\n## Storage\n\n### Upload File\n```python\nfrom fastapi import UploadFile\nfrom src.services.supabase import get_supabase_client\n\n\nasync def upload_avatar(user_id: str, file: UploadFile) -> str:\n    supabase = get_supabase_client()\n\n    file_content = await file.read()\n    file_path = f\"{user_id}/avatar.{file.filename.split(''.'')[-1]}\"\n\n    response = supabase.storage.from_(\"avatars\").upload(\n        file_path,\n        file_content,\n        {\"content-type\": file.content_type, \"upsert\": \"true\"},\n    )\n\n    # Get public URL\n    url = supabase.storage.from_(\"avatars\").get_public_url(file_path)\n    return url\n```\n\n### Download File\n```python\ndef get_avatar_url(user_id: str) -> str:\n    supabase = get_supabase_client()\n    return supabase.storage.from_(\"avatars\").get_public_url(f\"{user_id}/avatar.png\")\n```\n\n---\n\n## Realtime (Async)\n\n```python\nimport asyncio\nfrom supabase import create_client\n\n\nasync def listen_to_posts():\n    supabase = create_client(\n        settings.supabase_url,\n        settings.supabase_anon_key\n    )\n\n    def handle_change(payload):\n        print(f\"Change received: {payload}\")\n\n    channel = supabase.channel(\"posts\")\n    channel.on_postgres_changes(\n        event=\"*\",\n        schema=\"public\",\n        table=\"posts\",\n        callback=handle_change,\n    ).subscribe()\n\n    # Keep listening\n    while True:\n        await asyncio.sleep(1)\n```\n\n---\n\n## Testing\n\n### tests/conftest.py\n```python\nimport pytest\nfrom httpx import AsyncClient, ASGITransport\nfrom sqlalchemy.ext.asyncio import create_async_engine, AsyncSession\nfrom sqlalchemy.orm import sessionmaker\n\nfrom src.main import app\nfrom src.db.session import get_db\nfrom src.db.models import SQLModel\n\nTEST_DATABASE_URL = \"postgresql+asyncpg://postgres:postgres@localhost:54322/postgres_test\"\n\nengine = create_async_engine(TEST_DATABASE_URL)\nTestingSessionLocal = sessionmaker(engine, class_=AsyncSession, expire_on_commit=False)\n\n\n@pytest.fixture(scope=\"function\")\nasync def db_session():\n    async with engine.begin() as conn:\n        await conn.run_sync(SQLModel.metadata.create_all)\n\n    async with TestingSessionLocal() as session:\n        yield session\n\n    async with engine.begin() as conn:\n        await conn.run_sync(SQLModel.metadata.drop_all)\n\n\n@pytest.fixture\nasync def client(db_session):\n    async def override_get_db():\n        yield db_session\n\n    app.dependency_overrides[get_db] = override_get_db\n\n    async with AsyncClient(\n        transport=ASGITransport(app=app),\n        base_url=\"http://test\",\n    ) as ac:\n        yield ac\n\n    app.dependency_overrides.clear()\n```\n\n### tests/test_posts.py\n```python\nimport pytest\nfrom httpx import AsyncClient\n\n\n@pytest.mark.asyncio\nasync def test_list_posts(client: AsyncClient):\n    response = await client.get(\"/api/posts/\")\n    assert response.status_code == 200\n    assert isinstance(response.json(), list)\n```\n\n---\n\n## Running the App\n\n```bash\n# Development\nuvicorn src.main:app --reload --port 8000\n\n# Production\nuvicorn src.main:app --host 0.0.0.0 --port 8000 --workers 4\n```\n\n---\n\n## Anti-Patterns\n\n- **Using Supabase client for DB queries** - Use SQLAlchemy/SQLModel\n- **Sync database calls** - Use async with asyncpg\n- **Hardcoded credentials** - Use environment variables\n- **No connection pooling** - asyncpg handles this\n- **Missing auth dependency** - Always validate JWT\n- **Not closing sessions** - Use context managers\n- **Blocking I/O in async** - Use async libraries\n"},"lastSynced":"2026-03-02T09:49:35.836Z","agentAnalysis":{"suitability":{"en":"Ideal for Python-based AI Agents requiring secure data storage and authentication with Supabase and advanced database querying using SQLAlchemy/SQLModel.","zh":"适用于需要使用Supabase进行安全数据存储和身份验证，以及使用SQLAlchemy/SQLModel进行高级数据库查询的Python-based AI Agents。","ja":"Supabaseを使用してセキュアなデータストレージと認証を行い、SQLAlchemy/SQLModelを使用して高度なデータベースのクエリを行うPythonベースのAIエージェントに最適です。","ko":"Supabase를 사용하여 보안 데이터 저장소 및 인증이 필요한 Python 기반 AI 에이전트에게 적합하며, SQLAlchemy/SQLModel을 사용하여 고급 데이터베이스 쿼리를 수행합니다.","es":"Ideal para agentes de IA basados en Python que requieren almacenamiento de datos seguro y autenticación con Supabase y consulta de base de datos avanzada utilizando SQLAlchemy/SQLModel.","fr":"Idéal pour les agents d''IA basés sur Python nécessitant un stockage de données sécurisé et une authentification avec Supabase et une interrogation de base de données avancée à l''aide de SQLAlchemy/SQLModel.","de":"Ideal für Python-basierte KI-Agents, die sicheres Daten-speicherung und Authentifizierung mit Supabase sowie erweiterte Datenbankabfragen unter Verwendung von SQLAlchemy/SQLModel erfordern.","pt":"Ideal para Agentes de IA baseados em Python que exigem armazenamento de dados seguro e autenticação com Supabase e consulta de banco de dados avançada usando SQLAlchemy/SQLModel.","ru":"Идеально для агентов ИИ на основе Python, требующих безопасного хранения данных и аутентификации с Supabase и продвинутого запроса базы данных с помощью SQLAlchemy/SQLModel.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يستندون إلى Python الذين يتطلبون تخزين بيانات آمن وتوثيق مع Supabase واستعلام قاعدة البيانات المتقدمة باستخدام SQLAlchemy/SQLModel."},"recommendation":{"en":"Empowers agents to leverage Supabase for auth, storage, and real-time updates, while utilizing SQLAlchemy or SQLModel for type-safe database access and FastAPI patterns for robust backend development, ensuring a security-first and spec-driven approach.","zh":"赋予代理人利用Supabase进行身份验证、存储和实时更新的能力，同时利用SQLAlchemy或SQLModel进行类型安全的数据库访问和FastAPI模式进行强大的后端开发，确保以安全为首和规范驱动的方法。","ja":"エージェントがSupabaseを使用して認証、ストレージ、リアルタイム更新を行い、SQLAlchemyまたはSQLModelを使用して型安全なデータベースアクセスを行い、FastAPIパターンを使用して堅牢なバックエンド開発を行うことを可能にし、セキュリティ第一と仕様駆動のアプローチを保証します。","ko":"에이전트가 Supabase를 사용하여 인증, 저장소 및 실시간 업데이트를 수행하고, SQLAlchemy 또는 SQLModel을 사용하여 유형 안전한 데이터베이스 액세스를 수행하며, FastAPI 패턴을 사용하여 강력한 백엔드 개발을 수행할 수 있도록 하여, 보안 우선 및 사양 주도 접근 방식을 보장합니다.","es":"Habilita a los agentes a aprovechar Supabase para autenticación, almacenamiento y actualizaciones en tiempo real, mientras utiliza SQLAlchemy o SQLModel para acceso seguro a la base de datos y patrones de FastAPI para un desarrollo de backend robusto, garantizando un enfoque de seguridad y especificaciones.","fr":"Permet aux agents d''utiliser Supabase pour l''authentification, le stockage et les mises à jour en temps réel, tout en utilisant SQLAlchemy ou SQLModel pour un accès sécurisé à la base de données et des modèles FastAPI pour un développement de backend robuste, en garantissant une approche de sécurité et de spécifications.","de":"Ermöglich es den Agents, Supabase für Authentifizierung, Speicherung und Echtzeit-Updates zu nutzen, während SQLAlchemy oder SQLModel für den sichereren Zugriff auf die Datenbank und FastAPI-Muster für eine robuste Back-end-Entwicklung verwendet werden, um einen sicherheitsorientierten und spezifikationsgetriebenen Ansatz zu gewährleisten.","pt":"Habilita os agentes a aproveitar o Supabase para autenticação, armazenamento e atualizações em tempo real, ao mesmo tempo em que utiliza SQLAlchemy ou SQLModel para acesso a banco de dados seguro e padrões FastAPI para desenvolvimento de backend robusto, garantindo uma abordagem de segurança em primeiro lugar e dirigida por especificações.","ru":"Наделяет агентов возможностью использовать Supabase для аутентификации, хранения и обновлений в реальном времени, а также использовать SQLAlchemy или SQLModel для безопасного доступа к базе данных и шаблоны FastAPI для надежной разработки бэкенда, обеспечивая подход, ориентированный на безопасность и управляемый спецификациями.","ar":"يمكّن الوكلاء من الاستفادة من Supabase للتحقق والتحكم، والتخزين، والتحديثات في الوقت الفعلي، في الوقت نفسه الذي يستخدمون فيه SQLAlchemy أو SQLModel للوصول إلى قاعدة البيانات بأمان وأنماط FastAPI لتطوير الخلفية القوي، مما يضمن نهجًا يأتي الأمن أولاً وتوجيهه بواسطة المواصفات."},"useCases":{"en":["Implementing authentication and authorization using Supabase Auth","Building real-time data-driven applications with Supabase and FastAPI","Performing complex database queries using SQLAlchemy or SQLModel"],"zh":["使用Supabase Auth进行身份验证和授权的实现","使用Supabase和FastAPI构建实时数据驱动应用","使用SQLAlchemy或SQLModel进行复杂数据库查询"],"ja":["Supabase Authを使用した認証と認可の実装","SupabaseとFastAPIを使用したリアルタイムデータ駆動アプリケーションの構築","SQLAlchemyまたはSQLModelを使用した複雑なデータベースのクエリ"],"ko":["Supabase Auth를 사용한 인증 및 인가 구현","Supabase와 FastAPI를 사용한 실시간 데이터 주도 애플리케이션 구축","SQLAlchemy 또는 SQLModel을 사용한 복잡한 데이터베이스 쿼리"],"es":["Implementar autenticación y autorización utilizando Supabase Auth","Crear aplicaciones impulsadas por datos en tiempo real con Supabase y FastAPI","Realizar consultas de base de datos complejas utilizando SQLAlchemy o SQLModel"],"fr":["Mettre en œuvre l''authentification et l''autorisation à l''aide de Supabase Auth","Créer des applications pilotées par des données en temps réel avec Supabase et FastAPI","Effectuer des requêtes de base de données complexes en utilisant SQLAlchemy ou SQLModel"],"de":["Implementierung von Authentifizierung und Autorisierung unter Verwendung von Supabase Auth","Erstellen von Echtzeit-Datenanwendungen mit Supabase und FastAPI","Durchführen komplexer Datenbankabfragen unter Verwendung von SQLAlchemy oder SQLModel"],"pt":["Implementação de autenticação e autorização usando Supabase Auth","Construção de aplicações orientadas por dados em tempo real com Supabase e FastAPI","Realização de consultas de banco de dados complexas usando SQLAlchemy ou SQLModel"],"ru":["Реализация аутентификации и авторизации с помощью Supabase Auth","Создание приложений, ориентированных на данные в реальном времени, с Supabase и FastAPI","Выполнение сложных запросов базы данных с помощью SQLAlchemy или SQLModel"],"ar":["تنفيذ التحقق والتحكم باستخدام Supabase Auth","بناء تطبيقات مدفوعة بالبيانات في الوقت الفعلي مع Supabase و FastAPI","إجراء استفسارات قاعدة البيانات المعقدة باستخدام SQLAlchemy أو SQLModel"]},"limitations":{"en":["Requires Supabase account and project setup","Dependent on SQLAlchemy or SQLModel for database interactions","Limited to Python environment"],"zh":["需要Supabase账户和项目设置","依赖于SQLAlchemy或SQLModel进行数据库交互","仅限Python环境"],"ja":["Supabaseアカウントとプロジェクトの設定が必要","SQLAlchemyまたはSQLModelに依存してデータベースの相互作用を行う","Python環境のみ"],"ko":["Supabase 계정 및 프로젝트 설정이 필요","SQLAlchemy 또는 SQLModel에 의존하여 데이터베이스 상호 작용을 수행","Python 환경만"],"es":["Requiere una cuenta y configuración de proyecto de Supabase","Dependiente de SQLAlchemy o SQLModel para interacciones con la base de datos","Limitado al entorno de Python"],"fr":["Nécessite un compte et une configuration de projet Supabase","Dépendant de SQLAlchemy ou SQLModel pour les interactions avec la base de données","Limité à l''environnement Python"],"de":["Erfordert ein Supabase-Konto und eine Projektkonfiguration","Abhängig von SQLAlchemy oder SQLModel für Datenbankinteraktionen","Begrenzt auf die Python-Umgebung"],"pt":["Exige conta e configuração de projeto Supabase","Dependente de SQLAlchemy ou SQLModel para interações de banco de dados","Limitado ao ambiente Python"],"ru":["Требуется учетная запись и настройка проекта Supabase","Зависит от SQLAlchemy или SQLModel для взаимодействия с базой данных","Ограничен средой Python"],"ar":["يتطلب حسابًا وتكوين مشروع Supabase","يعتمد على SQLAlchemy أو SQLModel للتفاعل مع قاعدة البيانات","محدود بيئة Python"]},"version":3},"contentHash":"f53306e9d121a3b07b302c0a9d982ede342a3b16d33e6c742d5fedb37cf61d45","qualityScore":80}');
