INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alinaqi/claude-bootstrap/supabase-python', 'supabase-python', 'alinaqi', 'claude-bootstrap', 'community', 'supabase-python alinaqi claude-bootstrap community Supabase Python AI工具提供了将FastAPI与Supabase和SQLAlchemy/SQLModel集成的解决方案，实现快速、可靠的应用程序开发 Supabase Python AIエージェントは、FastAPIとSupabaseおよびSQLAlchemy/SQLModelの統合ソリューションを提供し、高速で信頼性の高いアプリケーションの開発を実現 Supabase Python AI 에이전트는 FastAPI와 Supabase 및 SQLAlchemy/SQLModel의 통합 솔루션을 제공하여 빠르고 안정적인 애플리케이션 개발을 가능하게 합니다 Supabase Python es una combinación de FastAPI y Supabase para desarrollar aplicaciones escalables con SQLAlchemy/SQLModel Supabase Python est une combinaison de FastAPI et Supabase pour développer des applications évolutives avec SQLAlchemy/SQLModel Supabase Python ist eine Kombination aus FastAPI und Supabase für die Entwicklung von skalierbaren Anwendungen mit SQLAlchemy/SQLModel Desenvolva aplicações rápidas e escaláveis com Supabase, FastAPI e SQLAlchemy/SQLModel Разрабатывайте быстрые и масштабируемые приложения с Supabase, FastAPI и SQLAlchemy/SQLModel قم بتطوير تطبيقات سريعة وقابلة للتوسعة مع Supabase و FastAPI و SQLAlchemy/SQLModel FastAPI with Supabase and SQLAlchemy/SQLModel Supabase Python AI工具 FastAPI与Supabase集成 SQLAlchemy/SQLModel教程 如何使用Supabase Python AI工具 Supabase Python AI工具安装 Supabase Python AI工具替代品 FastAPI vs Django Supabase vs Firebase FastAPI with Supabase and SQLAlchemy/SQLModel');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('langgenius/dify/orpc-contract-first', 'official', 'langgenius', 'dify', 'langgenius/dify', 'orpc-contract-first', 131375, 20455, 80, '2026-03-06T06:00:48Z', '2026-03-06T06:08:09.008Z', '0d56a651bf08ab6d497802a8deb4a73986b2648e8b52434bdc99d9f404f7ba4a', '{"id":"langgenius/dify/orpc-contract-first","name":"orpc-contract-first","description":{"en":"The orpc-contract-first skill helps developers implement oRPC contract-first API patterns in Dify frontend, benefiting those working with NextJS and low-code workflows.","zh":"oRPC 合约优先开发是指以合约为单一事实源，实现高效的前端开发。它包括 TanStack Query 集成和 typed 合约等功能","ja":"oRPC コントラクトファースト開発は、コントラクトを単一の事実源として、効率的なフロントエンド開発を実現するものです","ko":"oRPC 계약优先 개발은 계약을 단일的事实源로 하여 효율적인 프론트엔드 개발을 구현하는 것입니다","es":"El patrón de API oRPC Contract-First permite mantener un contrato como fuente de verdad única en Dify frontend","fr":"Le modèle d''API oRPC Contract-First permet de maintenir un contrat comme source de vérité unique dans Dify frontend","de":"Das oRPC Contract-First-API-Muster ermöglicht es, einen Vertrag als einzige Wahrheitsquelle in Dify-Frontend zu halten","pt":"O oRPC contract-first é um padrão de desenvolvimento que mantém o contrato como única fonte de verdade. Aprenda a implementá-lo em seu frontend Dify","ru":"oRPC contract-first - это шаблон разработки, который сохраняет контракт как единственный источник правды. Узнайте, как реализовать его в вашем frontend Dify","ar":"oRPC contract-first هو نمط تطوير يحافظ على العقد كمصدر وحيد للtruth. تعلم كيفية تنفيذه في واجهة المستخدم الأمامية Dify"},"owner":"langgenius","repo":"dify","repoPath":"langgenius/dify","stars":131375,"forks":20455,"updatedAt":"2026-03-06T06:00:48Z","topics":["agent","agentic-ai","agentic-framework","agentic-workflow","ai","automation","gemini","genai","gpt","gpt-4","llm","low-code","mcp","nextjs","no-code","openai","orchestration","python","rag","workflow"],"skillMd":{"name":"orpc-contract-first","description":"Guide for implementing oRPC contract-first API patterns in Dify frontend. Trigger when creating or updating contracts in web/contract, wiring router composition, integrating TanStack Query with typed contracts, migrating legacy service calls to oRPC, or deciding whether to call queryOptions directly vs extracting a helper or use-* hook in web/service.","bodyPreview":"# oRPC Contract-First Development\n\n## Intent\n\n- Keep contract as single source of truth in `web/contract/*`.\n- Default query usage: call-site `useQuery(consoleQuery|marketplaceQuery.xxx.queryOptions(...))` when endpoint behavior maps 1:1 to the contract.\n- Keep abstractions minimal and preserve TypeScript inference.\n\n## Minimal Structure\n\n```text\nweb/contract/\n├── base.ts\n├── router.ts\n├── marketplace.ts\n└── console/\n    ├── billing.ts\n    └── ...other domains\nweb/service/client.ts\n```\n\n## Core","body":"# oRPC Contract-First Development\n\n## Intent\n\n- Keep contract as single source of truth in `web/contract/*`.\n- Default query usage: call-site `useQuery(consoleQuery|marketplaceQuery.xxx.queryOptions(...))` when endpoint behavior maps 1:1 to the contract.\n- Keep abstractions minimal and preserve TypeScript inference.\n\n## Minimal Structure\n\n```text\nweb/contract/\n├── base.ts\n├── router.ts\n├── marketplace.ts\n└── console/\n    ├── billing.ts\n    └── ...other domains\nweb/service/client.ts\n```\n\n## Core Workflow\n\n1. Define contract in `web/contract/console/{domain}.ts` or `web/contract/marketplace.ts`\n   - Use `base.route({...}).output(type<...>())` as baseline.\n   - Add `.input(type<...>())` only when request has `params/query/body`.\n   - For `GET` without input, omit `.input(...)` (do not use `.input(type<unknown>())`).\n2. Register contract in `web/contract/router.ts`\n   - Import directly from domain files and nest by API prefix.\n3. Consume from UI call sites via oRPC query utils.\n\n```typescript\nimport { useQuery } from ''@tanstack/react-query''\nimport { consoleQuery } from ''@/service/client''\n\nconst invoiceQuery = useQuery(consoleQuery.billing.invoices.queryOptions({\n  staleTime: 5 * 60 * 1000,\n  throwOnError: true,\n  select: invoice => invoice.url,\n}))\n```\n\n## Query Usage Decision Rule\n\n1. Default: call site directly uses `*.queryOptions(...)`.\n2. If 3+ call sites share the same extra options (for example `retry: false`), extract a small queryOptions helper, not a `use-*` passthrough hook.\n3. Create `web/service/use-{domain}.ts` only for orchestration:\n   - Combine multiple queries/mutations.\n   - Share domain-level derived state or invalidation helpers.\n\n```typescript\nconst invoicesBaseQueryOptions = () =>\n  consoleQuery.billing.invoices.queryOptions({ retry: false })\n\nconst invoiceQuery = useQuery({\n  ...invoicesBaseQueryOptions(),\n  throwOnError: true,\n})\n```\n\n## Mutation Usage Decision Rule\n\n1. Default: call mutation helpers from `consoleQuery` / `marketplaceQuery`, for example `useMutation(consoleQuery.billing.bindPartnerStack.mutationOptions(...))`.\n2. If mutation flow is heavily custom, use oRPC clients as `mutationFn` (for example `consoleClient.xxx` / `marketplaceClient.xxx`), instead of generic handwritten non-oRPC mutation logic.\n\n## Key API Guide (`.key` vs `.queryKey` vs `.mutationKey`)\n\n- `.key(...)`:\n  - Use for partial matching operations (recommended for invalidation/refetch/cancel patterns).\n  - Example: `queryClient.invalidateQueries({ queryKey: consoleQuery.billing.key() })`\n- `.queryKey(...)`:\n  - Use for a specific query''s full key (exact query identity / direct cache addressing).\n- `.mutationKey(...)`:\n  - Use for a specific mutation''s full key.\n  - Typical use cases: mutation defaults registration, mutation-status filtering (`useIsMutating`, `queryClient.isMutating`), or explicit devtools grouping.\n\n## Anti-Patterns\n\n- Do not wrap `useQuery` with `options?: Partial<UseQueryOptions>`.\n- Do not split local `queryKey/queryFn` when oRPC `queryOptions` already exists and fits the use case.\n- Do not create thin `use-*` passthrough hooks for a single endpoint.\n- Reason: these patterns can degrade inference (`data` may become `unknown`, especially around `throwOnError`/`select`) and add unnecessary indirection.\n\n## Contract Rules\n\n- **Input structure**: Always use `{ params, query?, body? }` format\n- **No-input GET**: Omit `.input(...)`; do not use `.input(type<unknown>())`\n- **Path params**: Use `{paramName}` in path, match in `params` object\n- **Router nesting**: Group by API prefix (e.g., `/billing/*` -> `billing: {}`)\n- **No barrel files**: Import directly from specific files\n- **Types**: Import from `@/types/`, use `type<T>()` helper\n- **Mutations**: Prefer `mutationOptions`; use explicit `mutationKey` mainly for defaults/filtering/devtools\n\n## Type Export\n\n```typescript\nexport type ConsoleInputs = InferContractRouterInputs<typeof consoleRouterContract>\n```\n"},"category":"official","lastSynced":"2026-03-06T06:08:09.008Z","seo":{"title":{"en":"orpc-contract-first: Contract-First API Setup Guide | AI ...","zh":"oRPC 合约优先开发设置指南","ja":"oRPC コントラクトファースト開発ベストプラクティス","ko":"oRPC 계약优先 개발 가이드","es":"Guía de configuración oRPC Contract-First para desarrolla...","fr":"Guide de mise en place oRPC Contract-First pour les dével...","de":"Einrichtungsleitfaden für oRPC Contract-First-Entwickler","pt":"Guia de Configuração oRPC Contract-First para Desenvolved...","ru":"Настройка oRPC Contract-First: Лучшие Практики для Разраб...","ar":"إعداد مرشد oRPC Contract-First لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement oRPC contract-first API patterns in Dify frontend with ease. Learn to trigger contracts, wire router composition, and integrate Tan...","zh":"了解如何使用 oRPC 合约优先 API 模式实现高效的前端开发，包括 TanStack Query 集成和 typed 合约","ja":"oRPC コントラクトファースト API パターンを使用した効率的なフロントエンド開発方法について学びます","ko":"oRPC 계약优先 API 패턴을 사용하여 효율적인 프론트엔드 개발을 구현하는 방법을 알아보세요","es":"Aprende a implementar patrones de API oRPC Contract-First en Dify frontend con este tutorial detallado","fr":"Découvrez comment mettre en œuvre des modèles d''API oRPC Contract-First dans Dify frontend avec ce didacticiel détaillé","de":"Erfahren Sie, wie Sie oRPC Contract-First-API-Muster in Dify-Frontend implementieren, mit diesem detaillierten Tutorial","pt":"Aprenda a implementar padrões de API oRPC contract-first em frontend Dify. Descubra como manter contratos como única fonte de verdade","ru":"Узнайте, как реализовать шаблоны API oRPC contract-first в frontend Dify. Откройте для себя, как сохранить контракты как единственный источник правды","ar":"تعلم كيفية تنفيذ أنماط API oRPC contract-first في واجهة المستخدم الأمامية Dify. اكتشف كيفية الحفاظ على العقود كمصدر وحيد للtruth"},"definition":{"en":"orpc-contract-first is a development pattern guiding the implementation of oRPC contract-first APIs in Dify frontend, emphasizing typed contracts and minimal abstractions.","zh":"oRPC 合约优先开发是一种以合约为中心的 API 设计模式","ja":"oRPC コントラクトファースト開発は、コントラクトを中心とした API デザインパターンです","ko":"oRPC 계약优先 개발은 계약을 중심으로 하는 API 설계 패턴입니다","es":"oRPC Contract-First es un patrón de diseño de API que mantiene el contrato como fuente de verdad única","fr":"oRPC Contract-First est un modèle de conception d''API qui maintient le contrat comme source de vérité unique","de":"oRPC Contract-First ist ein API-Designmuster, das den Vertrag als einzige Wahrheitsquelle hält","pt":"oRPC contract-first é um padrão de desenvolvimento que prioriza a manutenção do contrato como única fonte de verdade","ru":"oRPC contract-first - это шаблон разработки, который отдает приоритет сохранению контракта как единственного источника правды","ar":"oRPC contract-first هو نمط تطوير يأتي في المقام الأول للحفاظ على العقد كمصدر وحيد للtruth"},"features":{"en":["Implements oRPC contract-first API patterns in Dify frontend","Triggers contracts when creating or updating in web/contract","Wires router composition for seamless integration","Integrates TanStack Query with typed contracts for efficient data management","Migrates legacy service calls to oRPC for improved performance","Supports decision-making for direct queryOptions calls or extracting helper functions"],"zh":["以合约为单一事实源","TanStack Query 集成","Typed 合约支持","Legacy 服务调用迁移","queryOptions 的直接调用或辅助函数抽取"],"ja":["コントラクトを単一の事実源として","TanStack Query 統合","型付けコントラクトサポート","レガシーサービス呼び出しの移行","queryOptions の直接呼び出しまたはヘルパー関数抽出"],"ko":["계약을 단일的事实源로","TanStack Query 통합","타입화된 계약 지원","레거시 서비스 호출 마이그레이션","queryOptions의 직접 호출 또는 헬퍼 함수 추출"],"es":["Mantiene el contrato como fuente de verdad única en web/contract/*","Utiliza TanStack Query con contratos tipados","Permite la migración de llamadas de servicio heredadas a oRPC","Soporta la composición de routers y la integración con web/service","Mantiene abstracciones mínimas y preserva la inferencia de TypeScript"],"fr":["Maintient le contrat comme source de vérité unique dans web/contract/*","Utilise TanStack Query avec des contrats typés","Permet la migration d''appels de service hérités vers oRPC","Prend en charge la composition de routers et l''intégration avec web/service","Maintient des abstractions minimales et préserve l''inférence de TypeScript"],"de":["Hält den Vertrag als einzige Wahrheitsquelle in web/contract/*","Verwendet TanStack Query mit typisierten Verträgen","Ermöglicht die Migration von veralteten Serviceaufrufen zu oRPC","Unterstützt die Router-Zusammensetzung und die Integration mit web/service","Hält Abstraktionen minimal und bewahrt die TypeScript-Inferez"],"pt":["Manter contratos como única fonte de verdade em web/contract/*","Uso de queryOptions para chamar endpoints de forma eficiente","Integração com TanStack Query para contratos tipados","Migração de chamadas de serviço legadas para oRPC","Uso de abstrações mínimas para preservar a inferência do TypeScript"],"ru":["Сохранение контрактов как единственный источник правды в web/contract/*","Использование queryOptions для вызова endpoints эффективно","Интеграция с TanStack Query для типизированных контрактов","Миграция устаревших вызовов сервиса на oRPC","Использование минимальных абстракций для сохранения вывода TypeScript"],"ar":["الحفاظ على العقود كمصدر وحيد للtruth في web/contract/*","استخدام queryOptions للاتصال بالنقاط النهاية بفعالية","التكامل مع TanStack Query للعقود المرتبطة","هجرة مكالمات الخدمة القديمة إلى oRPC","استخدام التغليف الأدنى للحفاظ على استنتاج TypeScript"]},"keywords":{"en":["how to use orpc-contract-first","orpc-contract-first setup guide","orpc-contract-first vs REST API","orpc-contract-first alternative","orpc-contract-first install","what is orpc-contract-first","orpc-contract-first tutorial","orpc-contract-first examples","orpc-contract-first best practices"],"zh":["oRPC 合约优先开发","AI エージェント","TanStack Query","Typed 合约","Legacy 服务调用迁移","queryOptions","合约优先 API 设计"],"ja":["oRPC コントラクトファースト開発","AIエージェント","TanStack Query","型付けコントラクト","レガシーサービス呼び出しの移行","queryOptions","コントラクトファースト API デザイン"],"ko":["oRPC 계약优先 개발","AI 에이전트","TanStack Query","타입화된 계약","레거시 서비스 호출 마이그레이션","queryOptions","계약优先 API 설계"],"es":["oRPC Contract-First","patrones de API","Dify frontend","TanStack Query","TypeScript","migración de servicios","composición de routers","integración con web/service","Agente de IA","Herramientas de IA"],"fr":["oRPC Contract-First","modèles d''API","Dify frontend","TanStack Query","TypeScript","migration de services","composition de routers","intégration avec web/service","Agent d''IA","Outils d''IA"],"de":["oRPC Contract-First","API-Designmuster","Dify-Frontend","TanStack Query","TypeScript","Migration von Diensten","Zusammensetzung von Routern","Integration mit web/service","KI-Agent","KI-Tools"],"pt":["oRPC contract-first","desenvolvimento de frontend","Dify","API contract-first","TanStack Query","TypeScript","migração de serviço","otimização de endpoints"],"ru":["oRPC contract-first","разработка frontend","Dify","API contract-first","TanStack Query","TypeScript","миграция сервиса","оптимизация endpoints"],"ar":["oRPC contract-first","تطوير واجهة المستخدم الأمامية","Dify","API contract-first","TanStack Query","TypeScript","هجرة خدمة","تحسين نقاط النهاية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing to implement contract-first API patterns with oRPC in Dify frontend applications.","zh":"非常适合需要在Dify前端应用程序中使用oRPC实现合约优先API模式的全栈代理","ja":"DifyフロントエンドアプリケーションでoRPCを使用して契約ファーストAPIパターンを実装する必要があるフルスタックエージェントに最適","ko":"Dify 프론트엔드 애플리케이션에서 oRPC를 사용하여 계약 우선 API 패턴을 구현해야 하는 풀스택 에이전트에 적합","es":"Perfecto para agentes Full-Stack que necesitan implementar patrones de API contract-first con oRPC en aplicaciones frontend de Dify.","fr":"Parfait pour les agents Full-Stack ayant besoin de mettre en œuvre des modèles d''API contract-first avec oRPC dans les applications frontend Dify.","de":"Perfekt für Full-Stack-Agents, die Vertrags-erst-API-Muster mit oRPC in Dify-Frontend-Anwendungen implementieren müssen.","pt":"Perfeito para Agentes Full-Stack que precisam implementar padrões de API de contrato primeiro com o oRPC em aplicações frontend do Dify.","ru":"Идеально подходит для полнофункциональных агентов, которым необходимо реализовать шаблоны API с контрактом в первую очередь с помощью oRPC в приложениях frontend Dify.","ar":"مثالي لعميل الويب الكامل الذين يحتاجون إلى تنفيذ أنماط API من أولوية العقد مع oRPC في تطبيقات واجهة المستخدم الأمامية Dify."},"recommendation":{"en":"Empowers agents to maintain a single source of truth for contracts in `web/contract/*`, integrate TanStack Query with typed contracts, and decide between direct queryOptions calls or extracting helper functions, all while preserving TypeScript inference and minimal abstractions.","zh":"赋予代理维护`web/contract/*`中的单一事实来源，集成TanStack Query与类型化合约，并在保留TypeScript推理和最小抽象的同时决定直接调用queryOptions或提取辅助函数","ja":"エージェントが`web/contract/*`の中に単一の真実源を維持し、TanStack Queryを型付き契約と統合し、TypeScriptの推論と最小限の抽象を保持しながら、直接queryOptionsを呼び出すかヘルパー関数を抽出するかを決定することを可能にします","ko":"에이전트가 `web/contract/*`에 단일的事実 원천을 유지하고 TanStack Query를 유형화된 계약과 통합하며 TypeScript 추론과 최소한의 추상을 보존하는 동시에 직접 쿼리 옵션을 호출하거나 헬퍼 함수를 추출할지 결정할 수 있도록 합니다","es":"Habilita a los agentes a mantener una sola fuente de verdad para los contratos en `web/contract/*`, integrar TanStack Query con contratos tipados, y decidir entre llamadas directas a queryOptions o la extracción de funciones de ayuda, todo mientras se preserva la inferencia de TypeScript y las abstracciones mínimas.","fr":"Permet aux agents de maintenir une seule source de vérité pour les contrats dans `web/contract/*`, d''intégrer TanStack Query avec des contrats typés, et de choisir entre des appels directs à queryOptions ou l''extraction de fonctions d''aide, le tout en préservant l''inférence de TypeScript et les abstractions minimales.","de":"Ermöglicht es Agenten, eine einzige Wahrheitsquelle für Verträge in `web/contract/*` zu erhalten, TanStack Query mit typisierten Verträgen zu integrieren und zwischen direkten queryOptions-Aufrufen oder der Extraktion von Hilfsfunktionen zu entscheiden, während die TypeScript-Inferez und minimale Abstraktionen erhalten bleiben.","pt":"Permite que os agentes mantenham uma única fonte de verdade para contratos em `web/contract/*`, integrem a TanStack Query com contratos tipados, e decidam entre chamadas diretas de queryOptions ou extração de funções de ajuda, tudo isso preservando a inferência do TypeScript e abstrações mínimas.","ru":"Позволяет агентам поддерживать единственный источник правды для контрактов в `web/contract/*`, интегрировать TanStack Query с типизированными контрактами и решать, использовать ли прямые вызовы queryOptions или извлекать вспомогательные функции, сохраняя при этом вывод типов TypeScript и минимальные абстракции.","ar":"يسمح للوكلاء الحفاظ على مصدر وحيد للحقيقة للعقود في `web/contract/*`، ودمج TanStack Query مع العقود الموصوفة، والقرار بين مكالمات queryOptions المباشرة أو استخراج دوال مساعدة، مع الحفاظ على استنتاج TypeScript والأبستракتات المعدلة."},"useCases":{"en":["Implementing oRPC contract-first API patterns in Dify frontend","Migrating legacy service calls to oRPC","Integrating TanStack Query with typed contracts for robust data fetching","Wiring router composition for efficient API routing"],"zh":["在Dify前端中实现oRPC合约优先API模式","将遗留服务调用迁移到oRPC","将TanStack Query与类型化合约集成以实现强大的数据获取","为高效的API路由而构建路由器组成"],"ja":["DifyフロントエンドでoRPC契約ファーストAPIパターンを実装する","レガシーサービス呼び出しをoRPCに移行する","TanStack Queryを型付き契約と統合して堅牢なデータ取得を実現する","効率的なAPIルーティングのためにルーターコンポジションを構築する"],"ko":["Dify 프론트엔드에서 oRPC 계약 우선 API 패턴을 구현","레거시 서비스 호출을 oRPC로 마이그레이션","TanStack Query를 유형화된 계약과 통합하여 강력한 데이터 가져오기","효율적인 API 라우팅을 위한 라우터 조성을 구축"],"es":["Implementar patrones de API contract-first con oRPC en aplicaciones frontend de Dify","Migrar llamadas de servicio heredadas a oRPC","Integrar TanStack Query con contratos tipados para una recopilación de datos robusta","Conectar la composición del enrutador para un enrutamiento de API eficiente"],"fr":["Mettre en œuvre des modèles d''API contract-first avec oRPC dans les applications frontend Dify","Migrer des appels de service hérités vers oRPC","Intégrer TanStack Query avec des contrats typés pour une collecte de données robuste","Raccorder la composition du routeur pour un routage d''API efficace"],"de":["Implementierung von Vertrags-erst-API-Mustern mit oRPC in Dify-Frontend-Anwendungen","Migration von veralteten Serviceaufrufen zu oRPC","Integration von TanStack Query mit typisierten Verträgen für eine robuste Datenerfassung","Verbindung der Router-Zusammensetzung für ein effizientes API-Routing"],"pt":["Implementação de padrões de API de contrato primeiro com o oRPC em aplicações frontend do Dify","Migração de chamadas de serviço legadas para o oRPC","Integração da TanStack Query com contratos tipados para busca de dados robusta","Conexão da composição do roteador para roteamento de API eficiente"],"ru":["Реализация шаблонов API с контрактом в первую очередь с помощью oRPC в приложениях frontend Dify","Миграция устаревших вызовов служб на oRPC","Интеграция TanStack Query с типизированными контрактами для надежной выборки данных","Подключение композиции маршрутизатора для эффективного маршрутизации API"],"ar":["تنفيذ أنماط API من أولوية العقد مع oRPC في تطبيقات واجهة المستخدم الأمامية Dify","هجرة مكالمات الخدمة القديمة إلى oRPC","دمج TanStack Query مع العقود الموصوفة لاسترجاع البيانات القوي","ربط تركيبة الموجه لتحویل API الفعال"]},"limitations":{"en":["Requires TypeScript for inference and typing","Limited to oRPC and Dify frontend applications","Needs TanStack Query for data fetching and caching"],"zh":["需要TypeScript进行推理和类型化","仅限于oRPC和Dify前端应用程序","需要TanStack Query进行数据获取和缓存"],"ja":["推論と型付けのためにTypeScriptが必要","oRPCとDifyフロントエンドアプリケーションに限定される","データ取得とキャッシュのためにTanStack Queryが必要"],"ko":["추론과 유형화에 대한 TypeScript 필요","oRPC 및 Dify 프론트엔드 애플리케이션으로 제한","데이터 가져오기 및 캐싱을 위한 TanStack Query 필요"],"es":["Requiere TypeScript para la inferencia y la tipificación","Limitado a aplicaciones oRPC y frontend de Dify","Necesita TanStack Query para la recopilación y el almacenamiento en caché de datos"],"fr":["Nécessite TypeScript pour l''inférence et le typage","Limité aux applications oRPC et frontend Dify","Nécessite TanStack Query pour la collecte et le mise en cache des données"],"de":["Benötigt TypeScript für die Inferenz und die Typisierung","Begrenzt auf oRPC- und Dify-Frontend-Anwendungen","Benötigt TanStack Query für die Datenerfassung und -caching"],"pt":["Requer TypeScript para inferência e tipagem","Limitado a aplicações oRPC e frontend do Dify","Necessita TanStack Query para busca e cache de dados"],"ru":["Требует TypeScript для вывода типов и типизации","Ограничен приложениями oRPC и frontend Dify","Требует TanStack Query для выборки и кэширования данных"],"ar":["يتطلب TypeScript للاستنتاج والتصنيف","محدود لتطبيقات oRPC وواجهة المستخدم الأمامية Dify","يحتاج إلى TanStack Query لاسترجاع البيانات وتخزينها مؤقتا"]},"version":4},"contentHash":"0d56a651bf08ab6d497802a8deb4a73986b2648e8b52434bdc99d9f404f7ba4a","repoEtag":"W/\"8b79270de464b84537dd173d2e750efb4b05e743496516f4c20a14f45fafde09\"","qualityScore":80}');
