INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('langgenius/dify/orpc-contract-first', 'orpc-contract-first', 'langgenius', 'dify', 'official', 'orpc-contract-first langgenius dify official agent agentic-ai agentic-framework agentic-workflow ai automation gemini genai gpt gpt-4 llm low-code mcp nextjs no-code openai orchestration python rag workflow The orpc-contract-first skill helps developers implement oRPC contract-first API patterns in Dify frontend, benefiting those working with NextJS and low-code workflows. oRPC 合约优先开发是指以合约为单一事实源，实现高效的前端开发。它包括 TanStack Query 集成和 typed 合约等功能 oRPC コントラクトファースト開発は、コントラクトを単一の事実源として、効率的なフロントエンド開発を実現するものです oRPC 계약优先 개발은 계약을 단일的事实源로 하여 효율적인 프론트엔드 개발을 구현하는 것입니다 El patrón de API oRPC Contract-First permite mantener un contrato como fuente de verdad única en Dify frontend Le modèle d''API oRPC Contract-First permet de maintenir un contrat comme source de vérité unique dans Dify frontend Das oRPC Contract-First-API-Muster ermöglicht es, einen Vertrag als einzige Wahrheitsquelle in Dify-Frontend zu halten O oRPC contract-first é um padrão de desenvolvimento que mantém o contrato como única fonte de verdade. Aprenda a implementá-lo em seu frontend Dify oRPC contract-first - это шаблон разработки, который сохраняет контракт как единственный источник правды. Узнайте, как реализовать его в вашем frontend Dify oRPC contract-first هو نمط تطوير يحافظ على العقد كمصدر وحيد للtruth. تعلم كيفية تنفيذه في واجهة المستخدم الأمامية Dify how to use orpc-contract-first orpc-contract-first setup guide orpc-contract-first vs REST API orpc-contract-first alternative orpc-contract-first install what is orpc-contract-first orpc-contract-first tutorial orpc-contract-first examples orpc-contract-first best practices oRPC 合约优先开发 AI エージェント TanStack Query Typed 合约 Legacy 服务调用迁移 queryOptions 合约优先 API 设计 Implements oRPC contract-first API patterns in Dify frontend Triggers contracts when creating or updating in web/contract Wires router composition for seamless integration Integrates TanStack Query with typed contracts for efficient data management Migrates legacy service calls to oRPC for improved performance Supports decision-making for direct queryOptions calls or extracting helper functions orpc-contract-first is a development pattern guiding the implementation of oRPC contract-first APIs in Dify frontend, emphasizing typed contracts and minimal abstractions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/gha-security-review', 'official', 'getsentry', 'skills', 'getsentry/skills', 'gha-security-review', 360, 11, 80, '2026-03-06T00:20:36Z', '2026-03-06T05:10:26.064Z', '4fc6ccff59d035fb66da3f1a514d3420232d565563d59b0c2e473222c3af364d', '{"id":"getsentry/skills/gha-security-review","name":"gha-security-review","description":{"en":"The gha-security-review skill audits GitHub Actions workflows for security vulnerabilities, providing concrete exploitation scenarios for identified threats, benefiting developers and security teams.","zh":"gha-security-review AI 工具提供了 GitHub Actions 工作流安全审查，检测漏洞并防止代码注入、凭证盗窃和供应链攻击","ja":"gha-security-review AIエージェントは、GitHub Actions のワークフローを安全にレビューし、脆弱性を检测し、コードインジェクション、資格情報の盗難、サプライチェーン攻撃を防ぐ","ko":"gha-security-review AI 도구는 GitHub Actions 워크플로中的 보안 리뷰를 제공하여 취약점을检测하고 코드 주입, 자격증명 도용, 공급망 공격을 방지","es":"gha-security-review analiza las vulnerabilidades de explotación en los flujos de trabajo de GitHub Actions. Identifica ataques de inyección de expresiones, robo de credenciales y ataques de cadena de suministro","fr":"gha-security-review analyse les vulnérabilités d''exploitation dans les flux de travail GitHub Actions. Il identifie les attaques d''injection d''expressions, les vols de crédentiels et les attaques de chaîne d''approvisionnement","de":"gha-security-review analysiert die Ausnutzungs-Schwachstellen in GitHub Actions-Workflows. Es identifiziert Angriffe auf Ausdrucksinjektion, Credential-Diebstahl und Lieferkettengriffe","pt":"O gha-security-review é uma ferramenta de análise de segurança para workflows do GitHub Actions, que ajuda a identificar vulnerabilidades e prevenir ataques de suprimento de cadeia","ru":"ИИ Агент gha-security-review - это инструмент анализа безопасности для рабочих процессов GitHub Actions, который помогает выявить уязвимости и предотвратить атаки по цепочке поставок","ar":"gha-security-review هو أداة فحص أمان لسير العمل على GitHub Actions، تساعد على تحديد الثغرات الأمنية ومنع الهجمات على سلسلة التوريد"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"gha-security-review","description":"GitHub Actions security review for workflow exploitation vulnerabilities. Use when asked to review GitHub Actions, audit workflows, check CI security, GHA security, workflow security review, or review .github/workflows/ for pwn requests, expression injection, credential theft, and supply chain attacks. Exploitation-focused with concrete PoC scenarios.","bodyPreview":"<!--\nAttack patterns and real-world examples sourced from the HackerBot Claw campaign analysis\nby StepSecurity (2025): https://www.stepsecurity.io/blog/hackerbot-claw-github-actions-exploitation\n-->\n\n# GitHub Actions Security Review\n\nFind exploitable vulnerabilities in GitHub Actions workflows. Every finding MUST include a concrete exploitation scenario — if you can''t build the attack, don''t report it.\n\nThis skill encodes attack patterns from real GitHub Actions exploits — not generic CI/CD theo","body":"<!--\nAttack patterns and real-world examples sourced from the HackerBot Claw campaign analysis\nby StepSecurity (2025): https://www.stepsecurity.io/blog/hackerbot-claw-github-actions-exploitation\n-->\n\n# GitHub Actions Security Review\n\nFind exploitable vulnerabilities in GitHub Actions workflows. Every finding MUST include a concrete exploitation scenario — if you can''t build the attack, don''t report it.\n\nThis skill encodes attack patterns from real GitHub Actions exploits — not generic CI/CD theory.\n\n## Scope\n\nReview the workflows provided (file, diff, or repo). Research the codebase as needed to trace complete attack paths before reporting.\n\n### Files to Review\n\n- `.github/workflows/*.yml` — all workflow definitions\n- `action.yml` / `action.yaml` — composite actions in the repo\n- `.github/actions/*/action.yml` — local reusable actions\n- Config files loaded by workflows: `CLAUDE.md`, `AGENTS.md`, `Makefile`, shell scripts under `.github/`\n\n### Out of Scope\n\n- Workflows in other repositories (only note the dependency)\n- GitHub App installation permissions (note if relevant)\n\n## Threat Model\n\nOnly report vulnerabilities exploitable by an **external attacker** — someone **without** write access to the repository. The attacker can open PRs from forks, create issues, and post comments. They cannot push to branches, trigger `workflow_dispatch`, or trigger manual workflows.\n\n**Do not flag** vulnerabilities that require write access to exploit:\n- `workflow_dispatch` input injection — requires write access to trigger\n- Expression injection in `push`-only workflows on protected branches\n- `workflow_call` input injection where all callers are internal\n- Secrets in `workflow_dispatch`/`schedule`-only workflows\n\n## Confidence\n\nReport only **HIGH** and **MEDIUM** confidence findings. Do not report theoretical issues.\n\n| Confidence | Criteria | Action |\n|---|---|---|\n| **HIGH** | Traced the full attack path, confirmed exploitable | Report with exploitation scenario and fix |\n| **MEDIUM** | Attack path partially confirmed, uncertain link | Report as needs verification |\n| **LOW** | Theoretical or mitigated elsewhere | Do not report |\n\nFor each HIGH finding, provide all five elements:\n\n1. **Entry point** — How does the attacker get in? (fork PR, issue comment, branch name, etc.)\n2. **Payload** — What does the attacker send? (actual code/YAML/input)\n3. **Execution mechanism** — How does the payload run? (expression expansion, checkout + script, etc.)\n4. **Impact** — What does the attacker gain? (token theft, code execution, repo write access)\n5. **PoC sketch** — Concrete steps an attacker would follow\n\nIf you cannot construct all five, report as MEDIUM (needs verification).\n\n---\n\n## Step 1: Classify Triggers and Load References\n\nFor each workflow, identify triggers and load the appropriate reference:\n\n| Trigger / Pattern | Load Reference |\n|---|---|\n| `pull_request_target` | `references/pwn-request.md` |\n| `issue_comment` with command parsing | `references/comment-triggered-commands.md` |\n| `${{ }}` in `run:` blocks | `references/expression-injection.md` |\n| PATs / deploy keys / elevated credentials | `references/credential-escalation.md` |\n| Checkout PR code + config file loading | `references/ai-prompt-injection-via-ci.md` |\n| Third-party actions (especially unpinned) | `references/supply-chain.md` |\n| `permissions:` block or secrets usage | `references/permissions-and-secrets.md` |\n| Self-hosted runners, cache/artifact usage | `references/runner-infrastructure.md` |\n| Any confirmed finding | `references/real-world-attacks.md` |\n\nLoad references selectively — only what''s relevant to the triggers found.\n\n## Step 2: Check for Vulnerability Classes\n\n### Check 1: Pwn Request\n\nDoes the workflow use `pull_request_target` AND check out fork code?\n- Look for `actions/checkout` with `ref:` pointing to PR head\n- Look for local actions (`./.github/actions/`) that would come from the fork\n- Check if any `run:` step executes code from the checked-out PR\n\n### Check 2: Expression Injection\n\nAre `${{ }}` expressions used inside `run:` blocks in externally-triggerable workflows?\n- Map every `${{ }}` expression in every `run:` step\n- Confirm the value is attacker-controlled (PR title, branch name, comment body — not numeric IDs, SHAs, or repository names)\n- Confirm the expression is in a `run:` block, not `if:`, `with:`, or job-level `env:`\n\n### Check 3: Unauthorized Command Execution\n\nDoes an `issue_comment`-triggered workflow execute commands without authorization?\n- Is there an `author_association` check?\n- Can any GitHub user trigger the command?\n- Does the command handler also use injectable expressions?\n\n### Check 4: Credential Escalation\n\nAre elevated credentials (PATs, deploy keys) accessible to untrusted code?\n- What''s the blast radius of each secret?\n- Could a compromised workflow steal long-lived tokens?\n\n### Check 5: Config File Poisoning\n\nDoes the workflow load configuration from PR-supplied files?\n- AI agent instructions: `CLAUDE.md`, `AGENTS.md`, `.cursorrules`\n- Build configuration: `Makefile`, shell scripts\n\n### Check 6: Supply Chain\n\nAre third-party actions securely pinned?\n\n### Check 7: Permissions and Secrets\n\nAre workflow permissions minimal? Are secrets properly scoped?\n\n### Check 8: Runner Infrastructure\n\nAre self-hosted runners, caches, or artifacts used securely?\n\n## Safe Patterns (Do Not Flag)\n\nBefore reporting, check if the pattern is actually safe:\n\n| Pattern | Why Safe |\n|---|---|\n| `pull_request_target` WITHOUT checkout of fork code | Never executes attacker code |\n| `${{ github.event.pull_request.number }}` in `run:` | Numeric only — not injectable |\n| `${{ github.repository }}` / `github.repository_owner` | Repo owner controls this |\n| `${{ secrets.* }}` | Not an expression injection vector |\n| `${{ }}` in `if:` conditions | Evaluated by Actions runtime, not shell |\n| `${{ }}` in `with:` inputs | Passed as string parameters, not shell-evaluated |\n| Actions pinned to full SHA | Immutable reference |\n| `pull_request` trigger (not `_target`) | Runs in fork context with read-only token |\n| Any expression in `workflow_dispatch`/`schedule`/`push` to protected branches | Requires write access — outside threat model |\n\n**Key distinction:** `${{ }}` is dangerous in `run:` blocks (shell expansion) but safe in `if:`, `with:`, and `env:` at the job/step level (Actions runtime evaluation).\n\n## Step 3: Validate Before Reporting\n\nBefore including any finding, read the actual workflow YAML and trace the complete attack path:\n\n1. **Read the full workflow** — don''t rely on grep output alone\n2. **Trace the trigger** — confirm the event and check `if:` conditions that gate execution\n3. **Trace the expression/checkout** — confirm it''s in a `run:` block or actually references fork code\n4. **Confirm attacker control** — verify the value maps to something an external attacker sets\n5. **Check existing mitigations** — env var wrapping, author_association checks, restricted permissions, SHA pinning\n\nIf any link is broken, mark MEDIUM (needs verification) or drop the finding.\n\n**If no checks produced a finding, report zero findings. Do not invent issues.**\n\n## Step 4: Report Findings\n\n````markdown\n## GitHub Actions Security Review\n\n### Findings\n\n#### [GHA-001] [Title] (Severity: Critical/High/Medium)\n- **Workflow**: `.github/workflows/release.yml:15`\n- **Trigger**: `pull_request_target`\n- **Confidence**: HIGH — confirmed through attack path tracing\n- **Exploitation Scenario**:\n  1. [Step-by-step attack]\n- **Impact**: [What attacker gains]\n- **Fix**: [Code that fixes the issue]\n\n### Needs Verification\n[MEDIUM confidence items with explanation of what to verify]\n\n### Reviewed and Cleared\n[Workflows reviewed and confirmed safe]\n````\n\nIf no findings: \"No exploitable vulnerabilities identified. All workflows reviewed and cleared.\"\n"},"category":"official","lastSynced":"2026-03-06T05:10:26.064Z","seo":{"title":{"en":"gha-security-review: GitHub Actions Security Audit Setup ...","zh":"GitHub Actions 安全审查设置指南 - gha-security-review","ja":"GitHub Actions セキュリティレビューのベストプラクティス - gha-security-review","ko":"GitHub Actions 보안 리뷰 설정 가이드 - gha-security-review","es":"Guía de configuración de gha-security-review para vulnera...","fr":"Guide de configuration de gha-security-review pour les vu...","de":"Konfigurationsleitfaden für gha-security-review zur Erken...","pt":"Guia de Configuração do gha-security-review para Análise ...","ru":"Настройка ИИ Агента gha-security-review для Анализа Безоп...","ar":"دليل إعداد gha-security-review لمعرفة أمان 워크フロー"},"description":{"en":"Discover vulnerabilities in GitHub Actions workflows with gha-security-review. Learn how to audit workflows and prevent exploitation attacks - get started now!","zh":"使用 gha-security-review AI 工具检测 GitHub Actions 工作流中的漏洞，防止代码注入、凭证盗窃和供应链攻击","ja":"gha-security-review AIエージェントを使用して、GitHub Actions のワークフローを脆弱性から保護し、コードインジェクション、資格情報の盗難、サプライチェーン攻撃を防ぐ","ko":"gha-security-review AI 도구를 사용하여 GitHub Actions 워크플로中的 취약점을检测하고 코드 주입, 자격증명 도용, 공급망 공격을 방지","es":"Descubre cómo proteger tus flujos de trabajo de GitHub con gha-security-review y detecta vulnerabilidades de explotación","fr":"Découvrez comment protéger vos flux de travail GitHub avec gha-security-review et détecter les vulnérabilités d''exploitation","de":"Erfahren Sie, wie Sie Ihre GitHub-Workflows mit gha-security-review schützen und Ausnutzungs-Schwachstellen erkennen","pt":"Descubra como o gha-security-review ajuda a identificar vulnerabilidades em workflows do GitHub Actions e proteja contra ataques de suprimento de cadeia","ru":"Узнайте, как ИИ Агент gha-security-review помогает выявить уязвимости в рабочих процессах GitHub Actions и защитить от атак по цепочке поставок","ar":"تعرف على كيفية استخدام gha-security-review لتحديد الثغرات الأمنية في سير العمل على GitHub Actions وحماية نفسك من الهجمات على سلسلة التوريد"},"definition":{"en":"gha-security-review is a GitHub Actions security audit tool that identifies exploitable vulnerabilities in workflows, including expression injection and credential theft attacks.","zh":"gha-security-review 是一种 AI 工具，用于检测 GitHub Actions 工作流中的漏洞","ja":"gha-security-review は、GitHub Actions のワークフローを安全にレビューする AIエージェント","ko":"gha-security-review는 GitHub Actions 워크플로中的 취약점을检测하는 AI 도구","es":"gha-security-review es una herramienta de revisión de seguridad para flujos de trabajo de GitHub Actions que detecta vulnerabilidades de explotación","fr":"gha-security-review est un outil de révision de sécurité pour les flux de travail GitHub Actions qui détec