INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/gha-security-review', 'gha-security-review', 'getsentry', 'skills', 'official', 'gha-security-review getsentry skills official tag-production The gha-security-review skill audits GitHub Actions workflows for security vulnerabilities, providing concrete exploitation scenarios for identified threats, benefiting developers and security teams. gha-security-review AI 工具提供了 GitHub Actions 工作流安全审查，检测漏洞并防止代码注入、凭证盗窃和供应链攻击 gha-security-review AIエージェントは、GitHub Actions のワークフローを安全にレビューし、脆弱性を检测し、コードインジェクション、資格情報の盗難、サプライチェーン攻撃を防ぐ gha-security-review AI 도구는 GitHub Actions 워크플로中的 보안 리뷰를 제공하여 취약점을检测하고 코드 주입, 자격증명 도용, 공급망 공격을 방지 gha-security-review analiza las vulnerabilidades de explotación en los flujos de trabajo de GitHub Actions. Identifica ataques de inyección de expresiones, robo de credenciales y ataques de cadena de suministro gha-security-review analyse les vulnérabilités d''exploitation dans les flux de travail GitHub Actions. Il identifie les attaques d''injection d''expressions, les vols de crédentiels et les attaques de chaîne d''approvisionnement gha-security-review analysiert die Ausnutzungs-Schwachstellen in GitHub Actions-Workflows. Es identifiziert Angriffe auf Ausdrucksinjektion, Credential-Diebstahl und Lieferkettengriffe O gha-security-review é uma ferramenta de análise de segurança para workflows do GitHub Actions, que ajuda a identificar vulnerabilidades e prevenir ataques de suprimento de cadeia ИИ Агент gha-security-review - это инструмент анализа безопасности для рабочих процессов GitHub Actions, который помогает выявить уязвимости и предотвратить атаки по цепочке поставок gha-security-review هو أداة فحص أمان لسير العمل على GitHub Actions، تساعد على تحديد الثغرات الأمنية ومنع الهجمات على سلسلة التوريد how to use gha-security-review gha-security-review setup guide github actions security audit gha-security-review alternative gha-security-review vs competitor what is gha-security-review github actions workflow security gha-security-review install ci/cd security review GitHub Actions 安全审查 gha-security-review AI 工具 代码注入 凭证盗窃 供应链攻击 CI/CD 安全 Identifies exploitable vulnerabilities in GitHub Actions workflows Provides concrete exploitation scenarios for identified threats Audits .github/workflows/ for pwn requests and supply chain attacks Encodes attack patterns from real GitHub Actions exploits Includes scenarios for expression injection and credential theft attacks Supports review of CI/CD security and workflow security gha-security-review is a GitHub Actions security audit tool that identifies exploitable vulnerabilities in workflows, including expression injection and credential theft attacks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/find-bugs', 'official', 'getsentry', 'skills', 'getsentry/skills', 'find-bugs', 360, 11, 79, '2026-03-06T00:20:36Z', '2026-03-06T05:08:02.659Z', '08664c3698f89116a4b04d12f699f95cff1aadb725da353b7f24f8ad73b02003', '{"id":"getsentry/skills/find-bugs","name":"find-bugs","description":{"en":"The find-bugs skill reviews local branch changes for bugs, security vulnerabilities, and code quality issues, benefiting developers in need of thorough code audits.","zh":"Find Bugs是一种AI工具，用于查找代码错误、安全漏洞和代码质量问题。它通过获取完整的diff并识别攻击面来工作","ja":"Find Bugsは、コードのバグ、セキュリティ脆弱性、コード品質の問題を発見するAIエージェントです。完全なdiffを取得し、攻撃面を特定することで機能します","ko":"Find Bugs는 코드의 버그, 보안 취약점 및 코드 품질 문제를 찾는 AI 에이전트입니다. 전체 diff를 가져오고 공격 표면을 식별하여 작동","es":"Find-bugs es una herramienta que ayuda a los desarrolladores a encontrar errores, vulnerabilidades de seguridad y problemas de calidad de código en sus cambios de rama local","fr":"Find-bugs est un outil qui aide les développeurs à identifier les bogues, les vulnérabilités de sécurité et les problèmes de qualité de code dans leurs modifications de branche locale","de":"Find-bugs ist ein Tool, das Entwicklern hilft, Fehler, Sicherheitslücken und Code-Qualitätsprobleme in ihren lokalen Branch-Änderungen zu finden","pt":"O Find-Bugs é uma ferramenta de análise de código que ajuda a detectar erros, vulnerabilidades de segurança e problemas de qualidade de código em suas alterações de branch","ru":"ИИ Агент Find-Bugs - это инструмент анализа кода, который помогает обнаружить ошибки, уязвимости безопасности и проблемы качества кода в ваших изменениях ветки","ar":"العثور على الأخطاء هو أداة تحليل الكود التي تساعد في اكتشاف الأخطاء وأخطاء أمان وجودة الكود في تغييراتك"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"find-bugs","description":"Find bugs, security vulnerabilities, and code quality issues in local branch changes. Use when asked to review changes, find bugs, security review, or audit code on the current branch.","bodyPreview":"# Find Bugs\n\nReview changes on this branch for bugs, security vulnerabilities, and code quality issues.\n\n## Phase 1: Complete Input Gathering\n\n1. Get the FULL diff: `git diff $(gh repo view --json defaultBranchRef --jq ''.defaultBranchRef.name'')...HEAD`\n2. If output is truncated, read each changed file individually until you have seen every changed line\n3. List all files modified in this branch before proceeding\n\n## Phase 2: Attack Surface Mapping\n\nFor each changed file, identify and list:\n\n* All","body":"# Find Bugs\n\nReview changes on this branch for bugs, security vulnerabilities, and code quality issues.\n\n## Phase 1: Complete Input Gathering\n\n1. Get the FULL diff: `git diff $(gh repo view --json defaultBranchRef --jq ''.defaultBranchRef.name'')...HEAD`\n2. If output is truncated, read each changed file individually until you have seen every changed line\n3. List all files modified in this branch before proceeding\n\n## Phase 2: Attack Surface Mapping\n\nFor each changed file, identify and list:\n\n* All user inputs (request params, headers, body, URL components)\n* All database queries\n* All authentication/authorization checks\n* All session/state operations\n* All external calls\n* All cryptographic operations\n\n## Phase 3: Security Checklist (check EVERY item for EVERY file)\n\n* [ ] **Injection**: SQL, command, template, header injection\n* [ ] **XSS**: All outputs in templates properly escaped?\n* [ ] **Authentication**: Auth checks on all protected operations?\n* [ ] **Authorization/IDOR**: Access control verified, not just auth?\n* [ ] **CSRF**: State-changing operations protected?\n* [ ] **Race conditions**: TOCTOU in any read-then-write patterns?\n* [ ] **Session**: Fixation, expiration, secure flags?\n* [ ] **Cryptography**: Secure random, proper algorithms, no secrets in logs?\n* [ ] **Information disclosure**: Error messages, logs, timing attacks?\n* [ ] **DoS**: Unbounded operations, missing rate limits, resource exhaustion?\n* [ ] **Business logic**: Edge cases, state machine violations, numeric overflow?\n\n## Phase 4: Verification\n\nFor each potential issue:\n\n* Check if it''s already handled elsewhere in the changed code\n* Search for existing tests covering the scenario\n* Read surrounding context to verify the issue is real\n\n## Phase 5: Pre-Conclusion Audit\n\nBefore finalizing, you MUST:\n\n1. List every file you reviewed and confirm you read it completely\n2. List every checklist item and note whether you found issues or confirmed it''s clean\n3. List any areas you could NOT fully verify and why\n4. Only then provide your final findings\n\n## Output Format\n\n**Prioritize**: security vulnerabilities > bugs > code quality\n\n**Skip**: stylistic/formatting issues\n\nFor each issue:\n\n* **File:Line** - Brief description\n* **Severity**: Critical/High/Medium/Low\n* **Problem**: What''s wrong\n* **Evidence**: Why this is real (not already fixed, no existing test, etc.)\n* **Fix**: Concrete suggestion\n* **References**: OWASP, RFCs, or other standards if applicable\n\nIf you find nothing significant, say so - don''t invent issues.\n\nDo not make changes - just report findings. I''ll decide what to address.\n"},"category":"official","lastSynced":"2026-03-06T05:08:02.659Z","seo":{"title":{"en":"find-bugs: Code Review Setup Guide | AI Agent Skill","zh":"Find Bugs Setup Guide: 使用AI工具查找代码错误","ja":"Find Bugs セットアップガイド: AIエージェントを使用したコードレビュー","ko":"Find Bugs 설정 가이드: AI 에이전트를 사용한 버그 찾기","es":"Guía de configuración para encontrar errores con AI Agent","fr":"Guide de mise en œuvre de find-bugs pour les développeurs","de":"Einrichtungsleitfaden für find-bugs: Sicherheitsüberprüfu...","pt":"Guia de Configuração do Find-Bugs: Ferramenta de Análise ...","ru":"Настройка ИИ Агента Find-Bugs: Руководство по поиску ошибок","ar":"دليل إعداد العثور على الأخطاء: أداة تحليل الكود"},"description":{"en":"Discover how to identify bugs, security vulnerabilities, and code quality issues with find-bugs. Learn how to integrate it into your development workflow today!","zh":"使用Find Bugs AI工具查找代码错误、安全漏洞和代码质量问题。获取完整的diff并识别攻击面","ja":"Find Bugs AIエージェントを使用してコードのバグ、セキュリティ脆弱性、コード品質の問題を発見。完全なdiffを取得し、攻撃面を特定","ko":"Find Bugs AI 에이전트를 사용하여 코드의 버그, 보안 취약점 및 코드 품질 문제를 찾습니다. 전체 diff를 가져오고 공격 표면을 식별","es":"Descubre cómo encontrar errores, vulnerabilidades de seguridad y problemas de calidad de código con find-bugs. Mejora tu proceso de revisión de código","fr":"Découvrez comment utiliser find-bugs pour identifier les bogues, les vulnérabilités de sécurité et les problèmes de qualité de code. Améliorez votre processu...","de":"Erfahren Sie, wie Sie find-bugs verwenden, um Fehler, Sicherheitslücken und Code-Qualitätsprobleme zu finden. Verbessern Sie Ihren Code-Review-Prozess","pt":"Aprenda a configurar o Find-Bugs para detectar erros, vulnerabilidades de segurança e problemas de qualidade de código em suas alterações de branch","ru":"Узнайте, как настроить ИИ Агент Find-Bugs для поиска ошибок, уязвимостей безопасности и проблем качества кода в ваших изменениях ветки","ar":"تعلم كيفية إعداد العثور على الأخطاء لاكتشاف الأخطاء وأخطاء أمان وجودة الكود في تغييراتك"},"definition":{"en":"find-bugs is a code review tool that analyzes local branch changes to detect bugs, security vulnerabilities, and code quality issues using git diff and file analysis.","zh":"Find Bugs是一种AI工具，用于查找代码错误和安全漏洞","ja":"Find Bugsは、コードのバグとセキュリティ脆弱性を発見するAIエージェント","ko":"Find Bugs는 코드의 버그와 보안 취약점을 찾는 AI 에이전트","es":"Find-bugs es una herramienta de revisión de código que utiliza git diff para identificar errores y problemas de calidad de código","fr":"Find-bugs est un outil de révision de code qui utilise git diff pour identifier les bogues et les problèmes de qualité de code","de":"Find-bugs ist ein Code-Review-Tool, das git diff verwendet, um Fehler und Code-Qualitätsprobleme zu identifizieren","pt":"O Find-Bugs é uma ferramenta de análise de código que executa uma revisão de alterações de branch para detectar erros, vulnerabilidades de segurança e problemas de qualidade de código","ru":"ИИ Агент Find-Bugs - это инструмент анализа кода, который выполняет проверку изменений ветки для обнаружения ошибок, уязвимостей безопасности и проблем качества кода","ar":"العثور على الأخطاء هو أداة تحليل الكود التي تقوم بمراجعة تغييرات الفرع لاكتشاف الأخطاء وأخطاء أمان وجودة الكود"},"features":{"en":["Generates a full diff using `git diff $(gh repo view --json defaultBranchRef --jq ''.defaultBranchRef.name'')...HEAD`","Analyzes each changed file individually to identify all changed lines","Lists all files modified in the current branch before proceeding with the review","Performs attack surface mapping for each changed file","Identifies and lists all potential security vulnerabilities and code quality issues"],"zh":["获取完整的diff","识别攻击面","查找代码错误","安全漏洞检测","代码质量问题识别","使用Git diff命令"],"ja":["完全なdiffを取得","攻撃面を特定","コードのバグを発見","セキュリティ脆弱性を検出","コード品質の問題を識別","Git diffコマンドを使用"],"ko":["전체 diff를 가져오기","공격 표면을 식별","코드의 버그를 찾기","보안 취약점을 검출","코드 품질 문제를 식별","Git diff 명령어 사용"],"es":["Análisis de diff de git para identificar cambios","Detección de errores y vulnerabilidades de seguridad","Revisión de la calidad del código","Compatibilidad con la herramienta de línea de comandos git","Identificación de archivos modificados en la rama actual"],"fr":["Analyse de diff de git pour identifier les modifications","Détection des bogues et des vulnérabilités de sécurité","Révision de la qualité du code","Compatibilité avec l''outil de ligne de commande git","Identification des fichiers modifiés dans la branche actuelle"],"de":["Analyse von git-Diff, um Änderungen zu identifizieren","Erkennung von Fehlern und Sicherheitslücken","Überprüfung der Code-Qualität","Kompatibilität mit der git-Befehlszeilen-Tool","Identifizierung von geänderten Dateien im aktuellen Branch"],"pt":["Executa uma revisão de alterações de branch para detectar erros, vulnerabilidades de segurança e problemas de qualidade de código","Utiliza o comando `git diff` para obter a diferença completa entre as alterações","Lista todos os arquivos modificados na branch antes de proceder","Identifica e lista superfícies de ataque para cada arquivo alterado","Executa uma análise de código para detectar problemas de qualidade"],"ru":["Выполняет проверку изменений ветки для обнаружения ошибок, уязвимостей безопасности и проблем качества кода","Использует команду `git diff` для получения полной разницы между изменениями","Перечисляет все измененные файлы в ветке перед продолжением","Определяет и перечисляет поверхности атаки для каждого измененного файла","Выполняет анализ кода для обнаружения проблем качества"],"ar":["تقوم بمراجعة تغييرات الفرع لاكتشاف الأخطاء وأخطاء أمان وجودة الكود","تستخدم الأمر `git diff` للحصول على الفرق الكامل بين التغييرات","تستعرض جميع الملفات المعدلة في الفرع قبل المتابعة","تحدد وتستعرض أسطح الهجوم لكل ملف معدل","تقوم بتحليل الكود لاكتشاف مشاكل الجودة"]},"keywords":{"en":["how to use find-bugs","find-bugs alternative","find-bugs setup guide","what is find-bugs","find-bugs vs code review tools","find-bugs install","git diff tutorial","code quality issue detection","security vulnerability scanning"],"zh":["AI工具","代码错误","安全漏洞","代码质量","Find Bugs","Git diff","代码审查","AIエージェント","代码优化"],"ja":["AIエージェント","コードのバグ","セキュリティ脆弱性","コード品質","Find Bugs","Git diff","コードレビュー","AIツール","コード最適化"],"ko":["AI 에이전트","코드의 버그","보안 취약점","코드 품질","Find Bugs","Git diff","코드 검토","AI 도구","코드 최적화"],"es":["find-bugs","revisión de código","seguridad de código","calidad de código","git diff","herramientas de desarrollo","AI Agent","Agente de inteligencia artificial"],"fr":["find-bugs","révision de code","sécurité de code","qualité de code","git diff","outils de développement","AI Agent","Agent d''intelligence artificielle"],"de":["find-bugs","Code-Review","Sicherheitsüberprüfung","Code-Qualität","git-Diff","Entwicklungstools","AI Agent","Künstliche Intelligenz Agent"],"pt":["find-bugs","análise de código","detecção de erros","vulnerabilidades de segurança","problemas de qualidade de código","git diff","revisão de branch"],"ru":["find-bugs","анализ кода","обнаружение ошибок","уязвимости безопасности","проблемы качества кода","git diff","проверка ветки"],"ar":["find-bugs","تحليل الكود","اكتشاف الأخطاء","أخطاء أمان","مشاكل جودة الكود","git diff","مراجعة الفرع"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced bug detection and security vulnerability assessment capabilities in Git-based repositories.","zh":"适用于需要在 Git 基础仓库中进行高级 bug 检测和安全漏洞评估的代码审查代理。","ja":"Git ベースのリポジトリで高度なバグ検出とセキュリティ脆弱性評価機能が必要なコードレビュー代理に最適です。","ko":"Git 기반 저장소에서 고급 버그 감지 및 보안 취약성 평가 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan capacidades avanzadas de detección de errores y evaluación de vulnerabilidades de seguridad en repositorios basados en Git.","fr":"Parfait pour les agents de révision de code nécessitant des capacités de détection de bogues et d''évaluation des vulnérabilités de sécurité avancées dans les référentiels basés sur Git.","de":"Perfekt für Code-Review-Agenten, die erweiterte Fehlersuch- und Sicherheitsverwundbarkeitsbewertungsfunktionen in Git-basierten Repositorys benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de detecção avançada de bugs e avaliação de vulnerabilidades de segurança em repositórios baseados em Git.","ru":"Идеально подходит для агентов кода-ревью, которым необходимы возможности поиска багов и оценки уязвимостей безопасности в репозиториях на основе Git.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى كشف العيوب المتقدم وتقييم نقاط الضعف الأمنية في مستودعات قائم على Git."},"recommendation":{"en":"Empowers agents to identify bugs, security vulnerabilities, and code quality issues in local branch changes using Git diff and JSON parsing with `gh repo view` and `jq`, enhancing code review and audit processes.","zh":"赋予代理识别 Git diff 和 JSON 解析使用 `gh repo view` 和 `jq` 的本地分支更改中的 bug、安全漏洞和代码质量问题，提高代码审查和审计流程。","ja":"Git diff と JSON パーシングを使用して `gh repo view` と `jq` のローカルブランチの変更でバグ、セキュリティ脆弱性、コード品質の問題を特定することで、コードレビューと監査プロセスを強化します。","ko":"Git diff 및 JSON 파싱을 사용하여 `gh repo view` 및 `jq`의 로컬 브랜치 변경에서 버그, 보안 취약성 및 코드 품질 문제를 식별하여 코드 리뷰 및 감사 프로세스를 강화합니다.","es":"Habilita a los agentes a identificar errores, vulnerabilidades de seguridad y problemas de calidad del código en cambios de ramas locales utilizando Git diff y análisis de JSON con `gh repo view` y `jq`, mejorando los procesos de revisión y auditoría de código.","fr":"Permet aux agents d''identifier les bogues, les vulnérabilités de sécurité et les problèmes de qualité de code dans les modifications de branches locales en utilisant Git diff et l''analyse JSON avec `gh repo view` et `jq`, améliorant les processus de révision et d''audit de code.","de":"Ermöglicht es den Agenten, Fehler, Sicherheitsverwundbarkeiten und Codequalitätsprobleme in lokalen Branch-Änderungen zu identifizieren, indem Git diff und JSON-Parsing mit `gh repo view` und `jq` verwendet werden, wodurch die Code-Review- und Auditprozesse verbessert werden.","pt":"Habilita os agentes a identificar bugs, vulnerabilidades de segurança e problemas de qualidade de código em alterações de branch local usando Git diff e parsing JSON com `gh repo view` e `jq`, melhorando os processos de revisão e auditoria de código.","ru":"Наделяет агентов возможностью выявлять баги, уязвимости безопасности и проблемы качества кода в локальных изменениях веток с помощью Git diff и парсинга JSON с `gh repo view` и `jq`, улучшая процессы код-ревью и аудита.","ar":"يمنح الوكلاء القدرة على تحديد العيوب ونقاط الضعف الأمنية ومشاكل جودة الكود في التغييرات المحلية للفروع باستخدام Git diff و JSON parsing مع `gh repo view` و `jq` ، مما يحسن عمليات مراجعة الكود وعمليات التدقيق."},"useCases":{"en":["Debugging code changes for security vulnerabilities","Auditing code quality in Git repositories","Reviewing branch changes for bugs and issues"],"zh":["调试代码更改以检测安全漏洞","在 Git 仓库中审计代码质量","审查分支更改以查找 bug 和问题"],"ja":["セキュリティ脆弱性の検出のためにコード変更をデバッグする","Git リポジトリでコード品質を監査する","バグと問題を検出するためにブランチ変更をレビューする"],"ko":["보안 취약성을 탐지하기 위한 코드 변경 디버깅","Git 저장소에서 코드 품질을 감사하기","버그 및 문제를 찾기 위한 브랜치 변경 리뷰"],"es":["Depuración de cambios de código para vulnerabilidades de seguridad","Auditoría de la calidad del código en repositorios Git","Revisión de cambios de rama para errores y problemas"],"fr":["Débogage des modifications de code pour les vulnérabilités de sécurité","Audit de la qualité de code dans les référentiels Git","Révision des modifications de branche pour les bogues et les problèmes"],"de":["Fehlerbehebung von Codeänderungen für Sicherheitsverwundbarkeiten","Auditoría der Codequalität in Git-Repositorys","Überprüfung von Branch-Änderungen auf Fehler und Probleme"],"pt":["Depuração de alterações de código para vulnerabilidades de segurança","Auditoria da qualidade do código em repositórios Git","Revisão de alterações de branch para bugs e problemas"],"ru":["Отладка изменений кода для уязвимостей безопасности","Аудит качества кода в репозиториях Git","Просмотр изменений веток для багов и проблем"],"ar":["تصحيح أخطاء التغييرات في الكود من أجل نقاط الضعف الأمنية","تدقيق جودة الكود في مستودعات Git","مراجعة التغييرات في الفروع من أجل العيوب والمشاكل"]},"limitations":{"en":["Requires Git installation and configuration","Needs `gh` and `jq` commands available","Limited to reviewing changes in the current branch"],"zh":["需要 Git 安装和配置","需要 `gh` 和 `jq` 命令可用","仅限于审查当前分支的更改"],"ja":["Git のインストールと設定が必要","`gh` と `jq` コマンドが利用可能である必要がある","現在のブランチの変更のみをレビューする"],"ko":["Git 설치 및 구성이 필요합니다.","`gh` 및 `jq` 명령어가 사용 가능한必要があります.","현재 브랜치의 변경 사항만을 리뷰하는 데 제한됩니다."],"es":["Requiere instalación y configuración de Git","Necesita los comandos `gh` y `jq` disponibles","Limitado a la revisión de cambios en la rama actual"],"fr":["Nécessite l''installation et la configuration de Git","Nécessite les commandes `gh` et `jq` disponibles","Limité à la révision des modifications dans la branche actuelle"],"de":["Benötigt Git-Installation und -Konfiguration","Benötigt die Befehle `gh` und `jq` verfügbar","Begrenzt auf die Überprüfung von Änderungen im aktuellen Branch"],"pt":["Requer instalação e configuração do Git","Necessita dos comandos `gh` e `jq` disponíveis","Limitado à revisão de alterações no branch atual"],"ru":["Требует установки и настройки Git","Требует наличия команд `gh` и `jq`","Ограничен просмотром изменений в текущей ветке"],"ar":["يتطلب تثبيت وتكوين Git","يحتاج إلى توفر أوامر `gh` و `jq`","محدود بمراجعة التغييرات في الفرع الحالي"]},"version":4},"contentHash":"08664c3698f89116a4b04d12f699f95cff1aadb725da353b7f24f8ad73b02003","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":79}');
