INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/find-bugs', 'find-bugs', 'getsentry', 'skills', 'official', 'find-bugs getsentry skills official tag-production The find-bugs skill reviews local branch changes for bugs, security vulnerabilities, and code quality issues, benefiting developers in need of thorough code audits. Find Bugs是一种AI工具，用于查找代码错误、安全漏洞和代码质量问题。它通过获取完整的diff并识别攻击面来工作 Find Bugsは、コードのバグ、セキュリティ脆弱性、コード品質の問題を発見するAIエージェントです。完全なdiffを取得し、攻撃面を特定することで機能します Find Bugs는 코드의 버그, 보안 취약점 및 코드 품질 문제를 찾는 AI 에이전트입니다. 전체 diff를 가져오고 공격 표면을 식별하여 작동 Find-bugs es una herramienta que ayuda a los desarrolladores a encontrar errores, vulnerabilidades de seguridad y problemas de calidad de código en sus cambios de rama local Find-bugs est un outil qui aide les développeurs à identifier les bogues, les vulnérabilités de sécurité et les problèmes de qualité de code dans leurs modifications de branche locale Find-bugs ist ein Tool, das Entwicklern hilft, Fehler, Sicherheitslücken und Code-Qualitätsprobleme in ihren lokalen Branch-Änderungen zu finden O Find-Bugs é uma ferramenta de análise de código que ajuda a detectar erros, vulnerabilidades de segurança e problemas de qualidade de código em suas alterações de branch ИИ Агент Find-Bugs - это инструмент анализа кода, который помогает обнаружить ошибки, уязвимости безопасности и проблемы качества кода в ваших изменениях ветки العثور على الأخطاء هو أداة تحليل الكود التي تساعد في اكتشاف الأخطاء وأخطاء أمان وجودة الكود في تغييراتك how to use find-bugs find-bugs alternative find-bugs setup guide what is find-bugs find-bugs vs code review tools find-bugs install git diff tutorial code quality issue detection security vulnerability scanning AI工具 代码错误 安全漏洞 代码质量 Find Bugs Git diff 代码审查 AIエージェント 代码优化 Generates a full diff using `git diff $(gh repo view --json defaultBranchRef --jq ''.defaultBranchRef.name'')...HEAD` Analyzes each changed file individually to identify all changed lines Lists all files modified in the current branch before proceeding with the review Performs attack surface mapping for each changed file Identifies and lists all potential security vulnerabilities and code quality issues find-bugs is a code review tool that analyzes local branch changes to detect bugs, security vulnerabilities, and code quality issues using git diff and file analysis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('supabase/agent-skills/supabase-postgres-best-practices', 'official', 'supabase', 'agent-skills', 'supabase/agent-skills', 'supabase-postgres-best-practices', 1507, 86, 79, '2026-03-06T05:27:03Z', '2026-03-06T05:50:40.825Z', '8e5a86aa92990a706512a6454e3a6a6345a950b454e75a11d048210d0a2ca830', '{"id":"supabase/agent-skills/supabase-postgres-best-practices","name":"supabase-postgres-best-practices","description":{"en":"This AI Agent skill provides a comprehensive set of Postgres performance optimization rules from Supabase. It assists developers in writing efficient SQL queries, designing scalable schemas, and configuring database settings like connection pooling.","zh":"Supabase Postgres 最佳实践提供了全面的性能优化指南，包含 8 个类别的规则，用于自动化查询优化和模式设计","ja":"Supabase Postgres 最適化ガイドは、パフォーマンスを最適化するための包括的なガイドを提供し、8 つのカテゴリのルールを含みます","ko":"Supabase Postgres 최적화 설정 가이드는 성능 최적화를 위한 포괄적인 가이드를 제공하며 8개의 카테고리의 규칙을 포함합니다","es":"La guía de optimización de Supabase Postgres ofrece reglas para mejorar el rendimiento de tus bases de datos. Aprende a escribir consultas SQL eficientes y a diseñar esquemas óptimos.","fr":"Le guide d''optimisation de Supabase Postgres propose des règles pour améliorer les performances de vos bases de données. Apprenez à écrire des requêtes SQL efficaces et à concevoir des schémas optimaux.","de":"Der Leitfaden für die Optimierung von Supabase Postgres bietet Regeln für die Verbesserung der Leistung Ihrer Datenbanken. Lernen Sie, effiziente SQL-Abfragen zu schreiben und optimale Schemata zu entwerfen.","pt":"As melhores práticas de Supabase Postgres para otimização de desempenho. Contém regras em 8 categorias para guiar a otimização automática de consultas e design de esquemas.","ru":"Лучшие практики Supabase Postgres для оптимизации производительности. Содержит правила в 8 категориях для автоматизированной оптимизации запросов и проектирования схем.","ar":"أفضل الممارسات ل Supabase Postgres لتحسين الأداء. تحتوي على قواعد في 8 فئات لتوجيه تحسين الاستعلامات التلقائي وتصميم المخططات."},"owner":"supabase","repo":"agent-skills","repoPath":"supabase/agent-skills","stars":1507,"forks":86,"updatedAt":"2026-03-06T05:27:03Z","topics":["ai","ai-agents","skills","supabase"],"skillMd":{"name":"supabase-postgres-best-practices","description":"Postgres performance optimization and best practices from Supabase. Use this skill when writing, reviewing, or optimizing Postgres queries, schema designs, or database configurations.","version":"1.1.0","bodyPreview":"# Supabase Postgres Best Practices\n\nComprehensive performance optimization guide for Postgres, maintained by Supabase. Contains rules across 8 categories, prioritized by impact to guide automated query optimization and schema design.\n\n## When to Apply\n\nReference these guidelines when:\n- Writing SQL queries or designing schemas\n- Implementing indexes or query optimization\n- Reviewing database performance issues\n- Configuring connection pooling or scaling\n- Optimizing for Postgres-specific feature","body":"# Supabase Postgres Best Practices\n\nComprehensive performance optimization guide for Postgres, maintained by Supabase. Contains rules across 8 categories, prioritized by impact to guide automated query optimization and schema design.\n\n## When to Apply\n\nReference these guidelines when:\n- Writing SQL queries or designing schemas\n- Implementing indexes or query optimization\n- Reviewing database performance issues\n- Configuring connection pooling or scaling\n- Optimizing for Postgres-specific features\n- Working with Row-Level Security (RLS)\n\n## Rule Categories by Priority\n\n| Priority | Category | Impact | Prefix |\n|----------|----------|--------|--------|\n| 1 | Query Performance | CRITICAL | `query-` |\n| 2 | Connection Management | CRITICAL | `conn-` |\n| 3 | Security & RLS | CRITICAL | `security-` |\n| 4 | Schema Design | HIGH | `schema-` |\n| 5 | Concurrency & Locking | MEDIUM-HIGH | `lock-` |\n| 6 | Data Access Patterns | MEDIUM | `data-` |\n| 7 | Monitoring & Diagnostics | LOW-MEDIUM | `monitor-` |\n| 8 | Advanced Features | LOW | `advanced-` |\n\n## How to Use\n\nRead individual rule files for detailed explanations and SQL examples:\n\n```\nreferences/query-missing-indexes.md\nreferences/schema-partial-indexes.md\nreferences/_sections.md\n```\n\nEach rule file contains:\n- Brief explanation of why it matters\n- Incorrect SQL example with explanation\n- Correct SQL example with explanation\n- Optional EXPLAIN output or metrics\n- Additional context and references\n- Supabase-specific notes (when applicable)\n\n## References\n\n- https://www.postgresql.org/docs/current/\n- https://supabase.com/docs\n- https://wiki.postgresql.org/wiki/Performance_Optimization\n- https://supabase.com/docs/guides/database/overview\n- https://supabase.com/docs/guides/auth/row-level-security\n"},"category":"official","lastSynced":"2026-03-06T05:50:40.825Z","seo":{"title":{"en":"Supabase Postgres Best Practices: Performance Optimizatio...","zh":"Supabase Postgres 优化指南","ja":"Supabase Postgres 最適化ガイド","ko":"Supabase Postgres 최적화 설정 가이드","es":"Mejores Prácticas de Supabase Postgres: Guía de Optimización","fr":"Bonnes Pratiques Supabase Postgres: Guide d''Optimisation","de":"Supabase Postgres Best Practices: Leitfaden für Optimierung","pt":"Melhores Práticas de Supabase Postgres: Guia de Otimização","ru":"Лучшие практики Supabase Postgres: Руководство по оптимиз...","ar":"أفضل الممارسات ل Supabase Postgres: دليل لتحسين الأداء"},"description":{"en":"Leverage Supabase''s expert Postgres rules for automated query & schema optimization. This AI Agent skill provides prioritized guidance across 8 performance c...","zh":"使用 Supabase Postgres 最佳实践优化性能，提高数据库效率","ja":"Supabase Postgres のパフォーマンスを最適化し、データベースの効率を向上させる","ko":"Supabase Postgres 성능 최적화를 위해 최고의 사례를 사용하여 데이터베이스 효율성을 향상시키세요","es":"Aprende a optimizar el rendimiento de Postgres con las mejores prácticas de Supabase. Mejora tus consultas SQL y diseños de esquema.","fr":"Apprenez à optimiser les performances de Postgres avec les meilleures pratiques de Supabase. Améliorez vos requêtes SQL et conceptions de schéma.","de":"Lernen Sie, die Leistung von Postgres mit den besten Praktiken von Supabase zu optimieren. Verbessern Sie Ihre SQL-Abfragen und Schemadesigns.","pt":"Aprenda a otimizar o desempenho do Postgres com as melhores práticas da Supabase. Descubra dicas para consultas SQL, design de esquemas e configurações de ba...","ru":"Узнайте, как оптимизировать производительность Postgres с помощью лучших практик Supabase. Обнаружите советы для запросов SQL, проектирования схем и настроек...","ar":"تعرف على كيفية تحسين أداء Postgres باستخدام أفضل الممارسات من Supabase. اكتشف نصائح لاستعلامات SQL وتصميم مخططات وتكوين قواعد البيانات."},"definition":{"en":"supabase-postgres-best-practices is an AI Agent skill containing Supabase''s curated guidelines for PostgreSQL database optimization. It provides prioritized rules across 8 categories to automate query review, index implementation, and schema design for improved performance.","zh":"Supabase Postgres 最佳实践是由 Supabase 提供的 Postgres 性能优化和最佳实践指南","ja":"Supabase Postgres 最適化ガイドは、Supabase によって提供される Postgres のパフォーマンス最適化とベストプラクティスのガイドです","ko":"Supabase Postgres 최적화 설정 가이드는 Supabase에서 제공하는 Postgres 성능 최적화 및 최적의 사례 가이드입니다","es":"Las mejores prácticas de Supabase Postgres son un conjunto de reglas para optimizar el rendimiento de bases de datos Postgres.","fr":"Les bonnes pratiques de Supabase Postgres sont un ensemble de règles pour optimiser les performances des bases de données Postgres.","de":"Die besten Praktiken von Supabase Postgres sind ein Satz von Regeln für die Optimierung der Leistung von Postgres-Datenbanken.","pt":"As melhores práticas de Supabase Postgres são um conjunto de regras para otimizar o desempenho do Postgres.","ru":"Лучшие практики Supabase Postgres - это набор правил для оптимизации производительности Postgres.","ar":"أفضل الممارسات ل Supabase Postgres هي مجموعة من القواعد لتحسين أداء Postgres."},"features":{"en":["Provides prioritized Postgres optimization rules across 8 performance categories","Guides automated SQL query writing and review processes","Assists with database index implementation and strategy","Informs scalable Postgres schema design decisions","Offers configuration guidance for connection pooling","Helps troubleshoot and resolve database performance issues"],"zh":["包含 8 个类别的规则，用于自动化查询优化和模式设计","提供索引和查询优化的指导","支持数据库性能问题的审查","包含连接池和扩展配置的优化","针对 Postgres 特有的功能进行优化"],"ja":["8 つのカテゴリのルールを含み、自動化されたクエリ最適化とスキーマ設計をサポート","インデックスとクエリ最適化のガイドを提供","データベースのパフォーマンス問題のレビューをサポート","接続プールとスケーリングの設定の最適化を含む","Postgres 特有の機能に対する最適化"],"ko":["8개의 카테고리의 규칙을 포함하여 자동화된 쿼리 최적화 및 스키마 설계를 지원","인덱스 및 쿼리 최적화를 위한 가이드를 제공","데이터베이스 성능 문제의 검토를 지원","연결 풀 및 확장 구성의 최적화를 포함","Postgres 특有的 기능에 대한 최적화"],"es":["Optimización de consultas SQL","Diseño de esquemas eficientes","Implementación de índices","Optimización de la configuración de la base de datos","Mejora del rendimiento de Postgres","Guía para la configuración de conexión y escalado"],"fr":["Optimisation des requêtes SQL","Conception de schémas efficaces","Mise en œuvre d''index","Optimisation de la configuration de la base de données","Amélioration des performances de Postgres","Guide pour la configuration de connexion et mise à l''échelle"],"de":["Optimierung von SQL-Abfragen","Entwurf effizienter Schemata","Implementierung von Indizes","Optimierung der Datenbankkonfiguration","Verbesserung der Postgres-Leistung","Leitfaden für die Konfiguration von Verbindungen und Skalierung"],"pt":["Otimização de consultas SQL","Design de esquemas eficazes","Configurações de banco de dados personalizadas","Implementação de índices e otimização de consultas","Revisão de problemas de desempenho do banco de dados","Configuração de pooling de conexões e escalabilidade"],"ru":["Оптимизация запросо