INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('supabase/agent-skills/supabase-postgres-best-practices', 'supabase-postgres-best-practices', 'supabase', 'agent-skills', 'official', 'supabase-postgres-best-practices supabase agent-skills official ai ai-agents skills supabase This AI Agent skill provides a comprehensive set of Postgres performance optimization rules from Supabase. It assists developers in writing efficient SQL queries, designing scalable schemas, and configuring database settings like connection pooling. Supabase Postgres 最佳实践提供了全面的性能优化指南，包含 8 个类别的规则，用于自动化查询优化和模式设计 Supabase Postgres 最適化ガイドは、パフォーマンスを最適化するための包括的なガイドを提供し、8 つのカテゴリのルールを含みます Supabase Postgres 최적화 설정 가이드는 성능 최적화를 위한 포괄적인 가이드를 제공하며 8개의 카테고리의 규칙을 포함합니다 La guía de optimización de Supabase Postgres ofrece reglas para mejorar el rendimiento de tus bases de datos. Aprende a escribir consultas SQL eficientes y a diseñar esquemas óptimos. Le guide d''optimisation de Supabase Postgres propose des règles pour améliorer les performances de vos bases de données. Apprenez à écrire des requêtes SQL efficaces et à concevoir des schémas optimaux. Der Leitfaden für die Optimierung von Supabase Postgres bietet Regeln für die Verbesserung der Leistung Ihrer Datenbanken. Lernen Sie, effiziente SQL-Abfragen zu schreiben und optimale Schemata zu entwerfen. As melhores práticas de Supabase Postgres para otimização de desempenho. Contém regras em 8 categorias para guiar a otimização automática de consultas e design de esquemas. Лучшие практики Supabase Postgres для оптимизации производительности. Содержит правила в 8 категориях для автоматизированной оптимизации запросов и проектирования схем. أفضل الممارسات ل Supabase Postgres لتحسين الأداء. تحتوي على قواعد في 8 فئات لتوجيه تحسين الاستعلامات التلقائي وتصميم المخططات. supabase postgres best practices how to use supabase-postgres-best-practices what is supabase-postgres-best-practices supabase-postgres-best-practices alternative supabase-postgres-best-practices vs postgres optimizer supabase-postgres-best-practices install supabase-postgres-best-practices setup guide postgres query optimization ai agent supabase database performance rules Supabase Postgres 优化 Postgres 性能优化 数据库优化 索引优化 查询优化 模式设计 连接池 扩展配置 Provides prioritized Postgres optimization rules across 8 performance categories Guides automated SQL query writing and review processes Assists with database index implementation and strategy Informs scalable Postgres schema design decisions Offers configuration guidance for connection pooling Helps troubleshoot and resolve database performance issues supabase-postgres-best-practices is an AI Agent skill containing Supabase''s curated guidelines for PostgreSQL database optimization. It provides prioritized rules across 8 categories to automate query review, index implementation, and schema design for improved performance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/skill-writer', 'official', 'getsentry', 'skills', 'getsentry/skills', 'skill-writer', 360, 11, 79, '2026-03-06T00:20:36Z', '2026-03-06T05:17:23.190Z', '66ea94bed313eaa6644d4ebcbff7c7e2a90d2b9a7c183e807454290c47a6a35f', '{"id":"getsentry/skills/skill-writer","name":"skill-writer","description":{"en":"The Skill-Writer skill creates, synthesizes, and iteratively improves agent skills following the Agent Skills specification, benefiting AI agent developers. It handles source capture, depth gates, authoring, registration, and validation.","zh":"Skill Writer 是用于创建和改进 AI エージェント技能的工具，提供源捕获、深度门控、编写、注册和验证等功能","ja":"Skill Writer は、AIエージェントのスキルを作成、改善するためのツールで、ソースの収集、深度ゲート、著作、登録、検証などの機能を提供","ko":"Skill Writer는 AI 에이전트 스킬을 생성하고 개선하는 도구로, 소스 캡처, 심도 게이트, 저작, 등록 및 검증 등의 기능을 제공","es":"El skill-writer es una herramienta para crear y mejorar habilidades de Agentes de IA, siguiendo la especificación de habilidades de Agentes. Maximiza la cobertura de entrada de alto valor antes de la autoría.","fr":"Le skill-writer est un outil pour créer et améliorer les compétences des Outils d''IA, en suivant la spécification des compétences des Agents. Maximise la couverture des entrées de haute valeur avant l''authoring.","de":"Der skill-writer ist ein Tool zum Erstellen und Verbessern von Fähigkeiten von KI-Agents, unter Einhaltung der Spezifikation der Fähigkeiten von Agents. Maximiert die Abdeckung von hochwertigen Eingaben vor der Autorisierung.","pt":"O Skill-Writer é uma ferramenta para criar e melhorar habilidades de agentes de IA, garantindo uma cobertura de entrada de alto valor","ru":"Skill-Writer — это инструмент для создания и улучшения навыков ИИ Агентов, обеспечивающий максимальную покрытие входных данных высокого качества","ar":"Skill-Writer هو أداة لإنشاء وتحسين مهارات وكلاء الذكاء الاصطناعي، مما يضمن تغطية الإدخال عالية القيمة"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"skill-writer","description":"Create, synthesize, and iteratively improve agent skills following the Agent Skills specification. Use when asked to create a skill, write a skill, synthesize sources into a skill, improve a skill from positive/negative examples, update a skill, or maintain skill docs and registration. Handles source capture, depth gates, authoring, registration, and validation.","bodyPreview":"# Skill Writer\n\nUse this as the single canonical workflow for skill creation and improvement.\nPrimary success condition: maximize high-value input coverage before authoring so the resulting skill has minimal blind spots.\n\nLoad only the path(s) required for the task:\n\n| Task | Read |\n|------|------|\n| Set skill class and required dimensions | `references/mode-selection.md` |\n| Apply writing constraints for depth vs concision | `references/design-principles.md` |\n| Select structure pattern for thi","body":"# Skill Writer\n\nUse this as the single canonical workflow for skill creation and improvement.\nPrimary success condition: maximize high-value input coverage before authoring so the resulting skill has minimal blind spots.\n\nLoad only the path(s) required for the task:\n\n| Task | Read |\n|------|------|\n| Set skill class and required dimensions | `references/mode-selection.md` |\n| Apply writing constraints for depth vs concision | `references/design-principles.md` |\n| Select structure pattern for this skill | `references/skill-patterns.md` |\n| Select workflow orchestration pattern for process-heavy skills | `references/workflow-patterns.md` |\n| Select output format pattern for deterministic quality | `references/output-patterns.md` |\n| Choose workflow path and required outputs | `references/mode-selection.md` |\n| Load representative synthesis examples by skill type | `references/examples/*.md` |\n| Synthesize external/local sources with depth gates | `references/synthesis-path.md` |\n| Author or update SKILL.md and supporting files | `references/authoring-path.md` |\n| Optimize skill description and trigger precision | `references/description-optimization.md` |\n| Iterate using positive/negative/fix examples | `references/iteration-path.md` |\n| Evaluate behavior and compare baseline vs with-skill (opt-in quantitative) | `references/evaluation-path.md` |\n| Register and validate skill changes | `references/registration-validation.md` |\n\n## Step 1: Resolve target and path\n\n1. Resolve target skill path and intended operation (`create`, `update`, `synthesize`, `iterate`).\n2. Read `references/mode-selection.md` and select the required path(s).\n3. Classify the skill (`workflow-process`, `integration-documentation`, `security-review`, `skill-authoring`, `generic`).\n4. Ask one direct question if class or depth requirements are ambiguous; otherwise state explicit assumptions.\n\n## Step 2: Run synthesis when needed\n\nRead `references/synthesis-path.md`.\n\n1. Collect and score relevant sources with provenance.\n2. Apply trust and safety rules when ingesting external content.\n3. Produce source-backed decisions and coverage/gap status.\n4. Load one or more profiles from `references/examples/*.md` when the skill is hybrid.\n5. Enforce baseline source pack for skill-authoring workflows.\n6. Enforce depth gates before moving to authoring.\n\n## Step 3: Run iteration first when improving from outcomes/examples\n\nRead `references/iteration-path.md` first when selected path includes `iteration` (for example operation `iterate`).\n\n1. Capture and anonymize examples with provenance.\n2. Re-evaluate skill behavior against working and holdout slices.\n3. Propose improvements from positive/negative/fix evidence.\n4. Carry concrete behavior deltas into authoring.\n\nSkip this step when selected path does not include `iteration`.\n\n## Step 4: Author or update skill artifacts\n\nRead `references/authoring-path.md`.\n\n1. Write or update `SKILL.md` in imperative voice with trigger-rich description.\n2. Create focused reference files and scripts only when justified.\n3. Follow `references/skill-patterns.md`, `references/workflow-patterns.md`, and\n   `references/output-patterns.md` for structure and output determinism.\n4. For authoring/generator skills, include transformed examples in references:\n   - happy-path\n   - secure/robust variant\n   - anti-pattern + corrected version\n\n## Step 5: Optimize description quality\n\nRead `references/description-optimization.md`.\n\n1. Validate should-trigger and should-not-trigger query sets.\n2. Reduce false positives and false negatives with targeted description edits.\n3. Keep trigger language generic across Codex and Claude.\n\n## Step 6: Evaluate outcomes\n\nRead `references/evaluation-path.md`.\n\n1. Run a lightweight qualitative check by default (recommended).\n2. For integration/documentation and skill-authoring skills, include the concise depth rubric from `references/evaluation-path.md`.\n3. Run deeper eval playbook and quantitative baseline-vs-with-skill only when requested or risk warrants it.\n4. Record outcomes and unresolved risks.\n\n## Step 7: Register and validate\n\nRead `references/registration-validation.md`.\n\n1. Apply repository registration steps.\n2. Run quick validation with strict depth gates.\n3. Reject shallow outputs that fail depth gates or required artifact checks.\n\n## Output format\n\nReturn:\n\n1. `Summary`\n2. `Changes Made`\n3. `Validation Results`\n4. `Open Gaps`\n"},"category":"official","lastSynced":"2026-03-06T05:17:23.190Z","seo":{"title":{"en":"Skill-Writer: AI Agent Skill Creation and Improvement Gui...","zh":"AIエージェント技能编写指南：Skill Writer Setup Guide","ja":"AIエージェントのスキル作成：Skill Writer ベストプラクティス","ko":"AI 에이전트 스킬 작성 가이드：Skill Writer 설정 및 최적화","es":"Guía de configuración de skill-writer para Agentes de IA","fr":"Guide de mise en place de skill-writer pour les Outils d''IA","de":"Einrichtungsleitfaden für skill-writer in KI-Agents","pt":"Guia de Configuração do Skill-Writer para Ferramentas de IA","ru":"Настройка ИИ Агентов: Руководство по Skill-Writer","ar":"دليل إعداد Skill-Writer للوكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to maximize high-value input coverage with Skill-Writer. Learn to create, synthesize, and improve agent skills with our expert guide and get sta...","zh":"了解 Skill Writer 的功能和特点，掌握 AI エージェント技能的创建、改进和维护","ja":"AIエージェントのスキルを作成、改善、維持するための Skill Writer の機能と特徴を紹介","ko":"AI 에이전트 스킬을 생성하고 개선하는 Skill Writer의 기능과 특징을 알아보세요","es":"Aprende a crear y mejorar habilidades de Agentes de IA con skill-writer, maximizando la cobertura de entrada de alto valor","fr":"Découvrez comment créer et améliorer les compétences des Outils d''IA avec skill-writer, en maximisant la couverture des entrées de haute valeur","de":"Erfahren Sie, wie Sie Fähigkeiten von KI-Agents mit skill-writer erstellen und verbessern, um die Abdeckung von hochwertigen Eingaben zu maximieren","pt":"Aprenda a criar e melhorar habilidades de agentes de IA com o Skill-Writer, maximizando a cobertura de entrada de alto valor","ru":"Узнайте, как создавать и улучшать навыки ИИ Агентов с помощью Skill-Writer, максимизируя покрытие входных данных высокого качества","ar":"تعلم كيفية إنشاء وتحسين مهارات وكلاء الذكاء الاصطناعي باستخدام Skill-Writer، وتحقيق أقصى استفادة من تغطية الإدخال عالية القيمة"},"definition":{"en":"Skill-writer is a canonical workflow for skill creation and improvement, ensuring minimal blind spots in resulting skills.","zh":"Skill Writer 是一种 AI エージェント技能创建和改进工具","ja":"Skill Writer は、AIエージェントのスキルを作成、改善するためのツール","ko":"Skill Writer는 AI 에이전트 스킬을 생성하고 개선하는 도구","es":"El skill-writer es una herramienta de creación y mejora de habilidades de Agentes de IA que sigue la especificación de habilidades de Agentes","fr":"Le skill-writer est un outil de création et d''amélioration des compétences des Outils d''IA qui suit la spécification des compétences des Agents","de":"Der skill-writer ist ein Tool zur Erstellung und Verbesserung von Fähigkeiten von KI-Agents, das die Spezifikation der Fähigkeiten von Agents einhält","pt":"O Skill-Writer é uma ferramenta de criação e melhoria de habilidades de agentes de IA","ru":"Skill-Writer — это инструмент для создания и улучшения навыков ИИ Агентов","ar":"Skill-Writer هو أداة لإنشاء وتحسين مهارات وكلاء الذكاء الاصطناعي"},"features":{"en":["Loads required paths for tasks, such as setting skill class and dimensions via references/mode-selection.md","Applies writing constraints for depth vs concision using references/design-principles.md","Selects structure patterns for skills","Handles source capture and depth gates","Performs authoring, registration, and validation of skills"],"zh":["源捕获和深度门控功能","编写和注册 AI エージェント技能","验证和改进技能","支持多种任务和模式","集成设计原则和模式选择"],"ja":["ソースの収集と深度ゲート機能","AIエージェントのスキルを作成、登録","スキルの検証と改善","多種多様なタスクとパターンをサポート","設計原則とパターン選択の統合"],"ko":["소스 캡처와 심도 게이트 기능","AI 에이전트 스킬을 생성하고 등록","스킬의 검증과 개선","다양한 작업과 패턴 지원","디자인 원칙과 패턴 선택 통합"],"es":["Crea y mejora habilidades de Agentes de IA","Sigue la especificación de habilidades de Agentes","Maximiza la cobertura de entrada de alto valor antes de la autoría","Soporta la captura de fuentes, puertas de profundidad y autorización","Permite la selección de patrones de estructura para la creación de habilidades"],"fr":["Crée et améliore les compétences des Outils d''IA","Suit la spécification des compétences des Agents","Maximise la couverture des entrées de haute valeur avant l''authoring","Prend en charge la capture de sources, les portes de profondeur et l''authorisation","Permet la sélection de modèles de structure pour la création de compétences"],"de":["Erstellt und verbessert Fähigkeiten von KI-Agents","Einhaltet die Spezifikation der Fähigkeiten von Agents","Maximiert die Abdeckung von hochwertigen Eingaben vor der Autorisierung","Unterstützt die Quellenerfassung, Tiefengatter und Autorisierung","Ermöglicht die Auswahl von Strukturmustern für die Erstellung von Fähigkeiten"],"pt":["Criação e melhoria de habilidades de agentes de IA","Maximização da cobertura de entrada de alto valor","Suporte à captura de fontes e portas de profundidade","Authoring e registro de habilidades","Validação de habilidades"],"ru":["Создание и улучшение навыков ИИ Агентов","Максимизация покрытия входных данных высокого качества","Поддержка захвата источников и глубинных шлюзов","Авторинг и регистрация навыков","Валидация навыков"],"ar":["إنشاء وتحسين مهارات وكلاء الذكاء الاصطناعي","تحقيق أقصى استفادة من تغطية الإدخال عالية القيمة","دعم.capture من المصادر وبوابات العمق","كتابة وتسجيل المهارات","التحقق من صحة المهارات"]},"keywords":{"en":["how to use skill-writer","what is skill-writer","skill-writer alternative","skill-writer setup guide","skill-writer install","agent skills specification","ai agent skill creation","skill improvement workflow","maximizing high-value input coverage"],"zh":["AI エージェント技能创建","Skill Writer","AI工具","技能改进","源捕获","深度门控","编写和注册","验证和改进"],"ja":["AIエージェントのスキルを作成","Skill Writer","AIエージェント","スキルの改善","ソースの収集","深度ゲート","著作と登録","検証と改善"],"ko":["AI 에이전트 스킬 생성","Skill Writer","AI 에이전트","스킬 개선","소스 캡처","심도 게이트","저작과 등록","검증과 개선"],"es":["skill-writer","Agentes de IA","creación de habilidades","mejora de habilidades","especificación de habilidades de Agentes","captura de fuentes","puertas de profundidad","autorización","selección de patrones de estructura"],"fr":["skill-writer","Outils d''IA","création de compétences","amélioration de compétences","spécification des compétences des Agents","capture de sources","portes de profondeur","authorisation","sélection de modèles de structure"],"de":["skill-writer","KI-Agents","Erstellung von Fähigkeiten","Verbesserung von Fähigkeiten","Spezifikation der Fähigkeiten von Agents","Quellenerfassung","Tiefengatter","Autorisierung","Auswahl von Strukturmustern"],"pt":["Skill-Writer","Ferramentas de IA","Agente de IA","Criação de habilidades","Melhoria de habilidades","Cobertura de entrada de alto valor","Captura de fontes","Portas de profundidade","Authoring de habilidades"],"ru":["Skill-Writer","ИИ Агенты","Создание навыков","Улучшение навыков","Максимизация покрытия входных данных высокого качества","Захват источников","Глубинные шлюзы","Авторинг навыков"],"ar":["Skill-Writer","وكلاء الذكاء الاصطناعي","إنشاء مهارات","تحسين مهارات","تحقيق أقصى استفادة من تغطية الإدخال عالية القيمة","دعم.capture من المصادر","بوابات العمق","كتابة وتسجيل المهارات"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced skill creation and improvement capabilities, such as AutoGPT and LangChain.","zh":"适合需要高级技能创建和改进能力的AI代理，例如AutoGPT和LangChain。","ja":"AutoGPTやLangChainのような、高度なスキル作成および改善機能を必要とするAIエージェントに適しています。","ko":"AutoGPT와 LangChain 같은 고급 스킬 생성 및 개선 기능이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan capacidades avanzadas de creación y mejora de habilidades, como AutoGPT y LangChain.","fr":"Parfait pour les agents IA nécessitant des capacités avancées de création et d''amélioration de compétences, tels que AutoGPT et LangChain.","de":"Perfekt für KI-Agents, die erweiterte Fähigkeitserschaffungs- und Verbesserungsfähigkeiten benötigen, wie z.B. AutoGPT und LangChain.","pt":"Perfeito para Agentes de IA que necessitam de capacidades avançadas de criação e melhoria de habilidades, como AutoGPT e LangChain.","ru":"Идеально подходит для агентов ИИ, которым необходимы расширенные возможности создания и улучшения навыков, такие как AutoGPT и LangChain.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى قدرات متقدمة لإنشاء وتحسين المهارات، مثل AutoGPT و LangChain."},"recommendation":{"en":"Empowers agents to create, synthesize, and iteratively improve skills following the Agent Skills specification, utilizing source capture, depth gates, authoring, registration, and validation, with a focus on maximizing high-value input coverage and minimizing blind spots, leveraging design principles and mode selection.","zh":"赋予代理创建、综合和迭代改进技能的能力，遵循Agent Skills规范，利用源捕获、深度门、创作、注册和验证，注重最大化高价值输入覆盖率和最小化盲点，利用设计原则和模式选择。","ja":"エージェントは、エージェントスキル仕様に従ってスキルを作成、統合、反復改善する能力を持ち、ソースキャプチャ、デプスゲート、オーサリング、登録、バリデーションを利用し、高価値入力のカバー率を最大化し、盲点を最小限に抑えることを目指し、設計原則とモード選択を利用します。","ko":"에이전트는 에이전트 스킬 사양을 따라 스킬을 생성하고 통합하여 반복적으로 개선하는 능력을 가지고 있으며, 소스 캡처, 디프스 게이트, 저작, 등록, 검증을 활용하여 고가치 입력 범위를 최대화하고 맹점을 최소화하는 것을 목표로 하며, 설계 원칙과 모드 선택을 활용합니다.","es":"Habilita a los agentes a crear, sintetizar y mejorar iterativamente las habilidades siguiendo la especificación de habilidades del agente, utilizando la captura de fuentes, puertas de profundidad, autoría, registro y validación, con un enfoque en maximizar la cobertura de entrada de alto valor y minimizar los puntos ciegos, aprovechando los principios de diseño y la selección de modo.","fr":"Permet aux agents de créer, de synthétiser et d''améliorer de manière itérative les compétences en suivant la spécification des compétences de l''agent, en utilisant la capture de sources, les portes de profondeur, l''authoring, l''enregistrement et la validation, avec un focus sur la maximisation de la couverture des entrées à haute valeur et la minimisation des angles morts, en exploitant les principes de conception et la sélection de mode.","de":"Ermöglicht es Agents, Fähigkeiten zu erstellen, zu synthetisieren und iterativ zu verbessern, indem sie der Agent-Fähigkeiten-Spezifikation folgen, Quellenerfassung, Tiefen-Schranken, Autorenschaft, Registrierung und Validierung nutzen, mit dem Fokus darauf, die Abdeckung von hochwertigen Eingaben zu maximieren und blinden Flecken zu minimieren, indem sie die Entwurfsprinzipien und Modusaufwahl nutzen.","pt":"Habilita os agentes a criar, sintetizar e melhorar iterativamente as habilidades seguindo a especificação de Habilidades do Agente, utilizando captura de fontes, portas de profundidade, autoria, registro e validação, com foco em maximizar a cobertura de entrada de alto valor e minimizar pontos cegos, aproveitando princípios de design e seleção de modo.","ru":"Наделяет агентов возможностью создавать, синтезировать и итеративно улучшать навыки, следуя спецификации навыков агента, используя захват источников, глубинные ворота, авторство, регистрацию и проверку, с фокусом на максимизации покрытия входных данных высокого значения и минимизации слепых зон, используя принципы проектирования и выбор режима.","ar":"يمنح الوكلاء khảية إنشاء ودمج وتحسين المهارات بشكل متكرر اتباعا لمواصفات مهارات الوكيل، باستخدام التقاط المصادر وأبواب العمق والكتابة والتسجيل والتحقق، مع التركيز على تعظيم تغطية المدخلات القيمة العالية وتقليل النقاط العمياء، واستخدام مبادئ التصميم واختيار الوضع."},"useCases":{"en":["Creating skills from scratch using comprehensive content analysis","Improving existing skills through iterative refinement and validation","Synthesizing sources into new skills, handling depth gates and authoring constraints"],"zh":["使用综合内容分析从头开始创建技能","通过迭代改进和验证来改进现有技能","综合来源以创建新技能，处理深度门和创作约束"],"ja":["包括的コンテンツ分析を使用してスキルを作成する","反復改善と検証を通じて既存のスキルを改善する","ソースを統合して新しいスキルを作成し、デプスゲートとオーサリング制約を処理する"],"ko":["포괄적인 콘텐츠 분석을 사용하여 스킬을 처음부터 생성하는 것","반복적인 개선과 검증을 통해 기존 스킬을 개선하는 것","소스를 통합하여 새로운 스킬을 생성하고, 디프스 게이트 및 저작 제약을 처리하는 것"],"es":["Crear habilidades desde cero utilizando un análisis de contenido integral","Mejorar habilidades existentes a través de un refinamiento y validación iterativos","Sintetizar fuentes en nuevas habilidades, manejar puertas de profundidad y restricciones de autoría"],"fr":["Créer des compétences à partir de zéro en utilisant une analyse de contenu complète","Améliorer les compétences existantes à travers un raffinement et une validation itératifs","Synthétiser des sources en nouvelles compétences, gérer les portes de profondeur et les contraintes d''authoring"],"de":["Fähigkeiten von Grund auf erstellen, indem eine umfassende Inhaltsanalyse verwendet wird","Vorhandene Fähigkeiten durch iteratives Verfeinern und Validieren verbessern","Quellen in neue Fähigkeiten synthetisieren, Tiefen-Schranken und Autorenschafts-Beschränkungen handhaben"],"pt":["Criando habilidades do zero usando análise de conteúdo abrangente","Melhorando habilidades existentes por meio de refinamento e validação iterativos","Sintetizando fontes em novas habilidades, lidando com portas de profundidade e restrições de autoria"],"ru":["Создание навыков с нуля с использованием всестороннего анализа контента","Улучшение существующих навыков посредством итеративного уточнения и проверки","Синтез источников в новые навыки, обработка глубинных ворот и ограничений авторства"],"ar":["إنشاء مهارات من الصفر باستخدام تحليل محتوى شامل","تحسين المهارات الحالية من خلال التطوير والتحقق المتكرر","دمج المصادر في مهارات جديدة، التعامل مع أبواب العمق وقيود الكتابة"]},"limitations":{"en":["Requires references to mode-selection and design-principles documentation","Limited to skills following the Agent Skills specification"],"zh":["需要引用模式选择和设计原则文档","仅限于遵循Agent Skills规范的技能"],"ja":["モード選択と設計原則のドキュメントへの参照が必要","エージェントスキル仕様に従ったスキルに限定される"],"ko":["모드 선택 및 설계 원칙 문서 참조가 필요함","에이전트 스킬 사양을 따르는 스킬에만 한정됨"],"es":["Requiere referencias a la documentación de selección de modo y principios de diseño","Limitado a habilidades que siguen la especificación de habilidades del agente"],"fr":["Nécessite des références à la documentation de sélection de mode et de principes de conception","Limité aux compétences qui suivent la spécification des compétences de l''agent"],"de":["Benötigt Verweise auf die Modusaufwahl- und Entwurfsprinzipien-Dokumentation","Begrenzt auf Fähigkeiten, die der Agent-Fähigkeiten-Spezifikation folgen"],"pt":["Exige referências à documentação de seleção de modo e princípios de design","Limitado a habilidades que seguem a especificação de Habilidades do Agente"],"ru":["Требует ссылок на документацию по выбору режима и принципам проектирования","Ограничен навыками, следующими спецификации навыков агента"],"ar":["يتطلب مراجع إلى وثائق اختيار الوضع ومبادئ التصميم","محدود بالمهارات التي تتبع مواصفات مهارات الوكيل"]},"version":4},"contentHash":"66ea94bed313eaa6644d4ebcbff7c7e2a90d2b9a7c183e807454290c47a6a35f","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":79}');
