INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/skill-writer', 'skill-writer', 'getsentry', 'skills', 'official', 'skill-writer getsentry skills official tag-production The Skill-Writer skill creates, synthesizes, and iteratively improves agent skills following the Agent Skills specification, benefiting AI agent developers. It handles source capture, depth gates, authoring, registration, and validation. Skill Writer 是用于创建和改进 AI エージェント技能的工具，提供源捕获、深度门控、编写、注册和验证等功能 Skill Writer は、AIエージェントのスキルを作成、改善するためのツールで、ソースの収集、深度ゲート、著作、登録、検証などの機能を提供 Skill Writer는 AI 에이전트 스킬을 생성하고 개선하는 도구로, 소스 캡처, 심도 게이트, 저작, 등록 및 검증 등의 기능을 제공 El skill-writer es una herramienta para crear y mejorar habilidades de Agentes de IA, siguiendo la especificación de habilidades de Agentes. Maximiza la cobertura de entrada de alto valor antes de la autoría. Le skill-writer est un outil pour créer et améliorer les compétences des Outils d''IA, en suivant la spécification des compétences des Agents. Maximise la couverture des entrées de haute valeur avant l''authoring. Der skill-writer ist ein Tool zum Erstellen und Verbessern von Fähigkeiten von KI-Agents, unter Einhaltung der Spezifikation der Fähigkeiten von Agents. Maximiert die Abdeckung von hochwertigen Eingaben vor der Autorisierung. O Skill-Writer é uma ferramenta para criar e melhorar habilidades de agentes de IA, garantindo uma cobertura de entrada de alto valor Skill-Writer — это инструмент для создания и улучшения навыков ИИ Агентов, обеспечивающий максимальную покрытие входных данных высокого качества Skill-Writer هو أداة لإنشاء وتحسين مهارات وكلاء الذكاء الاصطناعي، مما يضمن تغطية الإدخال عالية القيمة how to use skill-writer what is skill-writer skill-writer alternative skill-writer setup guide skill-writer install agent skills specification ai agent skill creation skill improvement workflow maximizing high-value input coverage AI エージェント技能创建 Skill Writer AI工具 技能改进 源捕获 深度门控 编写和注册 验证和改进 Loads required paths for tasks, such as setting skill class and dimensions via references/mode-selection.md Applies writing constraints for depth vs concision using references/design-principles.md Selects structure patterns for skills Handles source capture and depth gates Performs authoring, registration, and validation of skills Skill-writer is a canonical workflow for skill creation and improvement, ensuring minimal blind spots in resulting skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('remotion-dev/skills/remotion', 'official', 'remotion-dev', 'skills', 'remotion-dev/skills', 'remotion-best-practices', 1913, 232, 78, '2026-03-06T03:19:56Z', '2026-03-06T04:48:45.131Z', '2f9be561c1c3659aea1b4c777a9b57733dcd466b6e85231316d2841d947584bf', '{"id":"remotion-dev/skills/remotion","name":"remotion-best-practices","description":{"en":"remotion-best-practices provides domain-specific knowledge for Remotion code, helping developers create high-quality videos in React. It covers best practices for captions, FFmpeg usage, and audio visualization.","zh":"Remotion 最佳实践指南，用于优化 React 视频创建，包括字幕、FFmpeg 和音频可视化","ja":"Remotion のベストプラクティスを使用して React ビデオ作成を最適化します。字幕、FFmpeg、音频可視化など","ko":"Remotion 최적화 가이드를 사용하여 React 비디오 생성을 개선하세요. 자막, FFmpeg, 오디오 시각화 등","es":"Remotion es una herramienta para crear vídeos en React. Aprende a utilizarla de manera efectiva","fr":"Remotion est un outil pour créer des vidéos dans React. Apprenez à l''utiliser de manière efficace","de":"Remotion ist ein Tool für die Erstellung von Videos in React. Erfahren Sie, wie Sie es effektiv verwenden","pt":"Remotion é uma ferramenta para criação de vídeos em React. Este guia fornece as melhores práticas para otimizar seu workflow","ru":"Remotion - это инструмент для создания видео в React. Этот гид предоставляет лучшие практики для оптимизации вашего рабочего процесса","ar":"Remotion هي أداة لإنشاء مقاطع فيديو في React. هذا الدليل يوفر أفضل الممارسات لتحسين تدفق عملك"},"owner":"remotion-dev","repo":"skills","repoPath":"remotion-dev/skills","stars":1913,"forks":232,"updatedAt":"2026-03-06T03:19:56Z","topics":[],"skillMd":{"name":"remotion-best-practices","description":"Best practices for Remotion - Video creation in React","tags":"remotion, video, react, animation, composition","bodyPreview":"## When to use\n\nUse this skills whenever you are dealing with Remotion code to obtain the domain-specific knowledge.\n\n## Captions\n\nWhen dealing with captions or subtitles, load the [./rules/subtitles.md](./rules/subtitles.md) file for more information.\n\n## Using FFmpeg\n\nFor some video operations, such as trimming videos or detecting silence, FFmpeg should be used. Load the [./rules/ffmpeg.md](./rules/ffmpeg.md) file for more information.\n\n## Audio visualization\n\nWhen needing to visualize audio (","body":"## When to use\n\nUse this skills whenever you are dealing with Remotion code to obtain the domain-specific knowledge.\n\n## Captions\n\nWhen dealing with captions or subtitles, load the [./rules/subtitles.md](./rules/subtitles.md) file for more information.\n\n## Using FFmpeg\n\nFor some video operations, such as trimming videos or detecting silence, FFmpeg should be used. Load the [./rules/ffmpeg.md](./rules/ffmpeg.md) file for more information.\n\n## Audio visualization\n\nWhen needing to visualize audio (spectrum bars, waveforms, bass-reactive effects), load the [./rules/audio-visualization.md](./rules/audio-visualization.md) file for more information.\n\n## Sound effects\n\nWhen needing to use sound effects, load the [./rules/sound-effects.md](./rules/sound-effects.md) file for more information.\n\n## How to use\n\nRead individual rule files for detailed explanations and code examples:\n\n- [rules/3d.md](rules/3d.md) - 3D content in Remotion using Three.js and React Three Fiber\n- [rules/animations.md](rules/animations.md) - Fundamental animation skills for Remotion\n- [rules/assets.md](rules/assets.md) - Importing images, videos, audio, and fonts into Remotion\n- [rules/audio.md](rules/audio.md) - Using audio and sound in Remotion - importing, trimming, volume, speed, pitch\n- [rules/calculate-metadata.md](rules/calculate-metadata.md) - Dynamically set composition duration, dimensions, and props\n- [rules/can-decode.md](rules/can-decode.md) - Check if a video can be decoded by the browser using Mediabunny\n- [rules/charts.md](rules/charts.md) - Chart and data visualization patterns for Remotion (bar, pie, line, stock charts)\n- [rules/compositions.md](rules/compositions.md) - Defining compositions, stills, folders, default props and dynamic metadata\n- [rules/extract-frames.md](rules/extract-frames.md) - Extract frames from videos at specific timestamps using Mediabunny\n- [rules/fonts.md](rules/fonts.md) - Loading Google Fonts and local fonts in Remotion\n- [rules/get-audio-duration.md](rules/get-audio-duration.md) - Getting the duration of an audio file in seconds with Mediabunny\n- [rules/get-video-dimensions.md](rules/get-video-dimensions.md) - Getting the width and height of a video file with Mediabunny\n- [rules/get-video-duration.md](rules/get-video-duration.md) - Getting the duration of a video file in seconds with Mediabunny\n- [rules/gifs.md](rules/gifs.md) - Displaying GIFs synchronized with Remotion''s timeline\n- [rules/images.md](rules/images.md) - Embedding images in Remotion using the Img component\n- [rules/light-leaks.md](rules/light-leaks.md) - Light leak overlay effects using @remotion/light-leaks\n- [rules/lottie.md](rules/lottie.md) - Embedding Lottie animations in Remotion\n- [rules/measuring-dom-nodes.md](rules/measuring-dom-nodes.md) - Measuring DOM element dimensions in Remotion\n- [rules/measuring-text.md](rules/measuring-text.md) - Measuring text dimensions, fitting text to containers, and checking overflow\n- [rules/sequencing.md](rules/sequencing.md) - Sequencing patterns for Remotion - delay, trim, limit duration of items\n- [rules/tailwind.md](rules/tailwind.md) - Using TailwindCSS in Remotion\n- [rules/text-animations.md](rules/text-animations.md) - Typography and text animation patterns for Remotion\n- [rules/timing.md](rules/timing.md) - Interpolation curves in Remotion - linear, easing, spring animations\n- [rules/transitions.md](rules/transitions.md) - Scene transition patterns for Remotion\n- [rules/transparent-videos.md](rules/transparent-videos.md) - Rendering out a video with transparency\n- [rules/trimming.md](rules/trimming.md) - Trimming patterns for Remotion - cut the beginning or end of animations\n- [rules/videos.md](rules/videos.md) - Embedding videos in Remotion - trimming, volume, speed, looping, pitch\n- [rules/parameters.md](rules/parameters.md) - Make a video parametrizable by adding a Zod schema\n- [rules/maps.md](rules/maps.md) - Add a map using Mapbox and animate it\n- [rules/voiceover.md](rules/voiceover.md) - Adding AI-generated voiceover to Remotion compositions using ElevenLabs TTS\n"},"category":"official","lastSynced":"2026-03-06T04:48:45.131Z","seo":{"title":{"en":"remotion-best-practices: Video Creation Best Practices fo...","zh":"Remotion 最佳实践指南 - React 视频创建优化","ja":"Remotion ベストプラクティスセットアップガイド - React ビデオ作成","ko":"Remotion 최적화 가이드 - React 비디오 생성 베스트 프랙티스","es":"Guía de configuración de Remotion para React","fr":"Meilleures pratiques de Remotion pour la création de vidé...","de":"Remotion-Setup-Leitfaden für React-Entwickler","pt":"Melhores Práticas para Remotion: Guia de Configuração","ru":"Лучшие практики для Remotion: Настройка и ИИ Агенты","ar":"أفضل الممارسات ل Remotion: دليل الإعداد وآلات الذكاء الاص..."},"description":{"en":"Unlock expert Remotion techniques for React video creation. Learn how to optimize captions, leverage FFmpeg, and visualize audio for stunning results. Get st...","zh":"了解 Remotion 的最佳实践，优化 React 视频创建，提高开发效率，AIエージェント","ja":"Remotion のベストプラクティスを学び、React ビデオ作成を最適化して開発効率を向上させる、AIエージェント","ko":"Remotion의 최적화된 가이드를 통해 React 비디오 생성을 개선하고 개발 효율성을 높이세요, AI 도구","es":"Aprende las mejores prácticas para crear vídeos en React con Remotion y mejora tus habilidades como desarrollador","fr":"Découvrez les meilleures pratiques pour créer des vidéos dans React avec Remotion et améliorez vos compétences de développeur","de":"Erfahren Sie die besten Praktiken für die Erstellung von Videos in React mit Remotion und verbessern Sie Ihre Fähigkeiten als Entwickler","pt":"Aprenda a criar vídeos em React com Remotion, seguindo as melhores práticas e dicas para otimizar seu workflow","ru":"Узнайте, как создавать видео в React с помощью Remotion, следуя лучшим практикам и советам для оптимизации вашего рабочего процесса и ИИ Агентов","ar":"تعلم كيفية إنشاء مقاطع فيديو في React باستخدام Remotion، باتباع أفضل الممارسات والنصائح لتحسين تدفق عملك وآلات الذكاء الاصطناعي"},"definition":{"en":"remotion-best-practices is a set of guidelines for creating videos in React using Remotion, covering topics such as caption management, FFmpeg integration, and audio visualization techniques.","zh":"Remotion 最佳实践是指在 React 中创建视频时遵循的最佳方法和指南","ja":"Remotion のベストプラクティスとは、React でビデオを作成する際に従うべき最佳方法とガイドライン","ko":"Remotion 최적화는 React에서 비디오를 생성할 때 따라야 하는 최적의 방법과 가이드를 의미합니다","es":"Remotion es una herramienta de código abierto para crear vídeos en React","fr":"Remotion est un outil open source pour créer des vidéos dans React","de":"Remotion ist ein Open-Source-Tool für die Erstellung von Videos in React","pt":"Remotion é uma ferramenta para criação de vídeos em React, que fornece funcionalidades para legendas, FFmpeg e visualização de áudio","ru":"Remotion - это инструмент для создания видео в React, который предоставляет функциональность для субтитров, FFmpeg и визуализации аудио","ar":"Remotion هي أداة لإنشاء مقاطع فيديو في React، التي توفر وظائف للتعليقات الصوتية و FFmpeg وتصوير الصوت"},"features":{"en":["Loads subtitles and captions using the ./rules/subtitles.md file","Utilizes FFmpeg for video operations like trimming and silence detection","References the ./rules/ffmpeg.md file for advanced FFmpeg usage","Visualizes audio for enhanced video creation","Provides domain-specific knowledge for Remotion code optimization","Supports React-based video development"],"zh":["字幕和字幕加载","FFmpeg 集成","音频可视化","React 视频创建优化","开发效率提高","AIエージェント集成"],"ja":["字幕と字幕の読み込み","FFmpeg 統合","音频可視化","React ビデオ作成の最適化","開発効率の向上","AIエージェント統合"],"ko":["자막과 자막 로딩","FFmpeg 통