INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('remotion-dev/skills/remotion', 'remotion-best-practices', 'remotion-dev', 'skills', 'official', 'remotion-best-practices remotion-dev skills official remotion-best-practices provides domain-specific knowledge for Remotion code, helping developers create high-quality videos in React. It covers best practices for captions, FFmpeg usage, and audio visualization. Remotion 最佳实践指南，用于优化 React 视频创建，包括字幕、FFmpeg 和音频可视化 Remotion のベストプラクティスを使用して React ビデオ作成を最適化します。字幕、FFmpeg、音频可視化など Remotion 최적화 가이드를 사용하여 React 비디오 생성을 개선하세요. 자막, FFmpeg, 오디오 시각화 등 Remotion es una herramienta para crear vídeos en React. Aprende a utilizarla de manera efectiva Remotion est un outil pour créer des vidéos dans React. Apprenez à l''utiliser de manière efficace Remotion ist ein Tool für die Erstellung von Videos in React. Erfahren Sie, wie Sie es effektiv verwenden Remotion é uma ferramenta para criação de vídeos em React. Este guia fornece as melhores práticas para otimizar seu workflow Remotion - это инструмент для создания видео в React. Этот гид предоставляет лучшие практики для оптимизации вашего рабочего процесса Remotion هي أداة لإنشاء مقاطع فيديو في React. هذا الدليل يوفر أفضل الممارسات لتحسين تدفق عملك how to use remotion-best-practices remotion-best-practices tutorial remotion vs react-video remotion-best-practices install remotion-best-practices setup guide react video creation best practices ffmpeg for video editing remotion caption management audio visualization in remotion Remotion 最佳实践 React 视频创建 字幕加载 FFmpeg 音频可视化 AIエージェント 开发效率 React 优化 视频创建 Loads subtitles and captions using the ./rules/subtitles.md file Utilizes FFmpeg for video operations like trimming and silence detection References the ./rules/ffmpeg.md file for advanced FFmpeg usage Visualizes audio for enhanced video creation Provides domain-specific knowledge for Remotion code optimization Supports React-based video development remotion-best-practices is a set of guidelines for creating videos in React using Remotion, covering topics such as caption management, FFmpeg integration, and audio visualization techniques.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/xlsx', 'official', 'anthropics', 'skills', 'anthropics/skills', 'xlsx', 85097, 8974, 77, '2026-03-06T03:11:21Z', '2026-03-06T03:26:42.464Z', 'dd316db7785a6be12966c2a2d848931fbf5f518b3cdb0a66fa62ee835ead1cfc', '{"id":"anthropics/skills/xlsx","name":"xlsx","description":{"en":"The xlsx AI Agent skill automates spreadsheet operations, including reading, editing, formatting, and cleaning .xlsx, .csv, and .tsv files. It is designed for developers and data professionals who need to programmatically generate or process Excel files with precision and consistency.","zh":"xlsx 是一项 AI 代理技能，专为处理电子表格文件（.xlsx, .csv, .tsv）而设计。它能自动化执行数据清洗、公式计算、格式调整及文件格式转换，并确保输出文件零错误且格式专业。","ja":"xlsx はスプレッドシートファイル（.xlsx, .csv, .tsv）を処理するためのAIエージェントスキルです。データクリーニング、数式計算、書式設定、ファイル形式変換を自動化し、出力ファイルのゼロエラーとプロフェッショナルなフォーマットを保証します。","ko":"xlsx는 스프레드시트 파일(.xlsx, .csv, .tsv) 처리를 위한 AI 에이전트 스킬입니다. 데이터 클리닝, 수식 계산, 서식 지정, 파일 형식 변환을 자동화하며 출력 파일의 제로 오류와 전문적인 형식을 보장합니다.","es":"Esta habilidad de agente de IA permite a los desarrolladores automatizar tareas complejas de hojas de cálculo, incluyendo la lectura, edición, limpieza de datos y creación de archivos .xlsx y .csv. Garantiza salidas profesionales sin errores de fórmula y preserva el formato de plantillas existentes.","fr":"Cette compétence d''agent IA permet aux développeurs d''automatiser des tâches complexes de feuilles de calcul, incluant la lecture, l''édition, le nettoyage de données et la création de fichiers .xlsx et .csv. Garantit des sorties professionnelles sans erreurs de formule et préserve le format des m...","de":"Diese KI-Agenten-Fähigkeit ermöglicht Entwicklern die Automatisierung komplexer Tabellenkalkulationsaufgaben, einschließlich Lesen, Bearbeiten, Datenbereinigung und Erstellung von .xlsx- und .csv-Dateien. Stellt professionelle Ausgaben ohne Formelfehler sicher und erhält das Format vorhandener Vo...","pt":"O skill xlsx para AI Agents é uma ferramenta técnica para desenvolvedores automatizarem a manipulação de arquivos de planilha, incluindo XLSX, CSV e TSV. Ele garante zero erros de fórmula, formatação profissional e conversão de formato.","ru":"Навык xlsx для ИИ Агентов — это технический инструмент для разработчиков, позволяющий автоматизировать обработку файлов электронных таблиц, включая XLSX, CSV и TSV. Он гарантирует отсутствие ошибок формул, профессиональное форматирование и преобразование форматов.","ar":"مهارة xlsx لوكلاء الذكاء الاصطناعي هي أداة تقنية للمطورين لأتمتة معالجة ملفات جداول البيانات، بما في ذلك XLSX و CSV و TSV. يضمن عدم وجود أخطاء في الصيغة، والتنسيق الاحترافي وتحويل التنسيق."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"xlsx","description":"Use this skill any time a spreadsheet file is the primary input or output. This means any task where the user wants to: open, read, edit, or fix an existing .xlsx, .xlsm, .csv, or .tsv file (e.g., adding columns, computing formulas, formatting, charting, cleaning messy data); create a new spreadsheet from scratch or from other data sources; or convert between tabular file formats. Trigger especially when the user references a spreadsheet file by name or path — even casually (like \\the xlsx in my downloads\\) — and wants something done to it or produced from it. Also trigger for cleaning or restructuring messy tabular data files (malformed rows, misplaced headers, junk data) into proper spreadsheets. The deliverable must be a spreadsheet file. Do NOT trigger when the primary deliverable is a Word document, HTML report, standalone Python script, database pipeline, or Google Sheets API integration, even if tabular data is involved.","bodyPreview":"# Requirements for Outputs\n\n## All Excel files\n\n### Professional Font\n- Use a consistent, professional font (e.g., Arial, Times New Roman) for all deliverables unless otherwise instructed by the user\n\n### Zero Formula Errors\n- Every Excel model MUST be delivered with ZERO formula errors (#REF!, #DIV/0!, #VALUE!, #N/A, #NAME?)\n\n### Preserve Existing Templates (when updating templates)\n- Study and EXACTLY match existing format, style, and conventions when modifying files\n- Never impose standardize","body":"# Requirements for Outputs\n\n## All Excel files\n\n### Professional Font\n- Use a consistent, professional font (e.g., Arial, Times New Roman) for all deliverables unless otherwise instructed by the user\n\n### Zero Formula Errors\n- Every Excel model MUST be delivered with ZERO formula errors (#REF!, #DIV/0!, #VALUE!, #N/A, #NAME?)\n\n### Preserve Existing Templates (when updating templates)\n- Study and EXACTLY match existing format, style, and conventions when modifying files\n- Never impose standardized formatting on files with established patterns\n- Existing template conventions ALWAYS override these guidelines\n\n## Financial models\n\n### Color Coding Standards\nUnless otherwise stated by the user or existing template\n\n#### Industry-Standard Color Conventions\n- **Blue text (RGB: 0,0,255)**: Hardcoded inputs, and numbers users will change for scenarios\n- **Black text (RGB: 0,0,0)**: ALL formulas and calculations\n- **Green text (RGB: 0,128,0)**: Links pulling from other worksheets within same workbook\n- **Red text (RGB: 255,0,0)**: External links to other files\n- **Yellow background (RGB: 255,255,0)**: Key assumptions needing attention or cells that need to be updated\n\n### Number Formatting Standards\n\n#### Required Format Rules\n- **Years**: Format as text strings (e.g., \"2024\" not \"2,024\")\n- **Currency**: Use $#,##0 format; ALWAYS specify units in headers (\"Revenue ($mm)\")\n- **Zeros**: Use number formatting to make all zeros \"-\", including percentages (e.g., \"$#,##0;($#,##0);-\")\n- **Percentages**: Default to 0.0% format (one decimal)\n- **Multiples**: Format as 0.0x for valuation multiples (EV/EBITDA, P/E)\n- **Negative numbers**: Use parentheses (123) not minus -123\n\n### Formula Construction Rules\n\n#### Assumptions Placement\n- Place ALL assumptions (growth rates, margins, multiples, etc.) in separate assumption cells\n- Use cell references instead of hardcoded values in formulas\n- Example: Use =B5*(1+$B$6) instead of =B5*1.05\n\n#### Formula Error Prevention\n- Verify all cell references are correct\n- Check for off-by-one errors in ranges\n- Ensure consistent formulas across all projection periods\n- Test with edge cases (zero values, negative numbers)\n- Verify no unintended circular references\n\n#### Documentation Requirements for Hardcodes\n- Comment or in cells beside (if end of table). Format: \"Source: [System/Document], [Date], [Specific Reference], [URL if applicable]\"\n- Examples:\n  - \"Source: Company 10-K, FY2024, Page 45, Revenue Note, [SEC EDGAR URL]\"\n  - \"Source: Company 10-Q, Q2 2025, Exhibit 99.1, [SEC EDGAR URL]\"\n  - \"Source: Bloomberg Terminal, 8/15/2025, AAPL US Equity\"\n  - \"Source: FactSet, 8/20/2025, Consensus Estimates Screen\"\n\n# XLSX creation, editing, and analysis\n\n## Overview\n\nA user may ask you to create, edit, or analyze the contents of an .xlsx file. You have different tools and workflows available for different tasks.\n\n## Important Requirements\n\n**LibreOffice Required for Formula Recalculation**: You can assume LibreOffice is installed for recalculating formula values using the `scripts/recalc.py` script. The script automatically configures LibreOffice on first run, including in sandboxed environments where Unix sockets are restricted (handled by `scripts/office/soffice.py`)\n\n## Reading and analyzing data\n\n### Data analysis with pandas\nFor data analysis, visualization, and basic operations, use **pandas** which provides powerful data manipulation capabilities:\n\n```python\nimport pandas as pd\n\n# Read Excel\ndf = pd.read_excel(''file.xlsx'')  # Default: first sheet\nall_sheets = pd.read_excel(''file.xlsx'', sheet_name=None)  # All sheets as dict\n\n# Analyze\ndf.head()      # Preview data\ndf.info()      # Column info\ndf.describe()  # Statistics\n\n# Write Excel\ndf.to_excel(''output.xlsx'', index=False)\n```\n\n## Excel File Workflows\n\n## CRITICAL: Use Formulas, Not Hardcoded Values\n\n**Always use Excel formulas instead of calculating values in Python and hardcoding them.** This ensures the spreadsheet remains dynamic and updateable.\n\n### ❌ WRONG - Hardcoding Calculated Values\n```python\n# Bad: Calculating in Python and hardcoding result\ntotal = df[''Sales''].sum()\nsheet[''B10''] = total  # Hardcodes 5000\n\n# Bad: Computing growth rate in Python\ngrowth = (df.iloc[-1][''Revenue''] - df.iloc[0][''Revenue'']) / df.iloc[0][''Revenue'']\nsheet[''C5''] = growth  # Hardcodes 0.15\n\n# Bad: Python calculation for average\navg = sum(values) / len(values)\nsheet[''D20''] = avg  # Hardcodes 42.5\n```\n\n### ✅ CORRECT - Using Excel Formulas\n```python\n# Good: Let Excel calculate the sum\nsheet[''B10''] = ''=SUM(B2:B9)''\n\n# Good: Growth rate as Excel formula\nsheet[''C5''] = ''=(C4-C2)/C2''\n\n# Good: Average using Excel function\nsheet[''D20''] = ''=AVERAGE(D2:D19)''\n```\n\nThis applies to ALL calculations - totals, percentages, ratios, differences, etc. The spreadsheet should be able to recalculate when source data changes.\n\n## Common Workflow\n1. **Choose tool**: pandas for data, openpyxl for formulas/formatting\n2. **Create/Load**: Create new workbook or load existing file\n3. **Modify**: Add/edit data, formulas, and formatting\n4. **Save**: Write to file\n5. **Recalculate formulas (MANDATORY IF USING FORMULAS)**: Use the scripts/recalc.py script\n   ```bash\n   python scripts/recalc.py output.xlsx\n   ```\n6. **Verify and fix any errors**: \n   - The script returns JSON with error details\n   - If `status` is `errors_found`, check `error_summary` for specific error types and locations\n   - Fix the identified errors and recalculate again\n   - Common errors to fix:\n     - `#REF!`: Invalid cell references\n     - `#DIV/0!`: Division by zero\n     - `#VALUE!`: Wrong data type in formula\n     - `#NAME?`: Unrecognized formula name\n\n### Creating new Excel files\n\n```python\n# Using openpyxl for formulas and formatting\nfrom openpyxl import Workbook\nfrom openpyxl.styles import Font, PatternFill, Alignment\n\nwb = Workbook()\nsheet = wb.active\n\n# Add data\nsheet[''A1''] = ''Hello''\nsheet[''B1''] = ''World''\nsheet.append([''Row'', ''of'', ''data''])\n\n# Add formula\nsheet[''B2''] = ''=SUM(A1:A10)''\n\n# Formatting\nsheet[''A1''].font = Font(bold=True, color=''FF0000'')\nsheet[''A1''].fill = PatternFill(''solid'', start_color=''FFFF00'')\nsheet[''A1''].alignment = Alignment(horizontal=''center'')\n\n# Column width\nsheet.column_dimensions[''A''].width = 20\n\nwb.save(''output.xlsx'')\n```\n\n### Editing existing Excel files\n\n```python\n# Using openpyxl to preserve formulas and formatting\nfrom openpyxl import load_workbook\n\n# Load existing file\nwb = load_workbook(''existing.xlsx'')\nsheet = wb.active  # or wb[''SheetName''] for specific sheet\n\n# Working with multiple sheets\nfor sheet_name in wb.sheetnames:\n    sheet = wb[sheet_name]\n    print(f\"Sheet: {sheet_name}\")\n\n# Modify cells\nsheet[''A1''] = ''New Value''\nsheet.insert_rows(2)  # Insert row at position 2\nsheet.delete_cols(3)  # Delete column 3\n\n# Add new sheet\nnew_sheet = wb.create_sheet(''NewSheet'')\nnew_sheet[''A1''] = ''Data''\n\nwb.save(''modified.xlsx'')\n```\n\n## Recalculating formulas\n\nExcel files created or modified by openpyxl contain formulas as strings but not calculated values. Use the provided `scripts/recalc.py` script to recalculate formulas:\n\n```bash\npython scripts/recalc.py <excel_file> [timeout_seconds]\n```\n\nExample:\n```bash\npython scripts/recalc.py output.xlsx 30\n```\n\nThe script:\n- Automatically sets up LibreOffice macro on first run\n- Recalculates all formulas in all sheets\n- Scans ALL cells for Excel errors (#REF!, #DIV/0!, etc.)\n- Returns JSON with detailed error locations and counts\n- Works on both Linux and macOS\n\n## Formula Verification Checklist\n\nQuick checks to ensure formulas work correctly:\n\n### Essential Verification\n- [ ] **Test 2-3 sample references**: Verify they pull correct values before building full model\n- [ ] **Column mapping**: Confirm Excel columns match (e.g., column 64 = BL, not BK)\n- [ ] **Row offset**: Remember Excel rows are 1-indexed (DataFrame row 5 = Excel row 6)\n\n### Common Pitfalls\n- [ ] **NaN handling**: Check for null values with `pd.notna()`\n- [ ] **Far-right columns**: FY data often in columns 50+ \n- [ ] **Multiple matches**: Search all occurrences, not just first\n- [ ] **Division by zero**: Check denominators before using `/` in formulas (#DIV/0!)\n- [ ] **Wrong references**: Verify all cell references point to intended cells (#REF!)\n- [ ] **Cross-sheet references**: Use correct format (Sheet1!A1) for linking sheets\n\n### Formula Testing Strategy\n- [ ] **Start small**: Test formulas on 2-3 cells before applying broadly\n- [ ] **Verify dependencies**: Check all cells referenced in formulas exist\n- [ ] **Test edge cases**: Include zero, negative, and very large values\n\n### Interpreting scripts/recalc.py Output\nThe script returns JSON with error details:\n```json\n{\n  \"status\": \"success\",           // or \"errors_found\"\n  \"total_errors\": 0,              // Total error count\n  \"total_formulas\": 42,           // Number of formulas in file\n  \"error_summary\": {              // Only present if errors found\n    \"#REF!\": {\n      \"count\": 2,\n      \"locations\": [\"Sheet1!B5\", \"Sheet1!C10\"]\n    }\n  }\n}\n```\n\n## Best Practices\n\n### Library Selection\n- **pandas**: Best for data analysis, bulk operations, and simple data export\n- **openpyxl**: Best for complex formatting, formulas, and Excel-specific features\n\n### Working with openpyxl\n- Cell indices are 1-based (row=1, column=1 refers to cell A1)\n- Use `data_only=True` to read calculated values: `load_workbook(''file.xlsx'', data_only=True)`\n- **Warning**: If opened with `data_only=True` and saved, formulas are replaced with values and permanently lost\n- For large files: Use `read_only=True` for reading or `write_only=True` for writing\n- Formulas are preserved but not evaluated - use scripts/recalc.py to update values\n\n### Working with pandas\n- Specify data types to avoid inference issues: `pd.read_excel(''file.xlsx'', dtype={''id'': str})`\n- For large files, read specific columns: `pd.read_excel(''file.xlsx'', usecols=[''A'', ''C'', ''E''])`\n- Handle dates properly: `pd.read_excel(''file.xlsx'', parse_dates=[''date_column''])`\n\n## Code Style Guidelines\n**IMPORTANT**: When generating Python code for Excel operations:\n- Write minimal, concise Python code without unnecessary comments\n- Avoid verbose variable names and redundant operations\n- Avoid unnecessary print statements\n\n**For Excel files themselves**:\n- Add comments to cells with complex formulas or important assumptions\n- Document data sources for hardcoded values\n- Include notes for key calculations and model sections"},"category":"official","lastSynced":"2026-03-06T03:26:42.464Z","seo":{"title":{"en":"xlsx Skill: Automate Excel Spreadsheet Tasks | AI Agent S...","zh":"xlsx AI 代理技能设置指南：Excel 文件自动化处理","ja":"xlsx AIエージェントスキル：Excelファイル操作のベストプラクティス","ko":"xlsx AI 에이전트 스킬 설정 가이드: Excel 파일 자동화 처리","es":"xlsx AI Agent: Guía de Automatización de Hojas de Cálculo","fr":"xlsx AI Agent: Guide de l''Automatisation des Feuilles de ...","de":"xlsx AI Agent: Leitfaden zur Tabellenkalkulations-Automat...","pt":"xlsx AI Agent: Guia de Manipulação de Planilhas para Dese...","ru":"xlsx ИИ Агент: Руководство по обработке электронных табли...","ar":"وكيل الذكاء الاصطناعي xlsx: دليل معالجة جداول البيانات لل..."},"description":{"en":"Automate .xlsx, .csv & .tsv tasks: read, edit, format & clean data. This AI Agent skill delivers professional spreadsheets with zero formula errors. Master E...","zh":"专为开发者设计的xlsx AI代理技能，可自动读取、编辑.xlsx/.csv文件，修复数据错误，保持专业格式与零公式错误。适用于数据处理与文件转换任务。","ja":"開発者向けxlsx AIエージェントスキル。.xlsx/.csvファイルの自動読み込み、編集、データエラー修正、プロフェッショナルなフォーマット維持とゼロ数式エラーを実現。","ko":"개발자를 위한 xlsx AI 에이전트 스킬. .xlsx/.csv 파일 자동 읽기, 편집, 데이터 오류 수정, 전문 형식 유지 및 제로 수식 오류를 제공합니다.","es":"Automatiza la manipulación de archivos .xlsx, .csv y .tsv con este agente de IA. Lee, edita, limpia datos y genera hojas de cálculo sin errores de fórmula. I...","fr":"Automatisez la manipulation des fichiers .xlsx, .csv et .tsv avec cet agent IA. Lisez, modifiez, nettoyez les données et générez des feuilles de calcul sans ...","de":"Automatisieren Sie die Bearbeitung von .xlsx-, .csv- und .tsv-Dateien mit diesem KI-Agenten. Lesen, bearbeiten, bereinigen Sie Daten und erstellen Sie Tabell...","pt":"Use o skill xlsx para AI Agents automatizar a manipulação de planilhas: ler, editar, criar XLSX, CSV, TSV. Elimine erros de fórmula (#REF!), preserve templat...","ru":"Используйте навык xlsx для ИИ Агентов для автоматизации работы с электронными таблицами: чтение, редактирование, создание XLSX, CSV, TSV. Устраняйте ошибки ф...","ar":"استخدم مهارة xlsx لوكلاء الذكاء الاصطناعي لأتمتة معالجة جداول البيانات: قراءة، تحرير، إنشاء ملفات XLSX و CSV و TSV. القضاء على أخطاء الصيغة (#REF!)، والحفاظ ..."},"definition":{"en":"xlsx is an AI Agent skill for programmatically handling spreadsheet files. It automates tasks like opening, reading, editing, formatting, and cleaning .xlsx, .xlsm, .csv, and .tsv data, ensuring professional output with zero formula errors.","zh":"xlsx 是一项 AI 代理技能，当电子表格文件是主要输入或输出时自动触发。它专门用于打开、读取、编辑 .xlsx 或 .csv 文件，执行数据清洗、公式计算，并生成零错误、格式专业的交付文件。","ja":"xlsx はスプレッドシートファイルが主な入力または出力である場合に自動的にトリガーされるAIエージェントスキルです。.xlsxや.csvファイルのオープン、読み取り、編集、データクリーニング、数式計算を専門とし、ゼロエラーでプロフェッショナルな形式の成果物を生成します。","ko":"xlsx는 스프레드시트 파일이 주요 입력 또는 출력일 때 자동으로 트리거되는 AI 에이전트 스킬입니다. .xlsx 및 .csv 파일 열기, 읽기, 편집, 데이터 클리닝, 수식 계산을 전문으로 하며 제로 오류와 전문적인 형식의 결과물을 생성합니다.","es":"La habilidad ''xlsx'' es un agente de IA diseñado para automatizar la manipulación de archivos de hoja de cálculo (.xlsx, .xlsm, .csv, .tsv). Se activa cuando la entrada principal o el entregable es un archivo tabular, realizando tareas como cálculo de fórmulas, formateo y limpieza de datos.","fr":"La compétence ''xlsx'' est un agent IA conçu pour automatiser la manipulation de fichiers de feuille de calcul (.xlsx, .xlsm, .csv, .tsv). Elle se déclenche lorsque l''entrée principale ou le livrable est un fichier tabulaire, effectuant des tâches comme le calcul de formules, le formatage et le nettoyage des données.","de":"Die ''xlsx''-Fähigkeit ist ein KI-Agent, der zur Automatisierung der Bearbeitung von Tabellenkalkulationsdateien (.xlsx, .xlsm, .csv, .tsv) entwickelt wurde. Er wird ausgelöst, wenn die primäre Eingabe oder das Lieferobjekt eine tabellarische Datei ist, und führt Aufgaben wie Formelberechnung, Formatierung und Datenbereinigung durch.","pt":"O skill xlsx é uma capacidade de AI Agent projetada para desenvolvedores que precisam automatizar a leitura, edição, criação e limpeza de arquivos de planilha como XLSX, XLSM, CSV e TSV, entregando resultados profissionais e livres de erros.","ru":"Навык xlsx — это возможность ИИ Агента, предназначенная для разработчиков, которым необходимо автоматизировать чтение, редактирование, создание и очистку файлов электронных таблиц, таких как XLSX, XLSM, CSV и TSV, обеспечивая профессиональные и безошибочные результаты.","ar":"مهارة xlsx هي قدرة وكيل الذكاء الاصطناعي مصممة للمطورين الذين يحتاجون إلى أتمتة قراءة وتحرير وإنشاء وتنظيف ملفات جداول البيانات مثل XLSX و XLSM و CSV و TSV، delivering results احترافية وخالية من الأخطاء."},"features":{"en":["Reads and edits existing .xlsx, .xlsm, .csv, and .tsv files","Cleans and restructures messy tabular data into proper spreadsheets","Ensures zero formula errors (#REF!, #DIV/0!, #VALUE!, #N/A, #NAME?) in deliverables","Uses consistent, professional fonts (e.g., Arial, Times New Roman) by default","Preserves existing format, style, and conventions when modifying template files","Converts between tabular file formats"],"zh":["支持多种文件格式：自动处理 .xlsx、.xlsm、.csv 和 .tsv 文件。","零公式错误交付：确保输出文件无 #REF!、#DIV/0! 等错误。","专业字体格式：使用 Arial 或 Times New Roman 等字体保持一致性。","模板格式保留：在修改文件时精确匹配现有的格式与样式。","混乱数据清洗：将结构不良的表格数据修复为规范的电子表格。","自动化文件转换：在不同表格文件格式之间进行转换。"],"ja":["多様なファイル形式のサポート：.xlsx、.xlsm、.csv、.tsv ファイルを自動処理。","ゼロ数式エラーの成果物：#REF!、#DIV/0! などのエラーがないことを保証。","プロフェッショナルなフォント書式：Arial 或 Times New Roman などのフォントで一貫性を維持。","テンプレート書式の維持：ファイル変更時に既存の書式とスタイルを正確に一致。","混乱データのクリーニング：構造不良の表データを規範的なスプレッドシートに修復。","自動ファイル変換：異なる表ファイル形式間で変換を実行。"],"ko":["다양한 파일 형식 지원: .xlsx, .xlsm, .csv, .tsv 파일 자동 처리.","제로 수식 오류 결과물: #REF!, #DIV/0! 등의 오류 없음을 보장.","전문적인 글꼴 형식: Arial 또는 Times New Roman 등 글꼴로 일관성 유지.","템플릿 형식 보존: 파일 수정 시 기존 형식과 스타일을 정확히 일치.","혼란 데이터 클리닝: 구조 불량 표 데이터를 규범적인 스프레드시트로 수복.","자동 파일 변환: 다른 표 파일 형식 간 변환 실행."],"es":["Conversión entre formatos tabulares (.xlsx, .csv, .tsv)","Eliminación de errores de fórmula (#REF!, #DIV/0!, #VALUE!)","Aplicación de fuentes profesionales consistentes (Arial, Times New Roman)","Preservación exacta de formatos de plantillas existentes","Limpieza y reestructuración de datos tabulares desordenados","Creación de hojas de cálculo desde cero o otras fuentes de datos"],"fr":["Conversion entre formats tabulaires (.xlsx, .csv, .tsv)","Élimination des erreurs de formule (#REF!, #DIV/0!, #VALUE!)","Application de polices professionnelles cohérentes (Arial, Times New Roman)","Préservation exacte des formats de modèles existants","Nettoyage et restructuration de données tabulaires désordonnées","Création de feuilles de calcul à partir de zéro ou d''autres sources de données"],"de":["Konvertierung zwischen tabellarischen Formaten (.xlsx, .csv, .tsv)","Beseitigung von Formelfehlern (#REF!, #DIV/0!, #VALUE!)","Anwendung konsistenter professioneller Schriftarten (Arial, Times New Roman)","Exakte Bewahrung vorhandener Vorlagenformate","Bereinigung und Umstrukturierung unordentlicher tabellarischer Daten","Erstellung von Tabellenkalkulationen von Grund auf oder aus anderen Datenquellen"],"pt":["Suporte para formatos XLSX, XLSM, CSV e TSV para leitura e escrita","Eliminação garantida de erros de fórmula Excel (#REF!, #DIV/0!, #VALUE!)","Preservação exata de formatos e estilos de templates existentes","Formatação profissional com fontes consistentes (Arial, Times New Roman)","Limpeza e reestruturação de dados tabulares desorganizados","Conversão entre formatos de arquivo tabular"],"ru":["Поддержка форматов XLSX, XLSM, CSV и TSV для чтения и записи","Гарантированное устранение ошибок формул Excel (#REF!, #DIV/0!, #VALUE!)","Точное сохранение форматов и стилей существующих шаблонов","Профессиональное форматирование с согласованными шрифтами (Arial, Times New Roman)","Очистка и реструктуризация неорганизованных табличных данных","Преобразование между форматами табличных файлов"],"ar":["دعم تنسيقات XLSX و XLSM و CSV و TSV للقراءة والكتابة","ضمان القضاء على أخطاء صيغة Excel (#REF!, #DIV/0!, #VALUE!)","الحفاظ الدقيق على تنسيقات وأنماط القوالب الحالية","تنسيق احترافي بخطوط متسقة (Arial, Times New Roman)","تنظيف وإعادة هيكلة البيانات الجدولية غير المنظمة","التحويل بين تنسيقات الملفات الجدولية"]},"keywords":{"en":["how to use xlsx skill","what is xlsx ai agent","automate excel tasks","clean csv data ai","xlsx vs openpyxl","xlsx skill setup guide","ai agent for spreadsheets","generate xlsx without errors","convert csv to xlsx","fix messy excel data"],"zh":["xlsx AI 代理","Excel 文件自动化","处理 CSV 文件 AI","数据清洗 AI 工具","零公式错误 Excel","表格文件格式转换","AI 代理电子表格技能","自动化数据修复"],"ja":["xlsx AIエージェント","Excel ファイル自動化","CSV ファイル処理 AI","データクリーニング AIツール","ゼロ数式エラー Excel","表ファイル形式変換","AIエージェント スプレッドシートスキル","自動データ修復"],"ko":["xlsx AI 에이전트","Excel 파일 자동화","CSV 파일 처리 AI","데이터 클리닝 AI 도구","제로 수식 오류 Excel","표 파일 형식 변환","AI 에이전트 스프레드시트 스킬","자동 데이터 수복"],"es":["automatizar excel con agente ia","manipular archivos xlsx python","limpiar datos csv automáticamente","convertir tsv a xlsx","eliminar errores fórmula excel","agente ia para hojas de cálculo","automatización datos tabulares","preservar formato plantilla excel"],"fr":["automatiser excel avec agent ia","manipuler fichiers xlsx python","nettoyer données csv automatiquement","convertir tsv en xlsx","éliminer erreurs formule excel","agent ia pour feuilles de calcul","automatisation données tabulaires","préserver format modèle excel"],"de":["excel mit ki agent automatisieren","xlsx dateien python bearbeiten","csv daten automatisch bereinigen","tsv zu xlsx konvertieren","formelfehler excel entfernen","ki agent für tabellenkalkulationen","automatisierung tabellarischer daten","vorlagenformat excel erhalten"],"pt":["automacao planilha python","ler arquivo xlsx ai agent","eliminar erro formula excel","converter csv para xlsx","limpar dados desorganizados","preservar template excel","skill xlsx para desenvolvedores","formato saida planilha profissional"],"ru":["автоматизация excel python","читать файл xlsx ИИ Агент","устранить ошибку формулы excel","конвертировать csv в xlsx","очистить неорганизованные данные","сохранить шаблон excel","навык xlsx для разработчиков","формат вывода профессиональная электронная таблица"],"ar":["أتمتة excel ببايثون","قراءة ملف xlsx وكيل الذكاء الاصطناعي","إصلاح خطأ صيغة excel","تحويل csv إلى xlsx","تنظيف البيانات غير المنظمة","الحفاظ على قالب excel","مهارة xlsx للمطورين","تنسيق output جدول بيانات احترافي"]}},"agentAnalysis":{"suitability":{"en":"Essential for Data Wrangling Agents that automate spreadsheet manipulation and analysis.","zh":"对于自动化电子表格操作和分析的数据整理代理至关重要。","ja":"スプレッドシートの操作と分析を自動化するデータラングリングエージェントに不可欠です。","ko":"스프레드시트 조작 및 분석을 자동화하는 데이터 랭글링 에이전트에게 필수적입니다.","es":"Esencial para agentes de manipulación de datos que automatizan la manipulación y análisis de hojas de cálculo.","fr":"Essentiel pour les agents de manipulation de données qui automatisent la manipulation et l''analyse de feuilles de calcul.","de":"Essenziell für Datenbearbeitungs-Agenten, die die Tabellenmanipulation und -analyse automatisieren.","pt":"Essencial para Agentes de Data Wrangling que automatizam a manipulação e análise de planilhas.","ru":"Необходим для агентов Data Wrangling, которые автоматизируют манипуляции с электронными таблицами и их анализ.","ar":"أساسي لوكلاء تنظيم البيانات (Data Wrangling) الذين يقومون بأتمتة معالجة وتحليل جداول البيانات."},"recommendation":{"en":"Enables direct programmatic interaction with Excel (.xlsx, .xlsm), CSV, and TSV files for reading, writing, and complex data transformation. This skill provides robust capabilities for formula computation, data cleaning (malformed rows, junk data), charting, and format conversion, ensuring professional font consistency and zero formula errors (#REF!, #DIV/0!) in deliverables.","zh":"支持对 Excel (.xlsx, .xlsm)、CSV 和 TSV 文件进行读取、写入和复杂数据转换的直接编程交互。此技能提供强大的公式计算、数据清理（格式错误行、垃圾数据）、图表生成和格式转换功能，确保交付成果具有专业的字体一致性且无公式错误（#REF!、#DIV/0!）。","ja":"Excel (.xlsx, .xlsm)、CSV、TSVファイルに対する読み取り、書き込み、複雑なデータ変換のための直接的なプログラム的インタラクションを可能にします。このスキルは、堅牢な数式計算、データクリーニング（不正な行、ジャンクデータ）、グラフ作成、フォーマット変換機能を提供し、納品物においてプロフェッショナルなフォントの一貫性と数式エラー（#REF!、#DIV/0!）のゼロ化を保証します。","ko":"Excel(.xlsx, .xlsm), CSV 및 TSV 파일에 대한 읽기, 쓰기 및 복잡한 데이터 변환을 위한 직접적인 프로그래밍 방식 상호작용을 가능하게 합니다. 이 스킬은 강력한 수식 계산, 데이터 정리(잘못된 행, 정크 데이터), 차트 생성 및 형식 변환 기능을 제공하여 최종 결과물에서 전문적인 글꼴 일관성과 수식 오류(#REF!, #DIV/0!) 없음을 보장합니다.","es":"Permite la interacción programática directa con archivos de Excel (.xlsx, .xlsm), CSV y TSV para lectura, escritura y transformación compleja de datos. Esta habilidad proporciona capacidades sólidas para el cálculo de fórmulas, la limpieza de datos (filas malformadas, datos basura), la creación de gráficos y la conversión de formatos, garantizando coherencia profesional de fuentes y cero errores de fórmula (#REF!, #DIV/0!) en los entregables.","fr":"Permet une interaction programmatique directe avec les fichiers Excel (.xlsx, .xlsm), CSV et TSV pour la lecture, l''écriture et la transformation complexe des données. Cette compétence offre des capacités robustes pour le calcul de formules, le nettoyage des données (lignes mal formées, données indésirables), la création de graphiques et la conversion de format, assurant une cohérence professionnelle des polices et zéro erreur de formule (#REF!, #DIV/0!) dans les livrables.","de":"Ermöglicht die direkte programmatische Interaktion mit Excel- (.xlsx, .xlsm), CSV- und TSV-Dateien zum Lesen, Schreiben und zur komplexen Datentransformation. Diese Fähigkeit bietet robuste Möglichkeiten für Formelberechnungen, Datenbereinigung (fehlerhafte Zeilen, unerwünschte Daten), Diagrammerstellung und Formatkonvertierung, wodurch professionelle Schriftartenkonsistenz und keine Formelfehler (#REF!, #DIV/0!) in den Lieferergebnissen gewährleistet werden.","pt":"Permite a interação programática direta com arquivos Excel (.xlsx, .xlsm), CSV e TSV para leitura, escrita e transformação complexa de dados. Esta habilidade fornece capacidades robustas para computação de fórmulas, limpeza de dados (linhas malformadas, dados inválidos), criação de gráficos e conversão de formato, garantindo consistência de fontes profissionais e zero erros de fórmula (#REF!, #DIV/0!) nos entregáveis.","ru":"Обеспечивает прямое программное взаимодействие с файлами Excel (.xlsx, .xlsm), CSV и TSV для чтения, записи и сложного преобразования данных. Этот навык предоставляет надежные возможности для вычисления формул, очистки данных (некорректные строки, нежелательные данные), построения графиков и преобразования форматов, гарантируя профессиональную согласованность шрифтов и отсутствие ошибок формул (#REF!, #DIV/0!) в результатах.","ar":"يتيح التفاعل البرمجي المباشر مع ملفات Excel (.xlsx و .xlsm) و CSV و TSV للقراءة والكتابة وتحويل البيانات المعقد. توفر هذه المهارة إمكانيات قوية لحساب الصيغ، وتنظيف البيانات (الصفوف غير المكتملة، البيانات غير المرغوب فيها)، وإنشاء المخططات، وتحويل التنسيق، مما يضمن اتساق الخطوط المحترفة وعدم وجود أخطاء في الصيغ (#REF! و #DIV/0!) في المخرجات."},"useCases":{"en":["Cleaning and restructuring messy tabular data files into proper spreadsheets","Computing formulas and generating charts from raw data","Converting between tabular file formats (e.g., CSV to XLSX)"],"zh":["将杂乱的表格数据文件清理并重构为适当的电子表格","根据原始数据计算公式并生成图表","在表格文件格式之间进行转换（例如，CSV 转 XLSX）"],"ja":["乱雑な表データファイルを適切なスプレッドシートにクリーニングおよび再構築する","生データから数式を計算しグラフを生成する","表ファイル形式間の変換（例：CSVからXLSXへ）"],"ko":["지저분한 테이블 형식 데이터 파일을 적절한 스프레드시트로 정리 및 재구성","원시 데이터에서 수식을 계산하고 차트 생성","테이블 파일 형식 간 변환(예: CSV를 XLSX로)"],"es":["Limpiar y reestructurar archivos de datos tabulares desordenados en hojas de cálculo adecuadas","Calcular fórmulas y generar gráficos a partir de datos sin procesar","Convertir entre formatos de archivo tabulares (por ejemplo, CSV a XLSX)"],"fr":["Nettoyer et restructurer des fichiers de données tabulaires désordonnés en feuilles de calcul appropriées","Calculer des formules et générer des graphiques à partir de données brutes","Convertir entre formats de fichiers tabulaires (par exemple, CSV vers XLSX)"],"de":["Bereinigen und Umstrukturieren von unordentlichen tabellarischen Datendateien in ordnungsgemäße Tabellenkalkulationen","Berechnen von Formeln und Erzeugen von Diagrammen aus Rohdaten","Konvertieren zwischen tabellarischen Dateiformaten (z.B. CSV zu XLSX)"],"pt":["Limpeza e reestruturação de arquivos de dados tabulares desorganizados em planilhas adequadas","Computação de fórmulas e geração de gráficos a partir de dados brutos","Conversão entre formatos de arquivos tabulares (por exemplo, CSV para XLSX)"],"ru":["Очистка и реструктуризация неупорядоченных файлов табличных данных в корректные электронные таблицы","Вычисление формул и создание графиков из необработанных данных","Преобразование между форматами табличных файлов (например, CSV в XLSX)"],"ar":["تنظيم و إعادة هيكلة ملفات البيانات الجدولية الفوضوية إلى جداول بيانات مناسبة","حساب الصيغ وإنشاء المخططات من البيانات الأولية","التحويل بين تنسيقات الملفات الجدولية (مثل، من CSV إلى XLSX)"]},"limitations":{"en":["Deliverable must be a spreadsheet file (excludes Word, HTML, Python scripts)","Cannot integrate with Google Sheets API","Requires exact format matching when updating existing templates"],"zh":["交付物必须是电子表格文件（不包括 Word、HTML、Python 脚本）","无法与 Google Sheets API 集成","更新现有模板时需要精确的格式匹配"],"ja":["納品物はスプレッドシートファイルである必要があります（Word、HTML、Pythonスクリプトは除外）","Google Sheets APIとの統合が不可能","既存のテンプレートを更新する際に正確なフォーマットの一致が必要"],"ko":["최종 결과물은 반드시 스프레드시트 파일이어야 함(Word, HTML, Python 스크립트 제외)","Google Sheets API와 통합 불가","기존 템플릿 업데이트 시 정확한 형식 일치 필요"],"es":["El entregable debe ser un archivo de hoja de cálculo (excluye Word, HTML, scripts de Python)","No puede integrarse con la API de Google Sheets","Requiere una coincidencia exacta de formato al actualizar plantillas existentes"],"fr":["Le livrable doit être un fichier de feuille de calcul (exclut Word, HTML, scripts Python)","Ne peut pas s''intégrer à l''API Google Sheets","Nécessite une correspondance exacte du format lors de la mise à jour de modèles existants"],"de":["Das Lieferergebnis muss eine Tabellenkalkulationsdatei sein (schließt Word, HTML, Python-Skripte aus)","Kann nicht mit der Google Sheets API integriert werden","Erfordert eine exakte Formatübereinstimmung beim Aktualisieren vorhandener Vorlagen"],"pt":["O entregável deve ser um arquivo de planilha (exclui Word, HTML, scripts Python)","Não pode integrar com a API do Google Sheets","Requer correspondência exata de formato ao atualizar modelos existentes"],"ru":["Результат должен быть файлом электронной таблицы (исключает Word, HTML, скрипты Python)","Не может интегрироваться с Google Sheets API","Требует точного соответствия формата при обновлении существующих шаблонов"],"ar":["يجب أن يكون المخرَج ملف جدول بيانات (يستثنى Word و HTML ونصوص Python)","لا يمكن التكامل مع واجهة برمجة تطبيقات Google Sheets","يتطلب مطابقة تنسيق بدقة عند تحديث القوالب الحالية"]},"version":4},"contentHash":"dd316db77